-- Seed Saints
INSERT INTO saints (name, slug, tagline, description, prayer, feast_day, emoji, trait_contemplative, trait_charitable, trait_intellectual, trait_courageous, trait_joyful, trait_mystical) VALUES
('Francis of Assisi', 'francis-of-assisi', 'Lover of creation and the poor', 'St. Francis of Assisi abandoned wealth to embrace radical poverty and joy. He saw God in every creature, preached to birds, and bore the stigmata. His life calls you to simplicity, compassion for the marginalized, and finding the sacred in nature.', 'Lord, make me an instrument of your peace. Where there is hatred, let me sow love; where there is injury, pardon; where there is doubt, faith.', 'October 4', '🐦', 3, 9, 2, 5, 8, 4),

('Teresa of Avila', 'teresa-of-avila', 'Mystic of the Interior Castle', 'St. Teresa of Avila was a Carmelite reformer and Doctor of the Church who mapped the soul''s journey to God through her Interior Castle. Practical yet profoundly mystical, she combined administrative genius with ecstatic prayer.', 'Let nothing disturb you. Let nothing frighten you. All things are passing away. God never changes. Patience obtains all things.', 'October 15', '🏰', 8, 4, 7, 6, 5, 9),

('Thomas Aquinas', 'thomas-aquinas', 'The Angelic Doctor', 'St. Thomas Aquinas harmonized faith and reason in his monumental Summa Theologica. A Dominican friar of towering intellect, he showed that truth is one — whether discovered through philosophy or revelation. Near the end of his life, a mystical experience led him to call his writings "mere straw."', 'Grant me, O Lord my God, a mind to know you, a heart to seek you, wisdom to find you, conduct pleasing to you, faithful perseverance in waiting for you, and a hope of finally embracing you.', 'January 28', '📚', 7, 3, 10, 2, 3, 6),

('Joan of Arc', 'joan-of-arc', 'The Maid of Orleans', 'St. Joan of Arc heard the voices of saints calling her to save France. A teenage peasant girl who led armies, she combined unwavering faith with extraordinary courage. Betrayed and martyred at 19, she never denied her divine mission.', 'I am not afraid. I was born to do this.', 'May 30', '⚔️', 3, 4, 2, 10, 5, 7),

('Mother Teresa', 'mother-teresa', 'Saint of the Gutters', 'St. Mother Teresa of Calcutta saw the face of Christ in the poorest of the poor. She founded the Missionaries of Charity and spent decades serving the dying and destitute in Kolkata, even while experiencing a prolonged dark night of the soul.', 'If you judge people, you have no time to love them. Spread love everywhere you go. Let no one ever come to you without leaving happier.', 'September 5', '🙏', 4, 10, 3, 7, 5, 4),

('Therese of Lisieux', 'therese-of-lisieux', 'The Little Flower', 'St. Therese of Lisieux discovered her "Little Way" — doing small things with great love. A Carmelite nun who died at 24, her spiritual autobiography became one of the most influential books in Catholic history. She is patron saint of missionaries despite never leaving her convent.', 'Miss no single opportunity of making some small sacrifice, here by a smiling look, there by a kindly word; always doing the smallest right and doing it all for love.', 'October 1', '🌹', 6, 7, 3, 3, 9, 5),

('Augustine of Hippo', 'augustine-of-hippo', 'Restless Heart', 'St. Augustine lived a wild youth before his dramatic conversion, famously praying "Grant me chastity — but not yet." He became one of the greatest theologians in history, exploring grace, free will, and the nature of God with unmatched depth and honesty in his Confessions.', 'You have made us for yourself, O Lord, and our hearts are restless until they rest in you.', 'August 28', '🔥', 7, 4, 9, 4, 4, 6),

('Maximilian Kolbe', 'maximilian-kolbe', 'Knight of the Immaculata', 'St. Maximilian Kolbe was a Franciscan friar who volunteered to die in place of a stranger at Auschwitz. A pioneer of Catholic media and devotion to Mary, he showed that the greatest love is laying down one''s life for another.', 'The most deadly poison of our times is indifference. Let us not be indifferent.', 'August 14', '✝️', 4, 8, 5, 10, 3, 4),

('Hildegard of Bingen', 'hildegard-of-bingen', 'Sibyl of the Rhine', 'St. Hildegard of Bingen was a Benedictine abbess, composer, philosopher, mystic, and polymath of the 12th century. She wrote on theology, natural science, and medicine, composed hauntingly beautiful music, and experienced vivid mystical visions from childhood.', 'Dare to declare who you are. It is not far from the shores of silence to the boundaries of speech.', 'September 17', '🎵', 7, 4, 8, 5, 5, 9),

('Philip Neri', 'philip-neri', 'The Apostle of Joy', 'St. Philip Neri was the joyful heart of Counter-Reformation Rome. Known for his humor, pranks, and ecstatic prayer, he founded the Oratory and drew people to God through laughter and friendship. His heart literally enlarged from the force of divine love.', 'A joyful heart is more easily made perfect than a downcast one. Cheerfulness strengthens the heart and helps us persevere.', 'May 26', '😄', 3, 6, 4, 3, 10, 5),

('Padre Pio', 'padre-pio', 'Bearer of the Wounds', 'St. Padre Pio was a Capuchin friar who bore the stigmata for 50 years. Known for his gift of reading souls in confession, bilocation, and healing, he endured immense suffering with patience and devotion. Millions sought his counsel and intercession.', 'Pray, hope, and don''t worry. Worry is useless. God is merciful and will hear your prayer.', 'September 23', '🩸', 8, 5, 3, 6, 2, 10),

('Catherine of Siena', 'catherine-of-siena', 'Doctor of the Church and Diplomat', 'St. Catherine of Siena was a Dominican tertiary who boldly advised popes and princes. A mystic who experienced a spiritual marriage with Christ, she combined deep contemplation with fearless political action, helping bring the papacy back to Rome.', 'Be who God meant you to be, and you will set the world on fire.', 'April 29', '👑', 7, 5, 7, 8, 4, 8);

