-- Imported from saints-data.csv
INSERT INTO saints (name, slug, tagline, description, prayer, feast_day, emoji, trait_contemplative, trait_charitable, trait_intellectual, trait_courageous, trait_joyful, trait_mystical) VALUES
('Peter', 'peter', 'St. Peter is recognized as the first pope and a leader among the apostles.', 'Born as Simon in Galilee, he was a fisherman before becoming a devoted follower of Jesus Christ. Peter played a crucial role in the early Church, ultimately facing martyrdom in Rome for his steadfast faith. His legacy as the first pope and his role in spreading Christianity have made him a pillar of the Catholic Church.', 'You are the Messiah, the Son of the living God.', 'June 29', NULL, 3, 5, 3, 10, 1, 8),

('Paul', 'paul', 'A key figure in the early Christian church who spread the Gospel to the Gentiles.', 'St. Paul, originally known as Saul of Tarsus, was a zealous persecutor of Christians before experiencing a profound conversion on the road to Damascus. He became one of Christianity''s most influential apostles, traveling extensively to establish churches and writing letters that form a significant portion of the New Testament. His theological insights and teachings continue to shape Christian doctrine and practice today.', 'I have become all things to all people, that I might by all means save some.', 'June 29', NULL, 1, 1, 10, 6, 4, 1),

('Mary Magdalene', 'mary-magdalene', 'The first witness to the Resurrection of Jesus and a devoted follower.', 'St. Mary Magdalene is celebrated as a pivotal figure in Christianity, known for her unwavering support of Jesus throughout His ministry. She uniquely witnessed His crucifixion and was the first to encounter the resurrected Christ, tasked with sharing the good news with the apostles. Her life reflects transformation, faith, and forgiveness, inspiring countless believers to follow her example of devotion.', 'I have seen the Lord.', 'July 22', NULL, 4, 8, 1, 4, 1, 10),

('Joseph', 'joseph', 'The earthly protector of Jesus and spouse of the Virgin Mary.', 'St. Joseph is revered as the humble and steadfast foster father of Jesus Christ and the devoted husband of the Virgin Mary. Known for his unwavering faith and dedication to his family, he is a model for all workers and fathers. His life exemplifies quiet strength, compassion, and virtue amidst life''s challenges.', 'I have chosen you, Joseph, to be the guardian of my son.', 'March 19', NULL, 3, 10, 1, 1, 1, 3),

('Clare of Assisi', 'clare-of-assisi', 'Founder of the Order of Poor Ladies, known as the Poor Clares, and devoted follower of St. Francis of Assisi.', 'St. Clare of Assisi was a noblewoman who became a pioneering figure in the Franciscan movement after hearing St. Francis preach. She founded the Order of Poor Ladies, which later became known as the Poor Clares, emphasizing a life of poverty and community. Clare is remembered for her deep spirituality, her commitment to her faith, and her role in promoting the values of humility and charity.', 'I desire to glorify God as long as I have breath.', 'August 11', NULL, 2, 10, 1, 1, 1, 2),

('Anthony of Padua', 'anthony-of-padua', 'A revered Franciscan preacher known for his powerful sermons and miracles.', 'St. Anthony of Padua was a Portuguese friar who became a significant figure in the Franciscan Order. Renowned for his profound preaching and connection to the poor, he traveled widely across Italy, touching the lives of many. His legacy is celebrated globally, especially for his intercessions in finding lost items and his compassion for those in need.', 'Actions speak louder than words', 'June 13', NULL, 1, 10, 4, 1, 3, 1),

('Teresa of Ávila', 'teresa-of-vila', 'A prominent Spanish mystic and reformer of the Carmelite Order.', 'St. Teresa of Ávila was a pioneering figure in the reform of the Carmelite Order, emphasizing a return to a life of prayer and contemplation. Her mystical experiences and writings, including ''The Interior Castle'', have had a profound influence on Christian spirituality. Canonized in 1614 and declared a Doctor of the Church in 1970, she remains a vital figure in the Catholic tradition.', 'Meditation is an act of love.', 'October 15', NULL, 4, 1, 10, 3, 1, 4),

('Ignatius of Loyola', 'ignatius-of-loyola', 'Founder of the Society of Jesus and author of the ''Spiritual Exercises''.', 'St. Ignatius of Loyola was a Spanish knight who experienced a profound spiritual conversion during his recovery from battle injuries. He founded the Society of Jesus in 1534, focusing on education, missionary work, and spiritual exploration. His influential work, the ''Spiritual Exercises'', guides countless individuals in meditation and prayer.', 'If God is for us, who can be against us?', 'July 31', NULL, 3, 1, 10, 10, 10, 3),

('Francis Xavier', 'francis-xavier', 'St. Francis Xavier was a pioneering Jesuit missionary who played a vital role in spreading Christianity across Asia, particularly in India and Japan.', 'St. Francis Xavier was one of the founding members of the Society of Jesus. He traveled extensively in his quest to evangelize and baptized thousands, facing great hardships. His commitment to his faith and dedication to spreading the message of Christ has made him one of the most revered missionaries in history.', 'The harvest is great, but the laborers are few.', 'December 3', NULL, 2, 6, 1, 10, 6, 4),

('John of the Cross', 'john-of-the-cross', 'A Carmelite mystic and poet, St. John of the Cross is renowned for his profound spiritual writings, particularly ''Dark Night of the Soul''.', 'St. John of the Cross was a Spanish Carmelite friar and priest who played a crucial role in the reform of the Carmelite Order. He is celebrated for his deep mystical insights and poetic expressions of spiritual union with God. His works continue to inspire countless individuals seeking a deeper relationship with the divine.', 'In the evening of life, we will be judged on love alone.', 'December 14', NULL, 10, 1, 1, 1, 7, 8),

('Thérèse of Lisieux', 'th-r-se-of-lisieux', 'Carmelite nun renowned for her ''Little Way'' of spiritual childhood.', 'St. Thérèse of Lisieux, also known as the ''Little Flower,'' lived a life of profound faith and simplicity within the cloistered walls of a Carmelite monastery. Her writings, especially ''Story of a Soul,'' reveal her deep love for God and her commitment to the ''Little Way,'' which emphasizes love and trust in God''s grace over grand acts. Canonized in 1925, she is one of the most beloved saints in the Catholic Church and was declared a Doctor of the Church in 1997.', 'I will spend my heaven doing good on earth.', 'October 1', NULL, 10, 10, 1, 5, 8, 3),

('Patrick', 'patrick', 'St. Patrick is renowned for bringing Christianity to Ireland and using the shamrock to explain the Holy Trinity.', 'A bishop and missionary, St. Patrick played a crucial role in converting the Irish to Christianity during the 5th century. According to legend, he drove snakes out of Ireland, symbolizing the eradication of paganism. His teachings and use of everyday symbols made the Christian faith more accessible to the Irish people.', 'Be still and know that I am God.', 'March 17', NULL, 2, 8, 1, 10, 3, 1),

('Benedict', 'benedict', 'Founder of the Benedictine Order and author of the Rule of St. Benedict.', 'St. Benedict, born in Italy around 480, is renowned for establishing monasticism in the West through his influential Rule, which emphasizes balance, moderation, and the quest for God. His work laid the foundation for Western Christian monastic life, and his teachings continue to inspire countless individuals seeking spiritual growth and community living. Revered by many as the father of monasticism, he is celebrated for his dedication to prayer and work.', 'If you are a man of peace, you can never be a man of quarrels.', 'July 11', NULL, 8, 4, 10, 2, 2, 4),

('Scholastica', 'scholastica', 'Lifelong dedication to monastic life and influence on the Benedictine order.', 'St. Scholastica was a devoted follower of Christ and the twin sister of St. Benedict, the founder of Western monasticism. She established the Women''s Benedictine order and dedicated her life to prayer, teaching, and the spiritual growth of her sisters. Her life exemplified the harmony of contemplation and service, influencing many within the faith.', 'I beg you, do not deprive me of your presence.', 'February 10', NULL, 2, 10, 1, 2, 6, 6),

('Gregory the Great', 'gregory-the-great', 'Pope who significantly reformed the liturgy and initiated missions to convert pagans.', 'St. Gregory the Great was the 64th pope, serving from 590 to 604 AD. He was known for his theological writings and the Gregorian Chant, which influenced Western liturgical music. His leadership and reforms helped shape the Roman Catholic Church during a time of political instability and cultural change.', 'In all things, may your glory be reflected in us.', 'September 3', NULL, 1, 10, 10, 10, 7, 10),

('Boniface', 'boniface', 'The Apostle to the Germans, renowned for his missionary work and martyrdom.', 'St. Boniface, originally named Wynfrith, dedicated his life to converting the Germanic tribes to Christianity. He is celebrated for his unwavering faith and was martyred in Friesland while on a mission to strengthen the church. His legacy includes the establishment of monasteries and the reform of church practices in the region.', 'The one who bears the torch of Christ will break the darkness that surrounds us.', 'June 5', NULL, 2, 5, 1, 10, 3, 3),

('Nicholas', 'nicholas', 'A beloved bishop renowned for his acts of charity and compassion.', 'St. Nicholas, the Bishop of Myra, was known for his unwavering generosity and dedication to serving the needy. His legendary deeds of secret gift-giving laid the foundation for modern traditions of Santa Claus. Celebrated for his compassion, he is a beloved figure among Christians, deeply revered in both Western and Eastern traditions.', 'I will not let my hand fall away from what I serve.', 'December 6', NULL, 1, 10, 3, 1, 1, 1),

('George', 'george', 'St. George is revered as a soldier and martyr, famous for slaying a dragon as a symbol of good triumphing over evil.', 'St. George, a Roman soldier of Greek origin, is one of Christianity’s most venerated saints. He is best known for his legendary battle against a dragon, a tale that symbolizes the struggle between faith and adversity. His courage in martyrdom has made him a patron saint of various groups, inspiring many through the centuries.', 'I will not be ashamed, for I am a soldier of Christ.', 'April 23', NULL, 1, 1, 1, 10, 1, 2),

('Lucy', 'lucy', 'A brave virgin martyr whose name means ''light'', symbolizing her faith amid persecution.', 'St. Lucy was a Christian martyr who lived during the Diocletian persecution in the early 4th century. She is remembered for her unwavering faith and dedication to God, which ultimately led to her tragic death. Her story serves as an inspiration to many, especially those enduring struggles related to vision and clarity.', 'I choose to be a Christian, and I will endure any suffering for my faith.', 'December 13', NULL, 2, 5, 1, 10, 3, 3),

('Sebastian', 'sebastian', 'St. Sebastian was a Christian martyr who inspired many through his unwavering faith and courage.', 'St. Sebastian was born in Rome and became a soldier of the Roman Empire. His strong Christian faith compelled him to secretly help imprisoned Christians, which ultimately led to his martyrdom. He is often depicted tied to a tree and shot with arrows, symbolizing his steadfastness in the face of persecution.', 'Your faith is your shield, and your conviction is your sword.', 'January 20', NULL, 1, 1, 1, 10, 1, 2),

('Cecilia', 'cecilia', 'A virgin martyr who is celebrated for her unwavering faith and her musical devotion to God.', 'St. Cecilia is revered as the patron saint of musicians, reflecting her enduring legacy as a symbol of music and art. According to tradition, she sang to God even during her martyrdom, exemplifying her deep faith and commitment. Her life and death inspire countless artists and believers to express their faith through music and creativity.', 'From the moment of my birth, I have been destined to be in the presence of God.', 'November 22', NULL, 2, 1, 1, 6, 4, 10),

('Lawrence', 'lawrence', 'Deacon martyred on a gridiron for his faith and generosity.', 'St. Lawrence was a devoted deacon in Rome who became known for his unwavering faith and service to the poor. He bravely faced his martyrdom around the year 258, famously being roasted alive on a gridiron while expressing his unshakeable faith. His legacy continues to inspire acts of charity and comedic humility in the face of adversity.', 'The church is truly rich, not because it has a lot of money, but because it has the wealth of the faith of its people.', 'August 10', NULL, 3, 10, 1, 7, 1, 10),

('Stephen', 'stephen', 'St. Stephen is recognized as the first Christian martyr, who was stoned to death for his faith.', 'St. Stephen was one of the first seven deacons appointed in the early Church, chosen for his faith and wisdom. His unwavering devotion to Christ and his eloquent defense of the faith led to his martyrdom outside Jerusalem, making him a powerful symbol of conviction. His legacy inspires countless Christians today to stand firm in their beliefs, even in the face of persecution.', 'Behold, I see the heavens opened and the Son of Man standing at the right hand of God.', 'December 26', NULL, 2, 6, 1, 6, 1, 10),

('Dominic', 'dominic', 'St. Dominic was the founder of the Dominican Order and is renowned for promoting the Rosary.', 'St. Dominic was born in Spain and dedicated his life to preaching and educating in the faith. He founded the Order of Preachers, known for their commitment to study and contemplation along with active ministry. His legacy persists through the widespread devotion to the Rosary and the work of Dominicans worldwide.', 'In all things, may God be glorified.', 'August 8', NULL, 10, 3, 1, 3, 5, 5),

('Bernard of Clairvaux', 'bernard-of-clairvaux', 'St. Bernard of Clairvaux was a prominent Cistercian abbot and influential theologian known for his role in promoting the Second Crusade.', 'St. Bernard of Clairvaux was born in 1090 in France, becoming a prominent Cistercian abbot whose spiritual leadership shaped medieval spirituality. He was instrumental in promoting the Second Crusade, emphasizing the importance of spiritual warfare alongside physical battles. Renowned for his eloquent writings and deep contemplation, Bernard left a lasting legacy on Christian theology and monastic life.', 'What we love, we shall never lose.', 'August 20', NULL, 4, 1, 10, 3, 4, 1),

('Bonaventure', 'bonaventure', 'St. Bonaventure was a prominent Franciscan theologian and a Doctor of the Church.', 'St. Bonaventure, born in Italy, was a central figure in the development of Franciscan theology. He served as the Minister General of the Franciscan Order and became a cardinal, deeply influencing the Church with his writings and teachings. As a Doctor of the Church, he is revered for his intellectual contributions and spiritual guidance.', 'Devotion without knowledge is like a flame without light.', 'July 15', NULL, 3, 5, 10, 3, 3, 1),

('Albertus Magnus', 'albertus-magnus', 'St. Albertus Magnus was a renowned Dominican scholar and a pioneer in the integration of faith and reason.', 'St. Albertus Magnus, known as the Universal Doctor, made significant contributions to various fields, including biology, chemistry, and philosophy. He was a mentor to St. Thomas Aquinas and emphasized the importance of observation and reason in understanding the natural world. His blend of scientific inquiry and theological insight set the stage for later developments in both areas.', 'We must love our neighbor as being made in the image of God and as an object of His love.', 'November 15', NULL, 1, 4, 10, 1, 1, 6),

('Louis IX', 'louis-ix', 'St. Louis IX was a devout king known for his strong sense of justice and leading two crusades.', 'St. Louis IX ruled as King of France from 1226 until his death in 1270, exemplifying the role of a monarch devoted to his faith and his people. He famously led the Seventh and Eighth Crusades and worked tirelessly to promote peace and social justice throughout his realm. His dedication to charity and the care of the poor earned him lasting reverence in the Catholic Church, ultimately leading to his canonization in 1297.', 'If I could be king of France on such conditions as these, I would be satisfied.', 'August 25', NULL, 5, 5, 3, 5, 1, 10),

('Elizabeth of Hungary', 'elizabeth-of-hungary', 'A princess known for her extraordinary charity and care for the poor.', 'Born in 1207, Elizabeth was the daughter of the King of Hungary and chose to live a life of poverty despite her royal status. She devoted herself to serving the sick and the poor, famously founding a hospital and providing for many through her own resources. Her unwavering faith and commitment to charity made her a beloved figure, and she was canonized just four years after her death in 1231.', 'My Lord and my God, I will serve you with a love that knows no bounds.', 'November 17', NULL, 2, 10, 1, 1, 1, 2),

('Margaret of Scotland', 'margaret-of-scotland', 'Reforming the Scottish church and her dedication to helping the poor.', 'St. Margaret of Scotland was an English princess who became queen consort of Scotland in the 11th century. She was instrumental in reforming the Scottish church and was known for her unwavering charity towards the poor and her dedication to education and welfare. Her legacy continues to inspire many, emphasizing the power of compassion and service to others.', 'What you do for the least of these, you do for me.', 'November 16', NULL, 3, 8, 3, 5, 1, 10),

('Bridget of Sweden', 'bridget-of-sweden', 'A mystic and founder of the Bridgettine Order who received profound spiritual revelations.', 'St. Bridget of Sweden was a noblewoman who devoted her life to prayer and service after the death of her husband. She received numerous visions and revelations that guided her in her mission to reform the Church and address social injustices. Her legacy includes the establishment of the Bridgettine Order, which emphasizes community life and dedication to education and care for the poor.', 'I am not asking you to make me happy, but to help me accept my sufferings.', 'July 23', NULL, 2, 6, 1, 6, 4, 10),

('Catherine of Alexandria', 'catherine-of-alexandria', 'A Christian martyr known for her intellect and eloquent debates with pagan philosophers.', 'St. Catherine of Alexandria was a learned young woman who bravely debated the finest pagan philosophers of her time. After refusing to renounce her faith, she was imprisoned and tortured, ultimately facing martyrdom on an iron wheel. Her steadfast commitment to her beliefs has made her an enduring symbol of wisdom and courage in the face of oppression.', 'O God, You are the light of my mind and the guide of my soul.', 'November 25', NULL, 1, 3, 10, 8, 3, 1),

('Martin of Tours', 'martin-of-tours', 'A soldier who became a compassionate bishop known for his acts of charity.', 'St. Martin of Tours was born into a Roman military family in what is now Hungary. He famously tore his military cloak in two to share with a beggar during a snowstorm, a gesture that would define his life as one of charity and leadership. Later, he became the Bishop of Tours and played a significant role in the spread of Christianity in Gaul.', 'I am a soldier of Christ, I cannot fight.', 'November 11', NULL, 1, 10, 1, 5, 3, 1),

('Ambrose', 'ambrose', 'St. Ambrose was a key figure in the early Church, known for his role as Bishop of Milan and his influence on St. Augustine.', 'St. Ambrose, born around 340 in Italy, became the Bishop of Milan and was instrumental in the development of early Church doctrine. He is renowned for his preaching and theological writings, which helped shape Christian thought during a pivotal time in history. His efforts in catechesis and evangelization significantly influenced many, including the conversion of St. Augustine.', 'Where there is no struggle, there is no virtue.', 'December 7', NULL, 1, 4, 10, 6, 1, 1),

('Jerome', 'jerome', 'Translator of the Bible into Latin, known as the Vulgate.', 'St. Jerome was a distinguished theologian and scholar known for his translation of the Bible into Latin, which became known as the Vulgate. He spent a significant part of his life in a monastery in Bethlehem, where he dedicated himself to the study of scripture and wrote extensively on theological matters. His profound insights and ascetic lifestyle made him a pivotal figure in the development of Christian doctrine and biblical scholarship.', 'Ignorance of scripture is ignorance of Christ.', 'September 30', NULL, 1, 3, 10, 5, 1, 2),

('Monica', 'monica', 'She is celebrated as the mother of St. Augustine, who underwent a remarkable conversion due in large part to her persistent prayers.', 'St. Monica was a woman of profound faith and unwavering resolve, dedicated to the conversion of her wayward son, Augustine. Through years of heartfelt prayers and patience, she witnessed his transformation into one of the Church''s greatest saints. Her life story exemplifies the power of maternal love and the importance of hope in times of struggle.', 'Nothing is far from God.', 'August 27', NULL, 2, 6, 1, 1, 1, 10),

('John Chrysostom', 'john-chrysostom', 'St. John Chrysostom was a prominent archbishop and influential preacher known for his exceptional eloquence.', 'St. John Chrysostom, born in Antioch, became renowned for his remarkable preaching abilities, earning him the title ''Chrysostom'' which means ''Golden-Mouthed.'' As Archbishop of Constantinople, he advocated for the poor and sought reforms in the Christian community, often provoking the ire of powerful figures. His theological contributions and writings, particularly on the Divine Liturgy and moral living, cemented his legacy as a Doctor of the Church.', 'The devil is afraid of us when we pray and make sacrifices.', 'September 13', NULL, 1, 5, 10, 7, 3, 1),

('Athanasius', 'athanasius', 'A champion of Trinitarian orthodoxy and a key figure in early Christian theology.', 'St. Athanasius was a fourth-century bishop of Alexandria who ardently defended the doctrine of the Trinity against the Arian heresy. Renowned for his intellectual rigor and strong leadership, he faced numerous exiles for his beliefs and played a critical role in the Nicene Council. His theological writings and pastoral guidance have significantly shaped Christian thought and practice.', 'The Son of God became man so that we might become God.', 'May 2', NULL, 1, 1, 10, 6, 1, 1),

('Cyril and Methodius', 'cyril-and-methodius', 'Evangelizing the Slavic peoples and creating the Cyrillic alphabet.', 'St. Cyril and Methodius were two brothers from Greece who played a pivotal role in spreading Christianity among the Slavic nations. They are credited with developing the Glagolitic script, which was a precursor to the Cyrillic alphabet, allowing Slavic peoples to read and write in their own language. Their dedication to education and evangelization laid the foundation for the rich Christian heritage of Eastern Europe.', 'Let us teach the faith to all those who are far from the truth.', 'February 14', NULL, 1, 10, 8, 4, 2, 2),

('John Vianney', 'john-vianney', 'St. John Vianney was a humble parish priest renowned for his dedication to the sacrament of confession and pastoral care.', 'St. John Vianney, also known as the Curé of Ars, dedicated his life to the spiritual well-being of his parishioners in Ars, France. His exceptional ability in hearing confessions attracted pilgrims from all over Catholic Europe, who sought his counsel and spiritual guidance. Despite facing numerous challenges, including illness and a lack of formal education, his unwavering faith and pastoral commitment transformed countless lives.', 'The priest is not a priest for himself, he is a priest for you.', 'August 4', NULL, 4, 10, 6, 4, 1, 4),

('Bernadette', 'bernadette', 'A visionary who reported 18 apparitions of the Virgin Mary in Lourdes.', 'St. Bernadette Soubirous was a simple peasant girl who experienced a series of visions of the Blessed Virgin Mary in a grotto near Lourdes, France. Her encounters led to the establishment of Lourdes as a major pilgrimage site, where many seek healing and solace. Despite her humble origins, her unwavering faith and deep spirituality left a lasting impact on the Church and the world.', 'I cannot promise you happiness in this life, but I can promise you happiness in the next.', 'April 16', NULL, 2, 3, 1, 3, 1, 10),

('John Bosco', 'john-bosco', 'Founder of the Salesian Society, dedicated to the education and welfare of young people.', 'St. John Bosco, born in Italy, was a visionary educator who dedicated his life to uplifting underprivileged youth through practical education and spiritual guidance. He founded the Salesians, an order committed to providing education and support to boys in need. His innovative teaching methods and heartfelt approach have left a lasting impact on countless lives across the globe.', 'Run, mend your nets, and do not forget that your net is your life.', 'January 31', NULL, 1, 10, 1, 5, 5, 5),

('Vincent de Paul', 'vincent-de-paul', 'He dedicated his life to serving the poor and founded the Vincentians and the Daughters of Charity.', 'St. Vincent de Paul was a French priest renowned for his commitment to helping the impoverished and vulnerable. He established the Congregation of the Mission and the Daughters of Charity, organizations that continue to serve communities worldwide. His legacy of compassion and service inspired many to dedicate their lives to acts of charity.', 'It''s not enough to give from our abundance', 'September 27', NULL, 1, 10, 1, 2, 2, 1),

('Louise de Marillac', 'louise-de-marillac', 'Co-founder of the Daughters of Charity alongside St. Vincent de Paul.', 'St. Louise de Marillac was a pioneering figure in the 17th century, dedicated to serving the poor and marginalized in society. She established the Daughters of Charity to further St. Vincent de Paul''s mission of charitable service and education. Her legacy continues to inspire countless individuals in acts of compassion and social justice worldwide.', 'We must strive to be all things to all people.', 'March 15', NULL, 1, 10, 1, 1, 1, 3),

('Margaret Mary Alacoque', 'margaret-mary-alacoque', 'St. Margaret Mary Alacoque is renowned for her role in promoting the devotion to the Sacred Heart of Jesus.', 'Born in France, St. Margaret Mary Alacoque was a nun of the Visitation Order who received mystical revelations about the love of Jesus towards humanity. Her profound experiences led her to advocate for the devotion to the Sacred Heart, emphasizing the importance of Christ''s love and mercy. She founded the First Friday devotion and contributed to the establishment of the Feast of the Sacred Heart in the Church calendar.', 'Behold this Heart which has loved men so much.', 'October 16', NULL, 3, 4, 1, 1, 1, 10),

('John of God', 'john-of-god', 'St. John of God is revered for founding the Brothers Hospitallers, dedicated to caring for the sick.', 'Born in Portugal and later moved to Spain, St. John of God experienced a dramatic conversion that led him to dedicate his life to the service of the needy. He established a religious order that focused on providing compassionate care to the sick and suffering, emphasizing the dignity of each person. His legacy continues through the work of the Brothers Hospitallers, who carry on his mission of love and healing.', 'Be careful to keep the love of Christ always in your heart.', 'March 8', NULL, 1, 10, 1, 3, 3, 1),

('Camillus de Lellis', 'camillus-de-lellis', 'St. Camillus de Lellis founded the Order of Servants of the Sick, revolutionizing hospital care.', 'St. Camillus de Lellis, born in 1550 in Italy, led a life dedicated to the sick and suffered from his own health issues that deepened his compassion. After a spiritual conversion, he founded the Camillians, a religious order committed to healthcare service in hospitals and communities. His legacy continues to inspire modern nursing practices and the ethical treatment of patients.', 'The sick are my masters, and it is my duty to serve them with great joy.', 'July 14', NULL, 1, 10, 1, 1, 1, 3),

('Alphonsus Liguori', 'alphonsus-liguori', 'St. Alphonsus Liguori was a renowned moral theologian and the founder of the Redemptorist congregation.', 'Born in Naples, Italy, St. Alphonsus Liguori was a brilliant scholar who dedicated his life to serving the poor and the sick. He became known for his profound moral teachings and pastoral care, founding the Congregation of the Most Holy Redeemer to evangelize the poor. His legacy as a Doctor of the Church continues to inspire those devoted to moral theology and spiritual growth.', 'It is better to be a sinner who seeks God than a righteous person who is indifferent to God.', 'August 1', NULL, 3, 10, 4, 1, 1, 3),

('Frances Xavier Cabrini', 'frances-xavier-cabrini', 'She was the first naturalized American citizen to be canonized as a saint.', 'St. Frances Xavier Cabrini, known as Mother Cabrini, dedicated her life to serving Italian immigrants in the United States. She founded the Missionary Sisters of the Sacred Heart, establishing numerous schools, hospitals, and orphanages throughout the country. Her unwavering spirit and commitment to her mission earned her the title of the patron saint of immigrants.', 'It is not you who will be speaking', 'November 13', NULL, 1, 10, 1, 4, 1, 4),

('Elizabeth Ann Seton', 'elizabeth-ann-seton', 'St. Elizabeth Ann Seton is recognized as the first native-born American saint and the founder of the Sisters of Charity.', 'St. Elizabeth Ann Seton was a devoted wife and mother who faced personal tragedies, including the loss of her husband. She responded to her call to serve God by founding the first Catholic school in the United States and established the Sisters of Charity. Her legacy continues in the mission of education and charitable service throughout the country.', 'If I cannot see God in the ways I want, I take care to see Him in the way He is.', 'January 4', NULL, 1, 10, 1, 6, 3, 1),

('Katharine Drexel', 'katharine-drexel', 'Katharine Drexel founded the Sisters of the Blessed Sacrament and dedicated her life to serving Native Americans and African Americans.', 'St. Katharine Drexel was a wealthy heiress who chose to dedicate her fortune to the service of marginalized communities. She established a religious order and helped to found over 60 schools, significantly advancing education for Native Americans. Her commitment to social justice and racial equality has inspired countless individuals in their pursuit of justice.', 'I would rather spend my time in pursuing a great cause than in being a collector of antiques.', 'March 3', NULL, 1, 10, 3, 7, 1, 10),

('Teresa of Calcutta', 'teresa-of-calcutta', 'St. Teresa of Calcutta is renowned for her unwavering dedication to serving the poorest of the poor through the Missionaries of Charity.', 'St. Teresa of Calcutta, born in Albania, dedicated her life to caring for the destitute and dying in the streets of Calcutta, India. She founded the Missionaries of Charity in 1950, which has grown to include thousands of members worldwide. Her selfless acts of love and service earned her the Nobel Peace Prize in 1979, but she always emphasized that the true reward was in serving God through others.', 'Not all of us can do great things. But we can do small things with great love.', 'September 5', NULL, 3, 7, 3, 7, 1, 10),

('Edith Stein', 'edith-stein', 'A Jewish philosopher who converted to Catholicism, became a Carmelite nun, and was martyred at Auschwitz.', 'St. Edith Stein, also known as St. Teresa Benedicta of the Cross, was a brilliant philosopher and theologian whose writings recognized the dignity of women in the Church. After converting from Judaism to Catholicism, she joined the Carmelite order and devoted her life to prayer and teaching. Tragically, she was arrested during World War II and died in Auschwitz, yet her legacy continues to inspire many today.', 'To be a saint is to be a lover of the truth.', 'August 9', NULL, 2, 6, 10, 6, 1, 6),

('John Paul II', 'john-paul-ii', 'Pope for 27 years, instrumental in the fall of communism, and founder of World Youth Day.', 'St. John Paul II, born Karol Wojtyła, was the first non-Italian pope in 455 years and served from 1978 to 2005. He played a crucial role in the downfall of communism in Eastern Europe, advocating for human dignity and rights. His legacy includes a profound pastoral outreach, particularly to the youth, and a commitment to ecumenism and interfaith dialogue.', 'Do not be afraid to open the doors to Christ.', 'October 22', NULL, 2, 6, 1, 6, 4, 10),

('Josemaría Escrivá', 'josemar-a-escriv', 'Founder of Opus Dei and advocate for finding holiness in everyday life.', 'St. Josemaría Escrivá was a Spanish priest who dedicated his life to encouraging people to pursue holiness through their daily work. He founded Opus Dei in 1928, promoting the idea that everyone is called to be a saint, regardless of their profession. His teachings continue to inspire countless individuals worldwide to integrate their faith into every aspect of their lives.', 'We cannot love God unless we love our neighbor.', 'June 26', NULL, 3, 10, 1, 8, 10, 3),

('Gianna Molla', 'gianna-molla', 'A devoted physician who chose her child''s life over her own during childbirth.', 'St. Gianna Molla was an Italian pediatrician who dedicated her life to helping the sick and promoting family values. During her pregnancy, she faced a life-threatening medical condition but chose to prioritize her baby''s survival, ultimately sacrificing her own life. Today, she is celebrated as a model of selfless love and maternal sacrifice.', 'If you are what you should be, you will set the whole world ablaze!', 'April 28', NULL, 1, 10, 1, 4, 1, 1),

('Teresa Benedicta', 'teresa-benedicta', 'A Jewish convert to Catholicism who became a Carmelite philosopher and was martyred at Auschwitz.', 'Born Edith Stein in Germany, she was a brilliant philosopher who converted to Catholicism and took the name Teresa Benedicta of the Cross. As a Carmelite nun, she dedicated her life to prayer and contemplation before ultimately being arrested and sent to Auschwitz during World War II for her Jewish heritage. Her profound writings on faith and philosophy have inspired countless individuals in their spiritual journeys.', 'The nation doesn’t simply live in its people', 'August 9', NULL, 2, 6, 10, 10, 1, 1),

('Rose of Lima', 'rose-of-lima', 'Known as the first indigenous saint of the Americas, St. Rose of Lima is celebrated for her deep spirituality and commitment to serving the poor.', 'Born Isabel Flores de Oliva in Lima, Peru, Rose adopted the name of a rose to express her beauty of spirit. Throughout her life, she dedicated herself to prayer, fasting, and helping those in need, often taking extreme measures of penance. Her dedication to God and the marginalized made her a beloved figure, and she was canonized in 1671, becoming the first saint of the Americas.', 'I am a servant of God and a servant of the poor.', 'August 23', NULL, 3, 10, 1, 10, 7, 10),

('Martin de Porres', 'martin-de-porres', 'A devoted Dominican lay brother known for his profound compassion and extraordinary healing abilities.', 'St. Martin de Porres was born in Lima, Peru, to a Spanish father and a black mother, and he faced racial discrimination throughout his life. He joined the Dominicans as a lay brother, where he dedicated his life to serving the poor and caring for the sick, including both people and animals. His legacy of charity and humility continues to inspire those who seek to promote racial harmony and health care for all.', 'No one makes a greater mistake than he who did nothing because he could do only a little.', 'November 3', NULL, 4, 10, 1, 4, 1, 6),

('Juan Diego', 'juan-diego', 'His vision of the Virgin Mary in Guadalupe led to a significant cultural and religious movement in Mexico.', 'St. Juan Diego was a humble indigenous man who experienced a vision of the Virgin Mary in 1531. This encounter resulted in the miraculous image of Our Lady of Guadalupe, which became a powerful symbol of faith. His devotion and simplicity continue to inspire millions, making him a beloved figure in the Catholic Church.', 'She is my Mother.', 'December 9', NULL, 4, 4, 1, 1, 1, 10),

('Kateri Tekakwitha', 'kateri-tekakwitha', 'She is recognized as the first Native American saint, honored for her conversion and deep faith despite facing considerable persecution.', 'St. Kateri Tekakwitha was born in 1656 in what is now New York, growing up amidst the Mohawk people. After the death of her family members from smallpox, she embraced Christianity, dedicating herself to a life of faith and service. Known for her unwavering commitment to her beliefs, she became a symbol of unity between Native American spirituality and Christian faith.', 'I will be the first to pay for my people’s sins.', 'July 14', NULL, 6, 10, 1, 4, 1, 4),

('Augustine of Canterbury', 'augustine-of-canterbury', 'The first Archbishop of Canterbury who played a crucial role in establishing Christianity in England.', 'St. Augustine of Canterbury was sent by Pope Gregory the Great in 597 AD to convert the Anglo-Saxons to Christianity. He established the See of Canterbury and became its first Archbishop, laying the groundwork for the English Church. His efforts marked the beginning of a significant Christian presence in England, influencing its cultural and spiritual development.', 'By the grace of God, I am what I am.', 'May 27', NULL, 1, 5, 1, 10, 3, 3),

('Columba', 'columba', 'A pivotal Irish missionary credited with spreading Christianity in Scotland.', 'St. Columba was an Irish abbot and missionary who played a crucial role in converting the Picts of Scotland to Christianity. He founded the famous monastery on Iona, which became a center for Christian learning and evangelization. His dedication to spreading the Gospel and his poetic legacy continue to inspire many to this day.', 'I am a servant of Christ, and I seek to serve the least among my brethren.', 'June 9', NULL, 1, 8, 1, 5, 10, 2),

('Bede the Venerable', 'bede-the-venerable', 'An influential monk and scholar who authored the first comprehensive history of the English church.', 'St. Bede the Venerable was a Benedictine monk at the Monastery of Wearmouth-Jarrow in England, where he spent most of his life dedicated to learning and teaching. His most notable work, ''Ecclesiastical History of the English People,'' has earned him the title of the father of English history. Known for his deep spirituality, Bede combined his scholarly endeavors with a profound faith that inspired many during and after his lifetime.', 'Time flies inexorably, and like a fire, consumes everything in its path.', 'May 25', NULL, 7, 3, 10, 1, 1, 3),

('Olaf', 'olaf', 'St. Olaf was a king who played a crucial role in the Christianization of Norway.', 'St. Olaf, known for his fierce leadership, ascended to the throne of Norway in the 11th century. He was instrumental in spreading Christianity throughout the region, often through both peaceful evangelization and military means. Driven by his faith, he is remembered for his dedication to creating a united Christian kingdom.', 'Christ is my light', 'July 29', NULL, 1, 1, 1, 10, 1, 4),

('Stanislaus', 'stanislaus', 'A bishop and martyr who stood against the excesses of the monarchy in Poland.', 'St. Stanislaus was a prominent bishop of Krakow who fiercely defended the rights of the Church against the corrupt practices of the Polish king Bolesław II. His unwavering conviction and moral courage ultimately led to his martyrdom around the year 1079. Today, he is remembered not only as a protector of the faith but also as a symbol of justice and integrity in Poland.', 'As a shepherd, I must ensure my flock is safe from the wolves.', 'April 11', NULL, 1, 1, 1, 10, 1, 1),

('Wenceslaus', 'wenceslaus', 'St. Wenceslaus was a Duke of Bohemia who was martyred by his brother in defense of his Christian faith.', 'St. Wenceslaus, revered as the patron saint of the Czech Republic, is known for his leadership during a challenging time for Christianity in Central Europe. Despite familial betrayal, he remained steadfast in promoting the Christian faith and justice. His legacy endures in the hearts of the Czech people, symbolizing courage and devotion.', 'I will not let the wrongs of others take away my righteousness.', 'September 28', NULL, 2, 6, 1, 10, 1, 6),

('Vladimir', 'vladimir', 'The prince who played a pivotal role in Christianizing Kievan Rus.', 'St. Vladimir, known as the Great, was a noble ruler of Kievan Rus who strategically embraced Christianity in 988, leading to the Christianization of his people. His conversion was a landmark moment that laid the foundation for Ukraine and Russia''s cultural and spiritual heritage. Today, he is celebrated not only as a saint but also as an important historical figure in the development of Eastern Slavic civilization.', 'Let us be united in faith, and strive for the salvation of our souls.', 'July 15', NULL, 2, 1, 2, 7, 2, 10),

('Casimir', 'casimir', 'A Polish prince celebrated for his piety and commitment to chastity.', 'St. Casimir was a Polish prince who dedicated his life to serving God and leading a life of virtue. Known for his deep faith, he refused to succumb to worldly temptations and was a model of Christian charity. His legacy continues to inspire the youth of Poland and Lithuania to strive for purity and devotion.', 'Do not let the fear of the future disturb you', 'March 4', NULL, 3, 10, 3, 10, 7, 10),

('Rose Philippine Duchesne', 'rose-philippine-duchesne', 'St. Rose Philippine Duchesne was a pioneering missionary who played a significant role in the education of Native Americans in the United States.', 'Born in France, St. Rose Philippine Duchesne felt a calling to serve as a missionary in America, where she dedicated her life to education and the spiritual nourishment of Native American communities. Overcoming great challenges, she founded schools and spread the teachings of Christ among those she served. Her unwavering faith and compassion have made her a beloved figure in the Catholic Church.', 'I wish to be like the good Mother who offered her son on the altar for the sake of souls.', 'November 18', NULL, 3, 8, 1, 10, 1, 8),

('John de Brébeuf', 'john-de-br-beuf', 'Jesuit missionary and martyr in Canada.', 'St. John de Brébeuf was a Jesuit missionary who dedicated his life to evangelizing the Indigenous peoples of North America, particularly the Huron Nation. He endured great hardships and faced violent opposition, ultimately being martyred for his faith in 1649. His deep love for the people he served inspired him to learn their language and culture, leaving a lasting legacy of compassion and sacrifice.', 'You must remember, my brothers, that any virtue of ours is not our own but comes from God.', 'October 19', NULL, 2, 10, 1, 6, 1, 6),

('Isaac Jogues', 'isaac-jogues', 'Jesuit missionary and martyr who dedicated his life to evangelizing Native Americans in North America.', 'St. Isaac Jogues was a French Jesuit missionary whose unwavering dedication brought him to the New World in service of the Gospel. Captured by the Iroquois, he endured severe torture and hardships, ultimately returning to his mission in New York. He was martyred in 1646, and his sacrifices paved the way for future missionaries in North America.', 'I am more than willing to die for God’s people.', 'October 19', NULL, 3, 7, 1, 10, 1, 10),

('Andrew Kim Taegon', 'andrew-kim-taegon', 'The first Korean priest and a martyr for the faith.', 'St. Andrew Kim Taegon was born in 1821 in Korea, during a time of intense persecution for Christians. He became the first native Korean priest and dedicated his life to spreading the Gospel despite overwhelming odds, ultimately paying the ultimate price for his faith. His martyrdom in 1846 inspired many and marked a pivotal point in the establishment of the Catholic Church in Korea.', 'I would still choose to become a priest as I have long dreamed and follow God’s will.', 'September 20', NULL, 2, 10, 1, 8, 1, 3),

('Peter Chanel', 'peter-chanel', 'A Marist missionary who was martyred in Oceania while spreading the Christian faith.', 'St. Peter Chanel was a French priest who devoted his life to missionary work in the islands of Oceania. He faced great dangers but remained unwavering in his commitment to spreading Christianity. His efforts ultimately led to his martyrdom in 1841, affirming his legacy as a courageous missionary.', 'I do not fear death. I fear to die without having given myself completely to God.', 'April 28', NULL, 2, 6, 1, 10, 1, 4),

('John XXIII', 'john-xxiii', 'He is celebrated for initiating the Second Vatican Council, promoting openness and reform in the Catholic Church.', 'Pope John XXIII, born Angelo Giuseppe Roncalli, was a transformative figure in the Catholic Church during the mid-20th century. He guided the Church towards modernization through his convocation of the Second Vatican Council, which aimed to address relations with the modern world. His emphasis on compassion and pastoral care helped to reshape the Church''s approach to its faithful and to society.', 'The whole world is my homeland.', 'October 11', NULL, 2, 10, 1, 2, 4, 8),

('Oscar Romero', 'oscar-romero', 'Archbishop martyred for his defense of the poor and oppressed in El Salvador.', 'St. Oscar Romero was a prominent Salvadoran archbishop who spoke out against human rights abuses during the Salvadoran Civil War. Known for his unwavering commitment to social justice, he advocated for the vulnerable and marginalized in society. His life was tragically cut short when he was assassinated while celebrating Mass on March 24, 1980.', 'If we cannot see Christ in the poor, we cannot see him in the Eucharist.', 'March 24', NULL, 1, 6, 2, 10, 1, 4),

('Thomas More', 'thomas-more', 'St. Thomas More was a Lord Chancellor of England who was martyred for his unwavering faith and refusal to accept King Henry VIII''s authority over the Church.', 'St. Thomas More was a renowned English lawyer, philosopher, and author known for his strong moral conviction. As Lord Chancellor, he stood firm against the Act of Supremacy, ultimately leading to his execution in 1535. His life exemplifies integrity and steadfastness in faith amidst political turmoil.', 'I die the king''s good servant, but God''s first.', 'June 22', NULL, 1, 4, 1, 10, 1, 1),

('John Fisher', 'john-fisher', 'Bishop and martyr who opposed King Henry VIII''s separation from the Catholic Church.', 'St. John Fisher was an English bishop and theologian who stood firmly against the Protestant Reformation led by King Henry VIII. His unwavering commitment to the papacy and the moral teachings of the Church ultimately led to his martyrdom in 1535. He was canonized by Pope Pius XI in 1935, often remembered for his intellectual bravery and profound faith.', 'In the hands of the Almighty, I am safe, though I cannot see the way.', 'June 22', NULL, 1, 1, 10, 7, 1, 1),

('Edmund Campion', 'edmund-campion', 'A Jesuit priest who became a martyr in England during the persecution of Catholics.', 'St. Edmund Campion was born in England in 1540 and became a prominent Jesuit priest. Known for his unwavering faith, he was martyred for refusing to abandon his Catholic beliefs during the Elizabethan persecutions. His legacy as a scholar and martyr continues to inspire many in the Catholic faith.', 'The truth is like a lion', 'December 1', NULL, 1, 1, 3, 10, 1, 1),

('Margaret Clitherow', 'margaret-clitherow', 'Margaret Clitherow was a laywoman and martyr recognized for her unwavering commitment to the Catholic faith during the English Reformation.', 'St. Margaret Clitherow was born in England and became a devoted wife and mother who bravely hid priests to protect them from persecution. Her actions led to her arrest and trial, where she refused to betray her faith, ultimately sacrificing her life for her beliefs. Recognized as a martyr for her courage, she inspires many to stand firm in their convictions.', 'I die a Catholic, for the faith I have received.', 'March 25', NULL, 3, 1, 1, 10, 1, 4),

('Oliver Plunkett', 'oliver-plunkett', 'St. Oliver Plunkett was a courageous archbishop and martyr during the persecution of Catholics in Ireland.', 'St. Oliver Plunkett was a prominent figure in the Catholic Church during a time of great turmoil in Ireland. He dedicated his life to serving the spiritual needs of his people, ultimately sacrificing his own life for his unwavering faith. His execution in 1681 made him a symbol of resistance against religious oppression and a celebrated martyr.', 'I die innocent of all charges against me.', 'July 1', NULL, 2, 6, 6, 10, 1, 4),

('Brigid of Ireland', 'brigid-of-ireland', 'Brigid is notable for her role in founding monasteries and establishing Christian communities in Ireland.', 'St. Brigid of Ireland, born in the early 5th century, is celebrated for her dedication to spirituality and community service. She founded the famous monastery at Kildare, which became a center of learning and piety. Known for her compassion and wisdom, Brigid''s life and teachings continue to inspire many in their faith.', 'I would like a great lake of beer for the King of Kings. I would drink it deep, and I would pour it out for all who thirst.', 'February 1', NULL, 1, 10, 8, 4, 2, 6),

('Brendan the Navigator', 'brendan-the-navigator', 'An Irish monk celebrated for his legendary sea voyages across the Atlantic Ocean.', 'St. Brendan the Navigator was an influential Irish monk who founded several monasteries in Ireland and abroad. His most famous journey, the ''Navigatio Sancti Brendani,'' describes an adventurous voyage across the Atlantic, exploring mystical lands. Through his travels, he inspired countless generations with tales of faith and exploration.', 'For the sake of Christ, be ready for anything.', 'May 16', NULL, 2, 1, 1, 10, 6, 10),

('Kevin', 'kevin', 'Founder of the monastic community at Glendalough in Ireland.', 'St. Kevin, known for his deep spiritual life, established a monastery in the picturesque valley of Glendalough, which became a significant center of learning and pilgrimage. He was renowned for his piety and connection to nature, often depicted with animals, especially blackbirds who are said to have been drawn to him. His legacy endures not only through his monastic foundation but also in the hearts of those who seek peace in the serenity of nature.', 'You cannot wash a blackbird’s feathers', 'June 3', NULL, 1, 10, 3, 7, 1, 10),

('Malachy', 'malachy', 'St. Malachy was a significant reformer of the Irish Church and the first native-born Archbishop of Armagh.', 'St. Malachy was born in 1094 in Armagh, Ireland, and dedicated his life to revitalizing the ecclesiastical structure of his country. His tireless efforts in reform led to a more devout and unified church, earning him recognition as one of Ireland''s greatest saints. He died in 1148, leaving a lasting legacy of peace and leadership in the Irish Church.', 'Let us pray for the peace of the Church.', 'November 3', NULL, 1, 10, 1, 6, 1, 4),

('David', 'david', 'He is revered as the patron saint of Wales and founder of many monasteries.', 'St. David was a sixth-century bishop and the founder of monastic communities in Wales, notably at Glyn Rhosyn (now known as Glastonbury). He is celebrated for his piety, simplicity, and commitment to the Christian faith, living a life dedicated to the service of God and his community. St. David''s legacy continues to inspire generations, and he is remembered as a national hero in Welsh culture.', 'Be joyful, keep the faith, and do the little things.', 'March 1', NULL, 5, 10, 3, 5, 8, 8),

('Andrew', 'andrew', 'St. Andrew is recognized as the first Apostle called by Jesus and the brother of Peter, who was martyred by crucifixion on an X-shaped cross.', 'St. Andrew, one of the foremost apostles, dedicated his life to spreading the message of Jesus Christ. He is traditionally believed to have been martyred on an X-shaped cross in Patras, Greece, after a fervent ministry across various regions. His legacy as the patron saint of several countries reflects his impact and veneration throughout history.', 'Come, follow me, and I will make you fishers of men.', 'November 30', NULL, 5, 5, 1, 10, 5, 8),

('James the Greater', 'james-the-greater', 'St. James the Greater was one of Jesus'' twelve apostles, renowned for being the first to be martyred among them.', 'St. James the Greater, a Galilean fisherman, was called by Jesus to be one of His closest disciples. Known for his unwavering faith and missionary zeal, he spread the Gospel far and wide, eventually facing martyrdom by beheading in Jerusalem. Today, he is honored as the patron saint of Spain and his shrine in Santiago de Compostela attracts countless pilgrims every year.', 'If any man wishes to come after me, let him deny himself, take up his cross daily, and follow me.', 'July 25', NULL, 1, 1, 1, 10, 1, 3),

('John the Apostle', 'john-the-apostle', 'St. John is revered as the beloved disciple and the author of the Gospel of John and the Book of Revelation.', 'St. John the Apostle, one of Jesus'' closest companions, played a pivotal role in the early Christian community. He is traditionally believed to have authored several biblical texts that emphasize love and the divine nature of Jesus. After surviving persecution and exile, he is thought to have died peacefully in Ephesus around 100 AD.', 'In the beginning was the Word, and the Word was with God, and the Word was God.', 'December 27', NULL, 1, 4, 10, 1, 3, 1),

('Thomas the Apostle', 'thomas-the-apostle', 'The apostle famously known for his skepticism regarding Christ’s resurrection.', 'St. Thomas the Apostle, one of the twelve disciples of Jesus, is best known for his initial doubt about the resurrection. He traveled to India, where he played a pivotal role in establishing Christian communities. His unwavering faith following his encounter with the risen Christ led to his martyrdom, and he is honored as the patron saint of India.', 'My Lord and my God!', 'July 3', NULL, 1, 1, 1, 8, 1, 10),

('Matthew', 'matthew', 'St. Matthew is recognized as one of the twelve Apostles and the author of the Gospel of Matthew.', 'St. Matthew, originally a tax collector, was called by Jesus to be one of His disciples, showcasing the transformative power of grace. After the Ascension of Jesus, he dedicated his life to spreading the Gospel, traveling to various regions to preach. His Gospel is notable for its focus on the fulfillment of Old Testament prophecies, making it a vital text for Christians.', 'Follow me, and I will make you fishers of men.', 'September 21', NULL, 3, 8, 8, 1, 1, 10),

('Mark the Evangelist', 'mark-the-evangelist', 'St. Mark is celebrated for authoring the Gospel of Mark and serving as a close companion to the Apostle Peter.', 'St. Mark the Evangelist is one of the four Gospel writers of the New Testament, providing a vital account of Jesus’ life and teachings through his Gospel. He is also recognized as the founder of the Church of Alexandria, which became a significant center of Christianity. His feast is celebrated on April 25, a day marking his contributions to the faith and his enduring legacy through his writings.', 'The time has come, the Kingdom of God has come near', 'April 25', NULL, 1, 10, 6, 4, 4, 2),

('Luke the Evangelist', 'luke-the-evangelist', 'Author of the Gospel of Luke and the Acts of the Apostles, highlighting Jesus'' compassion and the spread of Christianity.', 'St. Luke the Evangelist was a physician and a companion of St. Paul, known for his deep intellect and artistic flair. He penned the Gospel that emphasizes the mercy of Christ and the role of the Holy Spirit in the early Church. His writings have profoundly influenced Christian theology and practice throughout the centuries.', 'For behold, I bring you good tidings of great joy, which shall be to all people.', 'October 18', NULL, 1, 10, 10, 1, 4, 4),

('Barnabas', 'barnabas', 'A prominent Apostle and missionary, he played a key role in the early Church as a companion of St. Paul.', 'St. Barnabas, originally named Joseph, was a Levite from Cyprus who sold his property to support the early Christian community. He became an influential figure in spreading the Gospel, particularly among the Gentiles, and was instrumental in introducing Paul to the apostles in Jerusalem. His unwavering faith and commitment to the Church earned him the title of Apostle, and he is remembered as a pioneering missionary of the Christian faith.', 'For it is not the one who commends himself who is approved, but the one whom the Lord commends.', 'June 11', NULL, 2, 6, 1, 4, 1, 10),

('Timothy', 'timothy', 'Timothy was a devoted bishop and close disciple of St. Paul, known for his contributions to the early Church.', 'St. Timothy, a key figure in the early Christian church, served as the bishop of Ephesus. He was a trusted companion of St. Paul, receiving two epistles that provide guidance and insight into his pastoral role. His commitment to leading his community with grace marked him as a model for Christian leadership.', 'Let no one despise your youth, but set the believers an example in speech, in conduct, in love, in faith, in purity.', 'January 26', NULL, 4, 8, 4, 10, 4, 1),

('Titus', 'titus', 'St. Titus was a close companion of St. Paul and played a significant role in the early Christian church as the Bishop of Crete.', 'St. Titus was one of the prominent figures of the early Church, entrusted by St. Paul to lead the Christian community in Crete. Known for his unwavering faith and strong leadership, he helped establish Christian practices in an area known for its challenges. His letters from St. Paul provide insights into the responsibilities and virtues expected of church leaders.', 'You must teach what is in accord with sound doctrine.', 'August 26', NULL, 2, 1, 2, 4, 1, 10),

('Apollonia', 'apollonia', 'St. Apollonia is revered as a virgin martyr who endured brutal torture during the persecution of Christians.', 'St. Apollonia was a Christian martyr from Egypt who faced horrific torture, notably having her teeth pulled out. She remained steadfast in her faith during her trials, inspiring countless believers with her unwavering courage. Her memory is honored by those who seek comfort and healing from tooth-related issues.', 'The Lord has given me the strength to endure this agony.', 'February 9', NULL, 2, 6, 1, 10, 1, 6),

('Blaise', 'blaise', 'A bishop known for healing a boy who was choking on a fishbone.', 'St. Blaise was a 4th-century bishop from Armenia known for his miraculous healing abilities. He gained fame for saving a child from choking, which led to his designation as the patron saint of throat afflictions. Ultimately, he was martyred for his faith, demonstrating steadfast leadership in the early church.', 'If you wish to be a true leader, serve others with love and compassion.', 'February 3', NULL, 2, 10, 1, 8, 1, 6),

('Agatha', 'agatha', 'St. Agatha is revered as a virgin martyr who endured severe torture, including having her breasts cut off, for her faith.', 'St. Agatha was a noblewoman from Sicily who dedicated her life to Christ and chose martyrdom over compromising her faith. Her courage during her torturous trials has made her a symbol of unwavering faith and devotion among Christians. Many miracles are attributed to her intercession, especially in times of illness and suffering.', 'Mine is the hope in the strength of the Almighty!', 'February 5', NULL, 2, 6, 1, 10, 1, 6),

('Agnes', 'agnes', 'St. Agnes is revered as a virgin martyr who sacrificed her life for her faith at a young age.', 'St. Agnes was a young Roman girl who dedicated her life to Christ and refused to marry, choosing instead to remain a virgin. At the tender age of 12 or 13, she faced persecution and ultimately martyrdom for her unwavering faith and commitment to her beliefs. She has inspired countless followers through her courage and steadfastness, serving as a symbol of purity and faith for young women throughout the centuries.', 'I choose to follow the Lord, no matter the cost.', 'January 21', NULL, 3, 8, 1, 8, 1, 10),

('Barbara', 'barbara', 'St. Barbara is revered as a virgin martyr who was killed by her father for her Christian faith.', 'St. Barbara was a beautiful maiden who boldly defied her father’s pagan beliefs by converting to Christianity. After her father discovered her faith, he imprisoned her and ultimately killed her, leading to her martyrdom. Her legacy represents courage and steadfastness in faith, inspiring countless devotees through the centuries.', 'I long to be free, unbound by worldly fears.', 'December 4', NULL, 1, 1, 1, 10, 3, 5),

('Christopher', 'christopher', 'St. Christopher is venerated for his legendary journey of carrying a child, believed to be Christ, across a river, which led to his martyrdom.', 'St. Christopher is known as the patron saint of travelers, embodying the spirit of adventure and protection. According to tradition, he carried a child across a perilous river, only to discover that the child was Christ himself. His unwavering faith and sacrificial love ultimately led to his martyrdom.', 'It is a great thing, my brethren, to serve a master who is the truth.', 'July 25', NULL, 2, 10, 1, 8, 1, 3),

('Valentine', 'valentine', 'A priest who defied Emperor Claudius II by marrying couples in secret, resulting in his martyrdom.', 'St. Valentine was a Roman priest renowned for his courage in marrying couples during a time when such unions were prohibited by the emperor. His dedication to love and faith ultimately led to his imprisonment and execution. Today, he is celebrated as the patron saint of lovers, symbolizing commitment and hope.', 'Love is the martyrdom of a Christ.', 'February 14', NULL, 2, 10, 1, 3, 1, 5),

('Jude Thaddeus', 'jude-thaddeus', 'One of the Twelve Apostles, St. Jude is revered as the patron saint of hopeless cases.', 'St. Jude Thaddeus, one of the lesser-known apostles, dedicated his life to spreading the teachings of Jesus Christ. He is particularly invoked by those in dire circumstances, offering hope to the hopeless. His letters in the New Testament tell of his unwavering faith and commitment to the early Christian community.', 'May the Lord find us faithful.', 'October 28', NULL, 4, 10, 1, 4, 1, 8),

('Rita of Cascia', 'rita-of-cascia', 'A devoted widow and nun who is recognized for her deep mystical spirituality and bearing the stigmata.', 'St. Rita of Cascia was born in Italy and lived a life marked by suffering and deep faith. After enduring a troubled marriage, she became a nun and dedicated herself to prayer and compassion for others. Known as the ''Saint of the Impossible'', she inspires countless individuals facing dire situations to trust in God''s mercy.', 'Pray to God, and He will hear you.', 'May 22', NULL, 3, 8, 1, 10, 1, 10),

('Peregrine Laziosi', 'peregrine-laziosi', 'He is renowned for his miraculous healing from cancer.', 'St. Peregrine Laziosi was a 14th-century Italian saint known for his deep faith and miraculous cures. After suffering from cancer himself, he experienced a profound healing through prayer and devotion, which inspired many to seek his intercession. He became a beloved figure, advocating for the sick and marginalized in society.', 'Where there is charity and wisdom, there is neither fear nor ignorance.', 'May 1', NULL, 3, 10, 1, 10, 7, 10),

('Dymphna', 'dymphna', 'An Irish princess who was martyred by her father for refusing to marry him.', 'St. Dymphna was the daughter of a pagan king and a Christian mother, whose untimely death deeply troubled him. In her devotion to her faith, she fled from her father''s advances, ultimately leading to her martyrdom. Today, she is cherished as a beacon of hope for those struggling with mental health issues.', 'Be not afraid to be a child of God.', 'May 15', NULL, 2, 10, 1, 8, 1, 3),

('Roch', 'roch', 'St. Roch is celebrated for his dedication to caring for plague victims, even at the cost of his own health.', 'Born into a noble family in France, St. Roch devoted his life to serving the sick and poor, particularly during times of plague. After contracting the disease himself, he was cared for by a dog that brought him food and companionship. His legacy as a healer and protector lives on, inspiring countless individuals to show compassion and care for others afflicted by illness.', 'I am but a servant of God.', 'August 16', NULL, 1, 10, 1, 4, 1, 1),

('Raphael the Archangel', 'raphael-the-archangel', 'The healing angel who guides Tobias in the Book of Tobit.', 'St. Raphael the Archangel is revered as one of the three archangels mentioned in sacred scripture. He plays a significant role in the Book of Tobit, where he aids Tobias on his journey and restores the sight of his father, Tobit. As a symbol of healing and guidance, St. Raphael inspires the faithful to trust in divine assistance during their struggles.', 'I am the angel Raphael', 'September 29', NULL, 1, 8, 8, 1, 1, 10),

('Michael the Archangel', 'michael-the-archangel', 'St. Michael is revered as the archangel who leads the heavenly army against the forces of evil.', 'St. Michael the Archangel is a central figure in Christian tradition, symbolizing divine protection and strength. He is often depicted as a majestic warrior with a sword, defeating the devil and safeguarding souls. His role as a protector of the faithful has made him a beloved saint across various cultures.', 'Who is like God?', 'September 29', NULL, 1, 3, 1, 10, 1, 1),

('Gabriel the Archangel', 'gabriel-the-archangel', 'St. Gabriel is known for being the archangel who announced the birth of Jesus to the Virgin Mary.', 'St. Gabriel the Archangel is one of the three archangels mentioned in the Bible, revered for his role as God''s messenger. He delivered important messages to figures such as Daniel in the Old Testament and Mary in the New Testament, signifying his role in both the Old and New Covenants. Gabriel is celebrated for his unwavering faithfulness and serves as a model of divine communication.', 'I stand in the presence of God.', 'September 29', NULL, 1, 5, 5, 5, 1, 10),

('Guardian Angels', 'guardian-angels', 'Saints associated with the guardianship and protection of individuals by angels.', 'St. Guardian Angels represent the divine assistance afforded to every individual through heavenly beings. These angels are believed to offer guidance, support, and protection throughout one''s life. Revered for their unwavering commitment to safeguarding humanity, they remind the faithful of God''s love and care.', 'For he will command his angels concerning you to guard you in all your ways. - Psalm 91:11', 'October 2', NULL, 1, 10, 1, 1, 1, 4),

('Anne', 'anne', 'Mother of the Virgin Mary and the grandmother of Jesus Christ.', 'St. Anne is revered as the mother of the Virgin Mary and the grandmother of Jesus, embodying maternal love and virtue. She is celebrated for her unwavering faith and role in the Holy Family, deeply influencing Christian devotion to motherhood. Her life is a testament to the power of prayer, patience, and the nurturing spirit of women throughout history.', 'If you are what you should be, you will set the whole world on fire.', 'July 26', NULL, 2, 10, 6, 4, 2, 4),

('Joachim', 'joachim', 'He is recognized as the father of the Virgin Mary and grandfather of Jesus Christ.', 'St. Joachim, a devout man from Galilee, is revered as the father of the Virgin Mary. He and his wife, St. Anne, are celebrated for their unwavering faith and the remarkable grace bestowed upon them in having a child after years of barrenness. Their legacy lives on through their daughter, Mary, the mother of Jesus, highlighting the importance of family in the Christian faith.', 'The Lord has given me the fruit of my prayers.', 'July 26', NULL, 2, 1, 1, 1, 1, 10),

('Elizabeth (mother of John Baptist)', 'elizabeth-mother-of-john-baptist', 'St. Elizabeth is revered as the mother of John the Baptist and the cousin of the Virgin Mary.', 'St. Elizabeth was a devout woman chosen by God to be the mother of John the Baptist. Despite her advanced age, she conceived miraculously, exemplifying faith and trust in God’s plan. Her life is a testament to the joys and challenges of motherhood, as well as a profound connection to Mary''s own journey.', 'My soul proclaims the greatness of the Lord, and my spirit rejoices in God my Savior.', 'November 5', NULL, 2, 4, 6, 1, 2, 10),

('John the Baptist', 'john-the-baptist', 'The forerunner of Christ who baptized Jesus in the Jordan River.', 'St. John the Baptist is revered as the precursor to Jesus Christ, calling people to repentance in preparation for the coming Messiah. He lived a life of asceticism in the wilderness, preaching the need for spiritual renewal and performing baptisms of atonement. His boldness in denouncing sin led to his imprisonment and eventual martyrdom, making him a symbol of unwavering faith.', 'I am the voice of one crying out in the wilderness, ''Make straight the way of the Lord.''', 'June 24', NULL, 5, 5, 1, 8, 1, 10),

('Joseph of Arimathea', 'joseph-of-arimathea', 'Joseph of Arimathea is known for providing his own tomb for the burial of Jesus Christ.', 'St. Joseph of Arimathea was a wealthy and respected member of the Jewish council who secretly followed Jesus. Despite the risk to his reputation and safety, he courageously requested Jesus'' body from Pilate and laid it in his own tomb. His actions symbolize profound faith and compassion in the face of adversity.', 'He shall be called a Nazarene.', 'March 17', NULL, 2, 10, 1, 8, 1, 3),

('Dismas', 'dismas', 'St. Dismas is recognized as the ''Good Thief'' who repented and was crucified alongside Jesus.', 'St. Dismas is known as the penitent thief who, during his crucifixion, expressed sorrow for his sins and asked Jesus to remember him. His faith and repentance earned him the promise of paradise that very day, showing that redemption is possible at any point in life. He serves as a powerful symbol of hope for those struggling with sin and despair.', 'Jesus, remember me when you come into your kingdom.', 'March 25', NULL, 4, 10, 1, 1, 1, 10),

('Longinus', 'longinus', 'St. Longinus is known as the Roman soldier who pierced the side of Jesus at the Crucifixion.', 'St. Longinus, a Roman centurion, is remembered for his pivotal role at the Crucifixion of Christ when he pierced Jesus'' side with a spear. He is said to have converted to Christianity after witnessing the events surrounding Jesus''s death, profoundly impacting his life. Traditionally, he became a martyr for his faith, inspiring many as a symbol of conversion and bravery.', 'Truly, this was the Son of God.', 'March 15', NULL, 2, 1, 1, 6, 1, 10),

('Veronica', 'veronica', 'St. Veronica is best known for compassionately wiping the face of Jesus on his way to Calvary, resulting in the image of His face miraculously being imprinted on her cloth.', 'St. Veronica is remembered for her act of kindness towards Jesus during His Passion. Her bravery and devotion led her to defy the crowd to offer Him comfort in His time of suffering. This encounter not only solidified her place in Christian tradition but also established her as a symbol of compassion and empathy.', 'In my heart, Lord, I carry Your passion.', 'July 12', NULL, 2, 6, 1, 10, 1, 6),

('Carlo Acutis', 'carlo-acutis', 'A young boy who created a website documenting Eucharistic miracles.', 'Blessed Carlo Acutis was an Italian teenager known for his deep devotion to the Eucharist and his innovative use of technology to spread the message of faith. He created a comprehensive online archive of Eucharistic miracles that continues to inspire many today. Carlo passed away from leukemia at the age of 15, leaving behind a legacy of joy and faithfulness to Christ.', 'The Eucharist is my highway to heaven.', 'October 12', NULL, 2, 1, 1, 1, 5, 10),

('Pier Giorgio Frassati', 'pier-giorgio-frassati', 'A compassionate young Italian known for serving the poor while passionately engaging in athletics and mountaineering.', 'Blessed Pier Giorgio Frassati was a remarkable Italian youth who dedicated his life to serving the underprivileged, often reflecting his deep Catholic faith through acts of charity. Despite his love for sports and the outdoors, he maintained a strong commitment to social reform and community service. His life, cut short at 24, continues to inspire young Catholics to embrace both faith and action in their lives.', 'The world is in great need of people who can awaken hope.', 'July 4', NULL, 1, 10, 1, 10, 10, 10),

('Chiara Badano', 'chiara-badano', 'A courageous Italian girl whose unwavering faith illuminated her battle with terminal cancer.', 'Chiara Badano, born in Italy, radiated joy and faith even as she faced the challenges of terminal cancer. She became a symbol of hope and love for many, inspiring people with her deep spirituality and positive attitude. Her life, though brief, touched countless hearts and continues to inspire those suffering from illness today.', 'For you, I would smile even in pain.', 'October 29', NULL, 2, 4, 1, 8, 10, 6),

('Miguel Pro', 'miguel-pro', 'A Mexican Jesuit priest known for his courageous ministry and martyrdom during a time of intense religious persecution.', 'Blessed Miguel Pro was a Mexican Jesuit priest renowned for his willingness to serve others during a brutal religious crackdown in Mexico. Utilizing disguises, he secretly provided sacraments and support to those in need, ultimately leading to his arrest and martyrdom. He was executed in 1927, proclaiming his faith with the words ''Viva Cristo Rey!'' as a testament to his unwavering dedication to Christ.', 'Viva Cristo Rey! (Long live Christ the King!)', 'November 23', NULL, 1, 2, 1, 10, 6, 4),

('Franz Jägerstätter', 'franz-j-gerst-tter', 'Austrian farmer who refused to serve in the Nazi army and was executed for his beliefs.', 'Franz Jägerstätter was an Austrian farmer whose steadfast refusal to fight for the Nazi regime made him a symbol of moral courage. In the face of immense pressure, he chose to stand by his convictions, ultimately paying the ultimate price for his beliefs in 1943. His life and sacrifice continue to inspire those who advocate for peace and justice.', 'I cannot and may not take an oath in favor of a government that is fighting an unjust war.', 'May 21', NULL, 1, 1, 1, 10, 1, 3),

('Solanus Casey', 'solanus-casey', 'He was an American Capuchin friar recognized for his gift of healing and service to the community.', 'Blessed Solanus Casey dedicated his life to serving others with humility and compassion. Known for his incredible faith and healing abilities, he became a beloved figure among those who sought his counsel and intercessions. His legacy of patience in the face of trials continues to inspire many today.', 'We should always pray for what we need, but we must never forget to thank God for what we have.', 'July 30', NULL, 2, 10, 1, 1, 1, 6),

('Stanley Rother', 'stanley-rother', 'An American priest martyred in Guatemala while serving the indigenous people.', 'Born in Oklahoma, Stanley Rother became a beloved priest in Guatemala, dedicating his life to serving the local indigenous population. His unwavering commitment to his community during a period of violent persecution led to his martyrdom in 1981. Rother''s legacy of love and service continues to inspire many to this day.', 'I have no greater gift than to give my life for others.', 'July 28', NULL, 1, 10, 1, 6, 1, 1),

('Michael McGivney', 'michael-mcgivney', 'Founder of the Knights of Columbus to support Catholic families.', 'Blessed Michael McGivney was an American priest dedicated to serving his parish and empowering families through social welfare. As the founder of the Knights of Columbus in 1882, he pioneered an organization that provided assistance to families in need during an era of hardship. His legacy continues to inspire charitable work and community service in the Catholic Church today.', 'The greatest thing that we must remember is that we are part of the great family of God.', 'August 13', NULL, 1, 10, 1, 1, 1, 1),

('Anne Catherine Emmerich', 'anne-catherine-emmerich', 'A German Augustinian nun noted for her mystical visions and writings about the Passion of Christ.', 'Anne Catherine Emmerich was a German Augustinian nun whose profound mystical experiences brought her deep insights into the life of Jesus. Living a life of intense prayer and suffering, she recorded her visions, which have inspired countless believers. Her dedication to the way of the Cross has made her a beloved figure among the faithful.', 'My soul is like a place where there is great silence. I see nothing and hear nothing, but my heart speaks to God.', 'February 9', NULL, 7, 4, 1, 1, 1, 10),

('Imelda Lambertini', 'imelda-lambertini', 'A young girl who died in ecstasy shortly after receiving her First Communion.', 'Blessed Imelda Lambertini was a young Italian girl devoted to the Eucharist, who yearned to receive Holy Communion. She experienced a profound encounter with Jesus in the Blessed Sacrament, which led to her dying in a state of joyful ecstasy. Her life exemplifies deep faith and innocence, inspiring many in the Catholic Church.', 'I can no longer live without my Jesus.', 'May 13', NULL, 4, 1, 1, 2, 10, 10),

('Isidore Bakanja', 'isidore-bakanja', 'A Congolese layman martyred for his unwavering faith and for teaching others about Christianity.', 'Blessed Isidore Bakanja was a devoted layman in the Congo who encountered severe persecution for his Christian beliefs. He is best known for his resolve to wear the scapular and spread the teachings of Christ despite the threats against him. His martyrdom symbolizes the courage and dedication of Christians enduring oppression, inspiring many in their faith journeys.', 'The white man did not like Christians. But I shall pray for him.', 'August 15', NULL, 1, 2, 1, 10, 1, 6),

('Jacinta Marto', 'jacinta-marto', 'The youngest visionaries of Fatima who dedicated her life to praying for the conversion of sinners.', 'Blessed Jacinta Marto was a shepherd girl from Portugal who witnessed the Marian apparitions in Fatima in 1917. Known for her profound devotion at a young age, she offered her suffering for the salvation of others and was deeply affected by the reality of sin and its consequences. Jacinta died at the tender age of 9, leaving behind a legacy of unwavering faith and love for the Immaculate Heart of Mary.', 'I will pray a lot for you, and I also want you to pray for me.', 'February 20', NULL, 2, 2, 1, 4, 1, 10),

('Francisco Marto', 'francisco-marto', 'A visionary of Fatima who devoted his life to prayer and consolation of Jesus.', 'Bl. Francisco Marto was one of the three shepherd children who witnessed the apparitions of Our Lady of Fatima. He was known for his profound devotion and desire to console Jesus, spending hours in prayer and meditation. His deep faith and spiritual insights continue to inspire many in their journey of faith.', 'I want to make Jesus happy, and that is why I pray.', 'February 20', NULL, 10, 1, 1, 1, 1, 7),

('Robert Bellarmine', 'robert-bellarmine', 'A prominent Jesuit cardinal and Doctor of the Church, recognized for his defense of Catholic doctrine.', 'St. Robert Bellarmine was a pivotal figure in the Counter-Reformation, known for his deep commitment to teaching and defending the faith. He served as a cardinal and was instrumental in shaping the Catholic Church’s response to Protestantism through his writings and theological insights. His legacy continues to inspire those involved in education and catechesis today.', 'The church is a great liar, and it lies against itself in order to unite itself.', 'September 17', NULL, 2, 5, 10, 1, 1, 5),

('Francis de Sales', 'francis-de-sales', 'Bishop of Geneva and a friend of the common people, he contributed significantly to the spiritual literature of the Catholic Church.', 'St. Francis de Sales was a prominent bishop in the early 17th century who dedicated his life to the pastoral care of his diocese amidst the challenges of the Protestant Reformation. His writings, steeped in compassion and clarity, helped make the Catholic faith accessible and appealing to many. He is remembered not only for his theological insights but also for his enduring principles of gentleness and love in personal interaction.', 'You can catch more flies with honey than with vinegar.', 'January 24', NULL, 1, 10, 7, 1, 10, 10),

('Jane Frances de Chantal', 'jane-frances-de-chantal', 'Co-founder of the Visitation Order alongside St. Francis de Sales.', 'St. Jane Frances de Chantal was a French widow who, after the death of her husband, dedicated her life to God and the service of others. She co-founded the Order of the Visitation of Holy Mary with St. Francis de Sales, emphasizing the importance of community and compassion. Known for her deep spiritual insights and nurturing character, she left a lasting legacy of love and service in the Church.', 'If you are faithful in little things, you will be faithful in great things.', 'August 12', NULL, 2, 10, 4, 4, 2, 6),

('Charles Borromeo', 'charles-borromeo', 'He was a cardinal instrumental in the reform of the Catholic Church in the wake of the Council of Trent.', 'St. Charles Borromeo dedicated his life to reforming the Church and improving the spiritual and educational needs of his community. Known for his compassion, he tirelessly served plague victims during an outbreak, demonstrating his deep commitment to his flock. He played a key role in establishing seminaries and promoting educational reforms that shaped the future of the clergy.', 'If we wish to make any progress in the service of God we must begin every day of our life with new eagerness.', 'November 4', NULL, 1, 10, 3, 7, 1, 10),

('Isidore of Seville', 'isidore-of-seville', 'A foundational figure in the early Middle Ages who compiled extensive encyclopedic knowledge.', 'St. Isidore of Seville was a prominent bishop and scholar whose works laid the groundwork for the preservation of knowledge during the Dark Ages. His encyclopedias served as vital resources for generations of students and thinkers, emphasizing the importance of education and faith. Revered as a Doctor of the Church, his influence extends into modern times, particularly in the field of information science.', 'The person who does not read will not be read.', 'April 4', NULL, 1, 1, 10, 1, 1, 5),

('Angela Merici', 'angela-merici', 'Angela Merici is renowned for founding the Ursulines, the first teaching order of women dedicated to the education of girls.', 'St. Angela Merici was a visionary educator who dedicated her life to improving the spiritual and educational landscape of her time. As a strong advocate for women''s education, she established the Ursuline order in 1535, emphasizing the importance of teaching girls. Her legacy continues to inspire countless educators and students today.', 'Do not be afraid! Take the leap with trust in God, and He will guide you.', 'January 27', NULL, 1, 10, 1, 4, 4, 10),

('Gerard Majella', 'gerard-majella', 'St. Gerard Majella was a Redemptorist lay brother renowned for his miraculous intercession, particularly for expectant mothers.', 'St. Gerard Majella was a humble and devoted lay brother of the Redemptorist order who dedicated his life to serving others through prayer and miraculous deeds. He gained a reputation for his compassion and was particularly known for assisting women during pregnancy and childbirth. His legacy lives on as a beloved saint amongst families and expectant mothers seeking comfort and support.', 'What can I say? I don''t know how to express my love for you, except to say that I love you as I love God.', 'October 16', NULL, 2, 10, 1, 1, 1, 6),

('John of Capistrano', 'john-of-capistrano', 'A fervent Franciscan preacher renowned for his leadership during the Siege of Belgrade.', 'Born in Italy, St. John of Capistrano dedicated his life to the Franciscan order and became an influential preacher. His passionate oratory inspired many, particularly during the critical defense against the Ottoman Empire in 1456. His legacy endures as a symbol of faith and commitment to justice.', 'He who is prepared to die for his faith will never perish.', 'October 23', NULL, 1, 1, 2, 10, 1, 6),

('Peter Canisius', 'peter-canisius', 'A prominent figure in the Counter-Reformation and a Jesuit Doctor of the Church.', 'St. Peter Canisius was a pivotal figure in the Catholic Reformation in Germany, known for his fervent missionary work and his dedication to education. He authored influential catechisms that helped clarify Catholic doctrine during a time of great turmoil. His commitment to spreading the faith and his intellectual contributions earned him a place among the Doctors of the Church.', 'I have my own life to live and I must live it for God.', 'December 21', NULL, 1, 4, 10, 6, 1, 4),

('André Bessette', 'andr-bessette', 'A Holy Cross brother renowned for his miraculous healings and the construction of St. Joseph''s Oratory in Montreal.', 'St. André Bessette, also known as Brother André, dedicated his life to the spiritual and physical well-being of others. Though he faced criticism and doubt due to his humble beginnings, he became a beacon of hope for the suffering through his unwavering faith and devotion. His legacy is immortalized in the grandeur of St. Joseph''s Oratory, a testament to his lifelong commitment to the service of God and His people.', 'One should not be discouraged', 'January 6', NULL, 3, 10, 1, 1, 4, 3),

('Junípero Serra', 'jun-pero-serra', 'Founder of the California mission system and evangelizer of the native populations.', 'St. Junípero Serra was a Spanish Franciscan missionary who dedicated his life to spreading the Catholic faith in California. He founded nine of the 21 California missions, working tirelessly to convert and educate the indigenous peoples. Serra is remembered for his deep faith and commitment to his mission, despite facing numerous challenges and hardships.', 'For me, the most important thing is not to lose faith, even when times are difficult.', 'July 1', NULL, 1, 1, 1, 8, 1, 10),

('Marguerite Bourgeoys', 'marguerite-bourgeoys', 'Foundress of the Congregation of Notre Dame, known for her dedication to educating girls in New France.', 'St. Marguerite Bourgeoys was a pioneering French educator who established schools in the New World, dedicated to the spiritual and academic formation of young girls. She founded the Congregation of Notre Dame, which played a crucial role in the development of education in Canada. Her legacy continues to inspire teaching and community service to this day.', 'In the little things, we find great love.', 'January 12', NULL, 1, 10, 1, 6, 3, 1),

('Marguerite d''Youville', 'marguerite-dyouville', 'Founder of the Grey Nuns dedicated to serving the impoverished in Canada.', 'St. Marguerite d''Youville was a devoted Canadian widow known for her unyielding commitment to the less fortunate. In the face of personal hardship, she established the Grey Nuns, who became instrumental in providing care for the poor and the sick in the 18th century. Her legacy of compassion and service continues to inspire countless individuals around the world.', 'Let us embrace our trials with love and continue to trust in God.', 'October 16', NULL, 1, 10, 1, 4, 1, 1),

('Maria Goretti', 'maria-goretti', 'A courageous young martyr who exemplified forgiveness and purity.', 'St. Maria Goretti was a twelve-year-old Italian girl who became a martyr for her faith and commitment to purity. She forgave her attacker with her dying words, embodying the virtue of forgiveness and leaving a profound impact on the Catholic Church. Canonized in 1950, her life continues to inspire many to uphold the values of faith and resilience.', 'I forgive Alessandro and I want him to be with me in Heaven.', 'July 6', NULL, 3, 5, 1, 8, 1, 10),

('Gemma Galgani', 'gemma-galgani', 'An Italian mystic renowned for receiving the stigmata and experiencing profound ecstatic visions.', 'St. Gemma Galgani was born in Italy and devoted her life to prayer and the deep love of Jesus Christ. Known for her mystical experiences, including the stigmata, she endured great suffering yet remained a beacon of faith. Her legacy continues to inspire countless individuals seeking solace and guidance in their spiritual journeys.', 'I desire to love God more than anything else.', 'April 11', NULL, 1, 6, 4, 4, 1, 10),

('Leopold Mandić', 'leopold-mandi', 'A devoted Croatian Capuchin recognized as the apostle of confession.', 'St. Leopold Mandić was a Croatian Capuchin friar known for his extraordinary dedication to the sacrament of confession, often spending up to 15 hours a day in the confessional. His life was characterized by a deep commitment to forgiveness and reconciliation, which inspired many to seek spiritual guidance through him. Despite facing numerous challenges, he remained humble and devoted to serving others until his death in 1942.', 'Forgive and love, it is our duty, and it is the hardest thing to do.', 'May 12', NULL, 2, 10, 1, 1, 1, 1),

('Charbel Makhlouf', 'charbel-makhlouf', 'A Lebanese Maronite monk renowned for his profound spirituality and posthumous miracles.', 'St. Charbel Makhlouf was a devout Maronite monk who embraced a life of solitude and contemplation, dedicating himself wholly to God. He lived a simple yet profound life in a hermitage in Lebanon, where his deep prayer and asceticism drew many to the faith. After his death, countless miracles were attributed to his intercession, solidifying his legacy as a powerful saint in the Catholic Church.', 'Pray to love God with all your heart.', 'July 24', NULL, 10, 2, 1, 1, 1, 2),

('Pedro Calungsod', 'pedro-calungsod', 'A Filipino teenage catechist who was martyred in Guam while defending a priest.', 'St. Pedro Calungsod was a devoted catechist who, at a young age, demonstrated remarkable dedication to his faith. His life was profoundly marked by his commitment to serving God and the Church, culminating in his martyrdom on the island of Guam. He is remembered not just for his courage, but also for inspiring young people to embrace their faith with zeal.', 'I will always be ready to lay down my life for the Lord and His mission.', 'April 2', NULL, 2, 2, 1, 10, 1, 8),

('Turibius of Mogrovejo', 'turibius-of-mogrovejo', 'Archbishop of Lima who evangelized Peru and defended indigenous rights.', 'St. Turibius of Mogrovejo was a Spanish priest who became the Archbishop of Lima during the Spanish colonization of South America. He tirelessly worked to evangelize the indigenous peoples and fought for their rights against colonial injustices. His dedication to reforming the Church and promoting justice has made him a revered figure in the history of Peru.', 'A true pastor must not only think of his own salvation, but also of that of his flock.', 'March 23', NULL, 1, 1, 3, 5, 1, 10),

('José Sánchez del Río', 'jos-s-nchez-del-r-o', 'A courageous teenage martyr who bravely upheld his Christian faith during the Cristero War.', 'St. José Sánchez del Río was a young Mexican martyr who lost his life at the tender age of 14 for his unwavering commitment to Christ during the Cristero War. After refusing to renounce his faith, he was tortured and ultimately executed, becoming a symbol of youthful conviction and resistance. His powerful legacy continues to inspire countless young people to stand firm in their beliefs.', 'Viva Cristo Rey!', 'February 10', NULL, 1, 1, 1, 10, 1, 3),

('Mariana de Jesús', 'mariana-de-jes-s', 'Ecuadorian mystic known for her self-sacrifice during a plague and earthquake.', 'St. Mariana de Jesús, born in Quito, Ecuador, dedicated her life to prayer and selflessness in the face of communal suffering. During horrific plagues and earthquakes, she offered her life for the well-being of her fellow citizens, embodying profound love and devotion. Her mystical experiences and commitment to God have made her a beloved figure in her homeland.', 'Lord, I offer my life for the cessation of these calamities.', 'May 26', NULL, 7, 5, 1, 1, 1, 10),

('Peter of Alcántara', 'peter-of-alc-ntara', 'A Spanish Franciscan mystic known for his intense commitment to penance and spiritual guidance, particularly in his support of St. Teresa of Ávila.', 'St. Peter of Alcántara was a dedicated Franciscan who exemplified the life of deep contemplation and penitential practices. He played a significant role in the reform of the Franciscan Order alongside St. Teresa of Ávila, encouraging a return to strict observance. His teachings and spiritual writings continue to inspire those seeking a deeper relationship with God through prayer and asceticism.', 'The soul that takes for its guide the Spirit of God will never be deceived.', 'October 19', NULL, 1, 1, 1, 1, 1, 10),

('John of Ávila', 'john-of-vila', 'A prominent Spanish priest and Doctor of the Church known for his profound spiritual writings and guidance to many saints.', 'St. John of Ávila was a dedicated priest and reformer who played a significant role in the spiritual revival of 16th-century Spain. He is celebrated for his deep insights and teachings on the spiritual life, which influenced many saints, including St. Teresa of Ávila and St. John of the Cross. Recognized as a Doctor of the Church, his legacy endures through his writings and the spiritual direction he provided to countless individuals seeking a deeper relationship with God.', 'In the pursuit of truth, do not allow the motive to place your faith solely in your own merits.', 'May 10', NULL, 4, 10, 8, 2, 4, 2),

('Anthony Mary Claret', 'anthony-mary-claret', 'Spanish archbishop and founder of the Congregation of Missionary Sons of the Immaculate Heart of Mary (Claretians).', 'St. Anthony Mary Claret was a passionate preacher and reformer dedicated to spreading the Gospel through literature and social justice. He founded the Claretian order to focus on education and missionary work, significantly impacting many lives. Known for his fiery love for the Virgin Mary, he emphasized the importance of faith in everyday life.', 'Speak the truth and do not be afraid.', 'October 24', NULL, 3, 10, 1, 8, 10, 8),

('Peter Julian Eymard', 'peter-julian-eymard', 'He is revered as the Apostle of the Eucharist and founded the Blessed Sacrament Fathers.', 'Born in France, St. Peter Julian Eymard dedicated his life to promoting devotion to the Eucharist. He founded the Congregation of the Blessed Sacrament to foster Eucharistic worship and ensure that the presence of Christ in the Eucharist was honored and celebrated. His teachings and writings continue to inspire countless faithful in their spiritual journeys.', 'The Eucharist is the bread of life, the source of all grace.', 'August 2', NULL, 10, 8, 1, 3, 5, 10),

('John Eudes', 'john-eudes', 'He was a French priest and founder of the Congregation of Jesus and Mary, renowned for his devotion to the Sacred Hearts of Jesus and Mary.', 'St. John Eudes dedicated his life to promoting the devotion to the Sacred Hearts of Jesus and Mary during a time of significant religious upheaval. He founded the Congregation of Jesus and Mary and played a crucial role in the spiritual renewal of France. His teachings continue to inspire devotion and a deeper understanding of Christ''s love.', 'I will not rest until I see the hearts of Jesus and Mary enthroned in all the hearts of men.', 'August 19', NULL, 2, 10, 1, 6, 8, 4),

('Claude de la Colombière', 'claude-de-la-colombi-re', 'St. Claude de la Colombière was a Jesuit priest recognized for his role as the spiritual director to St. Margaret Mary Alacoque.', 'Born in 1641 in France, St. Claude de la Colombière devoted his life to the Society of Jesus. He played a crucial role in promoting devotion to the Sacred Heart of Jesus through his guidance of St. Margaret Mary Alacoque. His dedication to teaching and mentorship left a lasting impact on the Jesuit community and the broader church.', 'To live without hope is to cease to live.', 'February 15', NULL, 6, 10, 4, 2, 4, 4),

('Josaphat', 'josaphat', 'Martyr for the unity of the Eastern and Western Churches.', 'St. Josaphat, born in the late 16th century in Ukraine, became an influential archbishop known for his fervent advocacy for the unity of the Eastern Orthodox and Roman Catholic Churches. His dedication in promoting reconciliation and understanding led to his martyrdom in 1623, as he was brutally killed by those opposed to his mission. Celebrated as a saint, he continues to inspire efforts toward ecumenical dialogue and unity among Christians today.', 'I stand before you now not as a persecutor, but as a shepherd willing to lay down my life for my sheep.', 'November 12', NULL, 1, 1, 1, 10, 1, 3),

('Elizabeth of the Trinity', 'elizabeth-of-the-trinity', 'A French Carmelite mystic known for her profound teachings on the indwelling Trinity.', 'St. Elizabeth of the Trinity was a significant figure in the Carmelite order, whose spiritual writings emphasized the presence of God within the soul. She devoted her life to contemplation and the pursuit of holiness, creating a profound legacy that continues to inspire many. Her mystical insights provide a pathway to understanding the divine relationship each person can cultivate in their life.', 'The more we keep silence, the more we shall hear the voice of God.', 'November 8', NULL, 10, 1, 1, 1, 1, 7),

('Marcellin Champagnat', 'marcellin-champagnat', 'Founder of the Marist Brothers, dedicated to the education of youth.', 'St. Marcellin Champagnat was a French priest who recognized the urgent need for educational reform for the young. He established the Marist Brothers in 1817, emphasizing a curriculum rich in faith and moral values. His legacy continues through the thousands of Marist schools worldwide that serve youth in diverse communities.', 'To teach is to touch a life forever.', 'June 6', NULL, 1, 10, 1, 1, 1, 6),

('Mary MacKillop', 'mary-mackillop', 'Pioneer of Catholic education in Australia and founder of the Sisters of St. Joseph.', 'St. Mary MacKillop was the first Australian to be canonized as a saint in the Catholic Church. She dedicated her life to educating the underprivileged, particularly the poor and Aboriginal children, often overcoming significant challenges. Her legacy is celebrated through the continued work of the Sisters of St. Joseph across Australia and beyond.', 'If you have a good spirit, you will inspire hope in others.', 'August 8', NULL, 1, 8, 1, 10, 1, 5),

('Alphonsa of the Immaculate Conception', 'alphonsa-of-the-immaculate-conception', 'First woman from India to be canonized, who offered her suffering for the salvation of souls.', 'St. Alphonsa, born in the Indian state of Kerala, embraced a life of intense suffering and devotion. Despite physical ailments throughout her life, she maintained a profound faith and dedicated her trials to God. Her beatification and subsequent canonization have inspired countless Christians, particularly in India, to find grace in their own struggles.', 'I have found my heaven on earth, for I am with you, Jesus.', 'July 28', NULL, 2, 1, 1, 1, 1, 10),

('Laura Montoya', 'laura-montoya', 'A dedicated Colombian foundress who evangelized and uplifted the indigenous peoples of Latin America.', 'St. Laura Montoya was a pioneering missionary who devoted her life to serving the indigenous communities of Colombia. Through her efforts, she founded the Missionary Sisters of Mary Immaculate, working tirelessly to promote education and faith among marginalized populations. Her legacy continues to inspire the commitment to social justice and spiritual growth within the Church.', 'I see you, Lord, in the simplest and most humble people.', 'October 21', NULL, 1, 10, 1, 8, 4, 2),

('Basil the Great', 'basil-the-great', 'A renowned theologian and one of the Cappadocian Fathers who played a crucial role in the development of monasticism and the defense of Trinitarian doctrine.', 'St. Basil the Great was a prominent bishop and theologian in the early Church, known for his deep commitment to Christian doctrine and ascetic life. He established communal monasticism, creating rules that shaped monastic life in the Eastern Church. His writings and teachings continue to influence Christian thought and practice today.', 'In the matter of a man''s life, one ought to strive against one''s own negligence.', 'January 2', NULL, 1, 5, 10, 2, 3, 2),

('Gregory of Nazianzus', 'gregory-of-nazianzus', 'A key figure in early Christian theology and a Doctor of the Church.', 'St. Gregory of Nazianzus, born in Cappadocia, was a prominent theologian who played a crucial role in the early Church''s development. He is especially remembered for his eloquent sermons and writings that shaped the understanding of the Trinity. As a former Patriarch of Constantinople, he guided the church during a time of significant doctrinal conflict.', 'A theologian is one who prays truly', 'January 2', NULL, 5, 1, 10, 1, 3, 3),

('Leo the Great', 'leo-the-great', 'He was a significant Pope who defined Christology and confronted the threat posed by Attila the Hun.', 'St. Leo the Great served as Pope from 440 to 461 and was a pivotal figure in the development of the Church''s doctrine. He is best known for his theological contributions, particularly at the Council of Chalcedon, where he affirmed the two natures of Christ. His diplomatic efforts helped avert the sacking of Rome by Attila the Hun, securing his legacy as a great leader and teacher.', 'The unity of the divine essence is not broken by the distinction of the persons.', 'November 10', NULL, 1, 1, 1, 10, 1, 3),

('Pius X', 'pius-x', 'St. Pius X was a Pope renowned for promoting early Communion for children and reforming liturgical practices.', 'Born in Riese, Italy, St. Pius X served as Pope from 1903 until his death in 1914, leading significant reforms in the Church. His advocacy for the reception of Holy Communion at an early age transformed the spiritual lives of many children. St. Pius X is remembered for his humble demeanor, strong leadership, and dedication to restoring the Church''s focus on the Eucharist.', 'Holy Communion is the shortest and safest way to Heaven.', 'August 21', NULL, 3, 7, 3, 7, 1, 10),

('Irenaeus of Lyon', 'irenaeus-of-lyon', 'An early Church Father known for his fight against Gnosticism and his theological writings.', 'St. Irenaeus of Lyon was a prominent early Christian theologian and bishop who played a crucial role in the development of Christian doctrine. He is primarily remembered for his work ''Against Heresies,'' where he systematically refuted Gnostic teachings and emphasized the importance of apostolic tradition. His commitment to the truth of faith and the unity of the Church has left a lasting legacy in Christianity.', 'The Scriptures are indeed full of the abundance of the Spirit of God.', 'June 28', NULL, 1, 3, 10, 3, 1, 1),

('Justin Martyr', 'justin-martyr', 'An early Christian apologist, St. Justin defended the faith against philosophical and pagan challenges.', 'St. Justin Martyr was a notable early Christian thinker who used his philosophical background to articulate and defend the Christian faith. He engaged in dialogues with various philosophers and was steadfast in his beliefs, ultimately facing martyrdom for his convictions. His works laid a foundation for Christian apologetics and significantly influenced later theological discourse.', 'No one can put a limit on either the exercise or the end of human knowledge.', 'June 1', NULL, 1, 1, 10, 5, 1, 3),

('Polycarp', 'polycarp', 'An early Christian bishop and martyr, Polycarp was a direct disciple of St. John the Apostle.', 'St. Polycarp served as the Bishop of Smyrna and was renowned for his unwavering faith amidst persecution. At the age of 86, he faced martyrdom with remarkable courage, famously refusing to renounce his faith. His legacy is celebrated by the early Church and remains an inspiration for many believers today.', 'Eighty-six years have I served Him, and He has done me no wrong. How can I blaspheme my King and Savior?', 'February 23', NULL, 1, 1, 1, 10, 1, 3),

('Cyprian', 'cyprian', 'St. Cyprian was a notable early Church father and martyr known for his writings on Church unity and leadership.', 'St. Cyprian was the Bishop of Carthage and played a crucial role in the early Christian community during a time of persecution. He wrote extensively, emphasizing the importance of unity within the Church and the significance of the bishop''s authority. His steadfast faith led to his martyrdom under the persecution of Emperor Valerian.', 'He who does not have the Church as his mother does not have God as his Father.', 'September 16', NULL, 1, 8, 10, 10, 1, 3),

('Hilary of Poitiers', 'hilary-of-poitiers', 'A staunch defender of Trinitarianism against Arianism in the Western Church.', 'St. Hilary of Poitiers was a prominent theologian and bishop who ardently defended the doctrine of the Trinity during the Arian controversy. His extensive writings, particularly ''On the Trinity,'' have earned him the title ''Doctor of the Church'' for their depth and clarity on Christian doctrine. He traveled extensively, confronting heresy and promoting true Christian belief in a challenging era for the faith.', 'He who is afraid of the Lord is not worthy of Him.', 'January 13', NULL, 2, 1, 10, 5, 1, 5),

('Norbert', 'norbert', 'He founded the Premonstratensian order and devoted his life to reforming others through deep holiness.', 'St. Norbert was born around 1080 in Xanten, Germany, and experienced a profound conversion after a near-death experience. Committed to reforming the clergy and promoting a communal monastic life, he founded the Premonstratensian order, emphasizing discipline and spiritual integrity. He played a pivotal role in advocating for peace during his lifetime and continued to inspire generations through his dedication to God and the Church.', 'The greatest tenderness of heart and the most fervent love of God are found in true priests.', 'June 6', NULL, 4, 10, 1, 3, 1, 4),

('Bruno', 'bruno', 'Founded the Carthusian order, emphasizing a life of solitude and prayer.', 'St. Bruno was a profound spiritual figure who established the Carthusian monastic order in the early 11th century. He sought a deeper relationship with God through radical solitude and ascetic practices, advocating for a quiet contemplative life. His legacy endures as a testament to the power of silence and prayer in the pursuit of holiness.', 'In the silence of the soul, we find God.', 'October 6', NULL, 3, 5, 1, 1, 1, 10),

('Romuald', 'romuald', 'He founded the Camaldolese order and significantly reformed monastic life in the early medieval period.', 'St. Romuald was a pivotal figure in monastic reform during the 11th century, known for establishing the Camaldolese order, which emphasized solitude and contemplation. His life was marked by a deep commitment to prayer and the search for a more austere lifestyle, leading him to inspire countless others in their spiritual journey. Throughout his lifetime, Romuald''s teachings promoted a return to the core values of monasticism, focusing on discipline and solitude.', 'In the same way that we care for the Church, so we must care for ourselves.', 'June 19', NULL, 10, 1, 1, 2, 1, 6),

('Anthony the Great', 'anthony-the-great', 'Considered the father of monasticism, he dedicated his life to God in the Egyptian desert.', 'St. Anthony the Great, born around 251 in Egypt, is revered as a pioneer of monastic life, having spent years in solitude and prayer in the desert. His profound spiritual experiences and battles against temptation have inspired countless followers seeking a deeper relationship with God. St. Anthony''s teachings on humility and the importance of community life in faith continue to resonate in Christian spirituality today.', 'The greatest response to the devil is the Holy Scriptures.', 'January 17', NULL, 10, 3, 1, 2, 1, 3),

('John Damascene', 'john-damascene', 'A Doctor of the Church known for his defense of icons and extensive theological writings.', 'St. John Damascene was a prominent theologian and defender of the veneration of icons during the Byzantine era. He served as a monk and priest, producing influential works that shaped Christian thought and practice. His eloquent writings and teachings continue to inspire theologians and artists alike.', 'I do not worship matter, I worship the Creator of matter.', 'December 4', NULL, 3, 1, 8, 8, 5, 10),

('Ephrem the Syrian', 'ephrem-the-syrian', 'St. Ephrem was a prominent theologian and hymn writer in the early Church, renowned for his deep spirituality and poetic expression.', 'St. Ephrem the Syrian, born in Nisibis, was a key figure in the development of Christian hymnody and theology during the 4th century. As a Doctor of the Church, his writings profoundly influenced both Eastern and Western Christian thought. His work, rich in poetic imagery, emphasizes the importance of divine grace and the inner life of faith.', 'The soul is like a bird', 'June 9', NULL, 4, 4, 4, 1, 4, 10),

('Cajetan', 'cajetan', 'Co-founder of the Theatines, committed to helping the poor and relying on Divine Providence.', 'St. Cajetan was a dedicated reformer and one of the founders of the Congregation of Clerics Regular, known as the Theatines. Throughout his life, he focused on serving the less fortunate and restoring moral integrity to the clergy. His unwavering faith in God’s provision inspired many to trust in Divine Providence during difficult times.', 'He who trusts in Providence will never be disappointed.', 'August 7', NULL, 1, 8, 1, 1, 1, 10),

('Aloysius Gonzaga', 'aloysius-gonzaga', 'Young Jesuit who renounced wealth and died caring for plague victims.', 'Born into a noble family in Lombardy, Italy, St. Aloysius Gonzaga chose a life of poverty and service from a young age. He joined the Jesuits and dedicated his life to the spiritual and physical well-being of others, particularly during the plague outbreak in Rome. His selfless acts ultimately led to his early death at the age of 23, inspiring generations to follow his example of holiness and dedication.', 'I must die, but I do not fear death, for I am not in sin.', 'June 21', NULL, 1, 10, 1, 5, 1, 8),

('Stanislaus Kostka', 'stanislaus-kostka', 'A devoted Polish Jesuit novice who journeyed 450 miles to join the Jesuits.', 'St. Stanislaus Kostka was a young Polish Jesuit novice known for his unwavering faith and determination. After experiencing a profound spiritual calling, he traveled 450 miles to join the Jesuit order, despite facing numerous obstacles. His short life was marked by extraordinary devotion to God and the Virgin Mary, inspiring many to pursue holiness.', 'I long to see Jesus, my love and my goal.', 'November 13', NULL, 2, 1, 1, 10, 1, 8),

('John Baptist de la Salle', 'john-baptist-de-la-salle', 'He founded the Institute of the Brothers of the Christian Schools and significantly advanced modern education practices.', 'St. John Baptist de la Salle was a pioneering figure in education and founded the Institute of the Brothers of the Christian Schools to provide quality education to the poor. His innovative teaching methods and commitment to the holistic development of students laid the foundation for modern educational systems. Today, he is remembered not only as a saint but also as a visionary in the field of education.', 'Let us hold ourselves to a high standard', 'April 7', NULL, 1, 10, 1, 4, 4, 8),

('Vincent Ferrer', 'vincent-ferrer', 'St. Vincent Ferrer was a remarkable Dominican preacher known for his fervent evangelization efforts and miraculous deeds.', 'Born in Valencia, Spain, St. Vincent Ferrer became a powerful preacher who traveled across Europe, spreading the Christian faith during a tumultuous period. He is renowned for his miraculous healings and prophetic visions, inspiring countless followers. His legacy endures as a vital figure in the Dominican Order and the history of the Church.', 'The devil can do nothing against a man who is living in grace.', 'April 5', NULL, 1, 1, 1, 8, 1, 10),

('Bernardine of Siena', 'bernardine-of-siena', 'A renowned Franciscan preacher who emphasized devotion to the Holy Name of Jesus.', 'St. Bernardine of Siena was a 15th-century Franciscan friar known for his powerful preaching and dedication to spreading the message of Christ. He played a crucial role in promoting the devotion to the Holy Name of Jesus, and his sermons drew large crowds throughout Italy. His efforts in reforming the Franciscan order and advocating for peace made him a significant figure in the Church during his lifetime.', 'The name of Jesus, my beloved, is the glory of the preachers.', 'May 20', NULL, 3, 8, 1, 3, 5, 10),

('Catherine Labouré', 'catherine-labour', 'Receiving visions of the Miraculous Medal from the Blessed Virgin Mary.', 'Born in France, St. Catherine Labouré dedicated her life to serving God and the poor. In 1830, she received a series of extraordinary visions of the Blessed Virgin Mary, during which she was instructed to have the Miraculous Medal created. Her humility and devotion have inspired countless faithful, and she was canonized in 1947.', 'The ball you see represents the whole world, especially France, and each person in particular.', 'November 28', NULL, 3, 3, 1, 1, 1, 10),

('Geneviève', 'genevi-ve', 'Patroness of Paris who led the city in prayer during invasions.', 'St. Geneviève was a devout young woman from Nanterre, France, who dedicated her life to God. She is best remembered for her intercessory prayers that helped protect Paris from barbarian invasions in the 5th century. Despite facing significant opposition, her unwavering faith and leadership inspired many in the community to trust in divine protection during perilous times.', 'God is with us', 'January 3', NULL, 2, 5, 1, 10, 3, 3),

('Isidore the Farmer', 'isidore-the-farmer', 'A humble farmer renowned for his piety and generosity towards the needy.', 'St. Isidore the Farmer is revered for his deep faith and connection to the land, embodying the spirit of Christian labor. He is often depicted surrounded by animals, reflecting his kindness and stewardship over creation. His commitment to daily Mass and charity towards the poor made him a beloved figure in his community.', 'Without God, you cannot work', 'May 15', NULL, 3, 10, 1, 1, 1, 4),

('Martha', 'martha', 'Sister of Mary and Lazarus, known for her service and hospitality towards Jesus.', 'St. Martha is known for her unwavering faith and commitment to serving Jesus and her family. As the sister of Mary and Lazarus, she welcomed Christ into her home and displayed deep devotion amidst her busy life. Her character exemplifies the value of service and hospitality in the Christian faith.', 'You should not be troubled, for He is the one who can awaken the dead.', 'July 29', NULL, 1, 6, 1, 1, 1, 10),

('Philip the Apostle', 'philip-the-apostle', 'One of the Twelve Apostles who was instrumental in bringing others to Jesus.', 'St. Philip the Apostle is remembered for his role in the early ministry of Jesus Christ and for bringing Nathanael to Him. He actively preached the Gospel in Asia Minor and is recognized for his commitment to evangelization. His direct inquiries to Jesus reveal a sincere seeker of truth and understanding.', 'Lord, show us the Father, and it is enough for us.', 'May 3', NULL, 1, 1, 1, 1, 1, 10),

('Bartholomew', 'bartholomew', 'One of the Twelve Apostles renowned for his faith and missionary work.', 'St. Bartholomew, also known as Nathanael, was one of Jesus'' closest disciples and is celebrated for his unwavering faith and commitment to spreading the Gospel. According to tradition, he was martyred by being flayed alive, symbolizing his ultimate sacrifice for his beliefs. His steadfast character and dedication to Christ make him a prominent figure in the early Christian church.', 'In Israel, a man like this is truly a son of God!', 'August 24', NULL, 2, 1, 1, 5, 1, 10),

('Matthias', 'matthias', 'Chosen by lot to replace Judas Iscariot as one of the Twelve Apostles.', 'St. Matthias is renowned for his unwavering faith, having been selected as an apostle shortly after the Ascension of Christ. His commitment to spreading the gospel and serving the early Church exemplifies the virtues of obedience and perseverance. Despite his lesser-known status among the apostles, Matthias''s role was pivotal in maintaining the integrity of the Twelve.', 'It is necessary that one become a witness of the resurrection.', 'May 14', NULL, 3, 5, 1, 5, 1, 10),

('Simon the Apostle', 'simon-the-apostle', 'A dedicated apostle known for his fervent zeal for Christ and missionary work.', 'St. Simon the Zealot was one of the Twelve Apostles of Jesus, distinguished by his passionate commitment to spreading the gospel. After the Ascension of Christ, he traveled extensively, with missionary efforts reportedly leading him to Persia. His legacy endures as a testament to faith and courage in the face of adversity.', 'If I could be the martyr whose blood would make the whole world believe in Jesus, I would welcome it.', 'October 28', NULL, 1, 4, 1, 10, 4, 6),

('Hedwig', 'hedwig', 'Duchess of Silesia who dedicated herself to charitable works and the religious life after her husband''s death.', 'St. Hedwig was born in Bavaria and became the Duchess of Silesia through her marriage. Following the death of her husband, she devoted her life to charitable acts and the education of her children in faith. Her legacy lives on as an exemplar of humility and service to the impoverished.', 'The greatest joy is to serve and love the least among us.', 'October 16', NULL, 10, 10, 1, 1, 3, 8),

('Gertrude the Great', 'gertrude-the-great', 'A revered Benedictine mystic renowned for her profound visions and writings on the love of Christ.', 'St. Gertrude the Great was a Benedictine nun in Germany who experienced mystical revelations that deepened her relationship with God. Her profound writings, particularly on the Sacred Heart of Jesus, have inspired countless readers over the centuries. As a prominent figure in medieval spirituality, she is celebrated for her contemplative life and devotion to the souls in Purgatory.', 'It is with a full heart that I stand before You, imploring Your mercy, Lord, for the souls that suffer.', 'November 16', NULL, 10, 4, 1, 1, 1, 7),

('Rose of Viterbo', 'rose-of-viterbo', 'A courageous young visionary who passionately preached for the faith and stood up against Emperor Frederick II.', 'St. Rose of Viterbo was a remarkable young woman known for her fervent preaching and commitment to the Christian faith. Born in Viterbo, Italy, she boldly challenged the political and religious authorities of her time. Her unwavering courage and deep devotion to Christ inspired many in her community, leaving a lasting legacy as a champion of faith.', 'I am the servant of the Lord, may it be done to me according to Your word.', 'September 4', NULL, 1, 1, 1, 10, 6, 3),

('Colette', 'colette', 'Reformed the Poor Clares and established numerous convents across Europe.', 'St. Colette was a visionary mystic born in Corbie, France, who dedicated her life to the reform of the Poor Clares. Despite personal challenges and the skepticism of her peers, she successfully founded seventeen convents, revitalizing the order''s commitment to contemplation and prayer. Her legacy lives on through the lives of those she inspired and the communities she established, which continue to thrive in devotion today.', 'Faith is the great foundation of all virtues and the mother of hope.', 'March 6', NULL, 3, 7, 3, 7, 1, 10),

('Hubert', 'hubert', 'He is known for his dramatic conversion while hunting, inspired by a vision of a crucifix between a stag''s antlers.', 'St. Hubert was a nobleman from Toulouse who experienced a profound conversion to Christianity during a hunting expedition. Following his transformation, he became a bishop and devoted his life to preaching and serving the community. His legacy as the patron saint of hunters and wildlife reflects his deep connection to nature and the divine.', 'O God, who didst call the blessed Hubert from the chase of the stag to become a shepherd of souls, grant that we may imitate his example.', 'November 3', NULL, 5, 1, 5, 3, 5, 10),

('Fiacre', 'fiacre', 'An Irish hermit revered for his miraculous garden and extraordinary healing abilities.', 'St. Fiacre was an Irish monk who settled in France, where he cultivated a legendary garden that was said to possess miraculous healing powers. His life as a hermit reflected his deep devotion to God and nature, often intertwining the act of gardening with spirituality. Fiacre’s legacy thrives today as he continues to inspire those who work the land and care for its bounties.', 'The earth is a glorious testament to God''s creativity and bounty.', 'September 1', NULL, 6, 4, 1, 4, 2, 10),

('Lydwina of Schiedam', 'lydwina-of-schiedam', 'She is known for enduring a life of severe suffering after a skating accident, which she offered for the conversion of sinners.', 'St. Lydwina of Schiedam was a Dutch mystic who, after a tragic accident at the age of 15, endured a lifetime of suffering while offering her pain for the salvation of others. Despite her afflictions, she became a source of inspiration and intercession for those who are ill. Her deep spirituality and devotion to Christ exemplified the power of suffering in the pursuit of holiness.', 'I suffer not for myself but for the love of God and the salvation of souls.', 'April 14', NULL, 1, 3, 1, 5, 1, 10),

('Elizabeth of Portugal', 'elizabeth-of-portugal', 'Known for her remarkable efforts in brokering peace among warring factions and her deep commitment to charitable works.', 'St. Elizabeth of Portugal was a queen renowned for her peacebuilding efforts during a time of family conflicts and war. She dedicated her life to helping the needy and was known to perform miracles, including healing the sick. Her legacy of charity and diplomacy continues to inspire people to seek peace in their own lives.', 'I would rather die than offend God.', 'July 4', NULL, 2, 10, 1, 1, 1, 1),

('Bénézet', 'b-n-zet', 'A shepherd boy guided by divine vision to construct the iconic bridge of Avignon.', 'St. Bénézet, a humble shepherd from Hermillon, France, received a divine mandate to build a bridge over the Rhône River at Avignon. Despite his young age and lack of resources, he inspired others to join him in this monumental task. Today, the Saint''s legacy lives on through the enduring structure that symbolizes faith and determination.', 'In faith, I have built what seemed impossible.', 'April 14', NULL, 2, 4, 1, 1, 1, 10),

('Mary, Mother of God', 'mary-mother-of-god', 'Being the mother of Jesus Christ and a central figure in Christianity.', 'St. Mary is revered as the mother of Jesus Christ, embodying grace and faith. Her acceptance of God’s will makes her a profound example for all Christians, highlighting the importance of trust in divine purpose. She holds a unique position within the Catholic Church, venerated not only for her maternal role but also for her unwavering devotion to God.', 'My soul proclaims the greatness of the Lord', 'January 1', NULL, 3, 10, 4, 1, 1, 3),

('Raymond of Peñafort', 'raymond-of-pe-afort', 'He is known for his significant contributions to canon law and the establishment of the Order of Preachers.', 'St. Raymond of Peñafort was a renowned Spanish priest and Dominican friar who dedicated his life to the service of the Church. He is celebrated for compiling many of the Church''s laws and for promoting the Sacrament of Confession. Revered for his wisdom and commitment to education, he also played a vital role in the Christianization of the Moors in Spain.', 'The greatest among you will be your servant.', 'January 7', NULL, 1, 10, 4, 1, 1, 1),

('Adrian of Canterbury', 'adrian-of-canterbury', 'He was an influential scholar and abbot who helped establish monastic schools in England.', 'St. Adrian of Canterbury was a Benedictine monk who became the abbot of the monastery at Canterbury. He played a pivotal role in fostering education and theological study in 7th-century England. His efforts helped to enhance the intellectual and spiritual vitality of the Church at that time.', 'Education is the foundation upon which we build our future.', 'January 9', NULL, 2, 4, 10, 4, 4, 2),

('William of Bourges', 'william-of-bourges', 'He is known for his contributions to the church as the Archbishop of Bourges and for his commitment to church reform.', 'St. William of Bourges served as Archbishop in the early 13th century, where he worked tirelessly to reform the clerical state and improve church practices. He was deeply dedicated to the poor, providing them with aid and support during his tenure. His legacy is remembered for the influence he had on both the church and society in France.', 'The greatest gift one can give is the gift of love.', 'January 10', NULL, 1, 10, 3, 1, 1, 1),

('Hyginus', 'hyginus', 'St. Hyginus is known for being the Pope who led the early Church during a time of persecution and organizational development.', 'St. Hyginus served as the Pope for a brief period during the early 2nd century, succeeding St. Anacletus. He is remembered for his efforts to strengthen the Church''s structure amid the challenges of the time. His leadership contributed to the establishment of key doctrines and the orderly administration of the growing Christian community.', 'The greatest gift is the freedom of choice.', 'January 11', NULL, 1, 10, 4, 4, 1, 1),

('Paul the Simple', 'paul-the-simple', 'A hermit known for his deep spirituality and simple life of faith.', 'St. Paul the Simple was a hermit who embraced a life of solitude and prayer in the Egyptian desert. Renowned for his innocence and genuine faith, he became a model of simplicity in a world often filled with complexity. His life served as an inspiration to many, showcasing the profound richness found in a humble existence devoted to God.', 'The greatest action is not to act.', 'January 14', NULL, 10, 5, 8, 1, 1, 8),

('Maurus', 'maurus', 'Maurus was a Benedictine monk and is known for being the first disciple of St. Benedict.', 'St. Maurus was born in Italy and became a follower of St. Benedict at the famous monastery of Monte Cassino. He is noted for his role in shaping monastic life and traditions in early Christianity. His commitment to the Benedictine Rule exemplified the values of prayer, work, and community.', 'It is better to make mistakes in kindness than to work miracles in unkindness.', 'January 15', NULL, 3, 10, 1, 4, 1, 3),

('Marcellus I', 'marcellus-i', 'He was the Pope who served during a time of intense persecution of Christians in the early Church.', 'St. Marcellus I was elected Pope in 308 AD and worked tirelessly to maintain the unity of the Church amid growing threats. He faced significant challenges from both outside and within the Christian community due to the ongoing persecutions under Emperor Maxentius. His commitment to the faith and the welfare of the Christian community has left a lasting legacy in the Church.', 'To speak to God is not to speak', 'January 16', NULL, 2, 10, 6, 6, 1, 4),

('Charles of Mount Argus', 'charles-of-mount-argus', 'St. Charles of Mount Argus is known for his compassionate care of the sick and his deep devotion to prayer.', 'Born in the Netherlands, St. Charles worked tirelessly in his priestly ministry, especially in the care of the sick. He was known for his kindness and his ability to comfort those suffering from various ailments. His life exemplified a profound commitment to God and to serving others through love and hope.', 'Prayer is the key to heaven.', 'January 18', NULL, 1, 10, 1, 3, 3, 1),

('Canute', 'canute', 'He was King of Denmark who became a martyr for his faith.', 'St. Canute was the King of Denmark in the early 11th century, known for his devout Christian faith. He worked to strengthen the church in Denmark and was eventually martyred as he sought to impose reforms and unify the Christian faith. His dedication to his beliefs made him an enduring figure of veneration in both Denmark and the wider Christian world.', 'Faith conquers all.', 'January 19', NULL, 1, 4, 1, 10, 1, 3),

('Vincent', 'vincent', 'He is known for his courageous stand for the faith during the persecution of Christians.', 'St. Vincent was one of the early Christian martyrs, known for his unwavering faith in the face of severe torture and persecution. He served as a deacon in the early Church and became a symbol of strength and endurance for Christians throughout the centuries. His martyrdom inspired many to remain steadfast in their beliefs, and he continues to be celebrated as a heroic figure in Christianity.', 'Always be prepared to speak for God''s truth.', 'January 22', NULL, 1, 5, 1, 10, 3, 3),

('Paul the Apostle', 'paul-the-apostle', 'One of the most important figures in early Christianity and author of several New Testament letters.', 'St. Paul, originally known as Saul of Tarsus, experienced a dramatic conversion to Christianity on the road to Damascus. He dedicated his life to spreading the Gospel, establishing churches, and mentoring early Christians. His epistles remain foundational texts for Christian theology and practice.', 'For I am convinced that neither death nor life, neither angels nor demons, neither the present nor the future, nor any powers.', 'January 25', NULL, 1, 1, 3, 10, 8, 2),

('Gildas', 'gildas', 'An influential monk and scholar in early medieval Britain, known for his writings and teachings.', 'St. Gildas was a British monk from the 6th century whose works offer significant insight into the history and spirituality of his time. He is best known for his book ''De Excidio et Conquestu Britanniae'', which reflects on the moral decline of society and the need for reform. His contributions to theology and history have made him a vital figure in early Christian literature.', 'The time for choosing between evil and a good conscience is at hand.', 'January 29', NULL, 2, 4, 10, 2, 1, 4),

('Agenoria', 'agenoria', 'St. Agenoria is known for her steadfast faith and martyrdom during the persecution of Christians.', 'St. Agenoria was a young Christian woman who displayed remarkable courage in the face of persecution. She stood firm in her beliefs and ultimately faced martyrdom for her unwavering faith. Her legacy continues to inspire many to remain steadfast in their convictions.', 'Faith is to believe what we do not see', 'January 30', NULL, 2, 6, 1, 10, 1, 6),

('Andrew Corsini', 'andrew-corsini', 'Known for his work as a bishop and promoting reforms within the Church.', 'St. Andrew Corsini, born into a noble family, chose a life of service to God and became a Carmelite friar. He was later appointed as Bishop of Fiesole, where he devoted himself to the pastoral care of his diocese and the spiritual welfare of its residents. His dedicated approach to reforming ecclesiastical practices and fostering deep spiritual renewal among the clergy and laity established a lasting legacy.', 'We must love our neighbor as ourselves.', 'February 4', NULL, 1, 10, 4, 1, 1, 1),

('Richard of Chichester', 'richard-of-chichester', 'Richard was known for his strong leadership as Bishop of Chichester and his dedication to pastoral care.', 'St. Richard of Chichester was born into a noble family and later became a scholar at the University of Oxford. He was elected Bishop of Chichester and worked tirelessly to reform the church, emphasizing pastoral care for the faithful. His life was marked by a deep commitment to God, and he is remembered for his compassion and integrity.', 'Lord, I am willing to do whatever you wish.', 'February 7', NULL, 1, 10, 1, 4, 1, 1),

('Our Lady of Lourdes', 'our-lady-of-lourdes', 'The apparitions of the Virgin Mary to St. Bernadette in Lourdes, France.', 'St. Our Lady of Lourdes appeared to a young girl named Bernadette Soubirous in a grotto near Lourdes, France, in 1858. During these apparitions, she identified herself as the Immaculate Conception and conveyed messages of prayer and penance. Lourdes has since become a major pilgrimage site known for miraculous healings and a place of devotion.', 'I cannot promise you happiness in this life, but I can promise you happiness in the next.', 'February 11', NULL, 1, 10, 1, 1, 1, 4),

('Édouard', 'douard', 'St. Édouard is known for his piety and dedication to his duties as the King of England.', 'St. Édouard, also known as King Edward the Confessor, was a beloved ruler of England renowned for his commitment to justice and his compassionate governance. His reign was marked by a deep devotion to God, and he played a significant role in promoting the Christian faith throughout his kingdom. After his death, he was canonized due to the miraculous healings and favors attributed to him.', 'The only thing I can do is pray for you.', 'February 12', NULL, 4, 10, 6, 1, 1, 6),

('Catherine de Ricci', 'catherine-de-ricci', 'A mystic and Dominican nun known for her intense spiritual life and devotion.', 'St. Catherine de Ricci was an Italian nun celebrated for her profound spiritual experiences and commitment to the Dominican order. She spent much of her life in a convent in Florence, where her visions and dedication to prayer inspired many around her. St. Catherine''s life exemplifies deep faith and the importance of community in spiritual growth.', 'We must never forget that we are in the world, but not of the world.', 'February 13', NULL, 4, 10, 1, 4, 1, 10),

('Febronia', 'febronia', 'She is venerated as a virgin martyr in the Christian tradition.', 'St. Febronia was a Christian virgin and martyr who lived during the reign of Emperor Diocletian. She endured severe torture and persecution for her faith before ultimately giving her life for Christ. Her story inspires many young women to stand firm in their beliefs amidst trials.', 'The glory of God is man fully alive.', 'February 16', NULL, 3, 8, 1, 10, 5, 10),

('Alexis of Rome', 'alexis-of-rome', 'He is known for his humble life and deep devotion to God, often considered a patron of the poor.', 'St. Alexis was born into a wealthy Roman family, but he chose a life of poverty and devotion, secretly helping the marginalized. After leaving his family, he returned incognito, living in the shadows to serve those in need. His piety and commitment inspired many, and he is venerated as a model of selfless love.', 'The greatest grace is to be humble.', 'February 17', NULL, 3, 10, 1, 3, 1, 3),

('Simeon', 'simeon', 'He is known for being the first Christian martyr in Jerusalem.', 'St. Simeon was an early Christian leader who played a pivotal role in the spread of the faith during the first century. He is often remembered for his unwavering commitment to Christ, culminating in his martyrdom for his beliefs. His legacy continues to inspire Christians to stand firm in their faith despite challenges.', 'Faith is the light that shines in the dark.', 'February 18', NULL, 3, 8, 8, 10, 5, 5),

('Conrad of Piacenza', 'conrad-of-piacenza', 'Known for his deep spirituality and commitment to asceticism.', 'St. Conrad of Piacenza was a hermit who lived a life of penance and devotion to prayer. After a life-changing experience with a vision, he dedicated himself to caring for the poor and healing sick animals. His profound commitment to a life of solitude and prayer led many to seek his counsel and support throughout his lifetime.', 'Prayer is an act of love.', 'February 19', NULL, 2, 10, 6, 1, 1, 4),

('Peter Damian', 'peter-damian', 'He was a prominent reformer of the Church and an advocate for clerical celibacy.', 'St. Peter Damian was a Benedictine monk and a cardinal who played a critical role in the reform of the clergy during the 11th century. He was known for his intense spirituality and his dedication to God, earning him the title of Doctor of the Church. His writings emphasized the importance of purity and the need for reform within the Church, making him an influential figure in his time.', 'Be who you are and be that well.', 'February 21', NULL, 3, 10, 10, 7, 1, 10),

('Oswald', 'oswald', 'Oswald is recognized for his martyrdom and dedication to the faith.', 'St. Oswald was a king of Northumbria who played a crucial role in the spread of Christianity in his region. He was known for his deep faith and his commitment to fostering peace and justice. After his martyrdom, he became a venerated saint, influencing many through his exemplary life and sacrifice.', 'As long as I live, I will continue to speak of God''s love.', 'February 24', NULL, 2, 6, 1, 10, 1, 6),

('Cesario', 'cesario', 'St. Cesario is known for his martyrdom during the Diocletian persecution.', 'St. Cesario was a Christian martyr who lived during the early centuries of the Church. He faced persecution for his faith under the Roman Emperor Diocletian and ultimately gave his life in witness to his beliefs. His dedication continues to inspire many who face adversity for their faith.', 'Martyrdom is the witness of the faith, a true testament to the love of Christ.', 'February 25', NULL, 3, 8, 1, 10, 5, 8),

('Alexander of Jerusalem', 'alexander-of-jerusalem', 'He is known for his role as a bishop who defended the faith during the early Church''s struggles with heresies.', 'St. Alexander of Jerusalem served as a prominent bishop during the third century and was an influential leader in the early Christian community. He was recognized for his theological contributions and his efforts to guide believers through various heretical teachings. His commitment to the faith and pastoral care left a lasting impact on the Church.', 'The soul is the seed of faith.', 'February 26', NULL, 1, 10, 8, 4, 2, 4),

('Gabriel of Our Lady of Sorrows', 'gabriel-of-our-lady-of-sorrows', 'He is known for his deep devotion to the passion of Christ and the sorrows of Mary.', 'St. Gabriel of Our Lady of Sorrows was a Passionist cleric known for his fervent spirituality and dedication to prayer. He entered the religious life at a young age and became a model of virtue among his peers. His legacy of promoting devotion to the suffering of Christ and His Blessed Mother inspires many Catholics today.', 'The more you suffer, the more you will love.', 'February 27', NULL, 3, 10, 1, 10, 7, 10),

('Agnes of Bohemia', 'agnes-of-bohemia', 'She is known for her deep devotion to Christ and for her role as a nun and abbess.', 'St. Agnes of Bohemia, a member of the royal family, chose a life of poverty and service to God over worldly power. After founding a convent in Prague, she became its first abbess and dedicated her life to charitable works. Her unwavering faith and commitment to the religious life inspired many during her time and continue to do so today.', 'The world is full of the glory of God.', 'March 2', NULL, 3, 10, 1, 3, 1, 3),

('Kate of Siena', 'kate-of-siena', 'A mystic and theologian known for her writings and influence on the Catholic Church during the Western Schism.', 'St. Kate of Siena was a prominent figure in the 14th-century Church who played a crucial role in advising popes and reforming the Church. Her intense mystical visions and writings, particularly ''The Dialogue'', are still studied for their rich spiritual insights. A lay member of the Dominican Order, she devoted her life to serving the poor and advocating for peace during tumultuous times in Italy.', 'Be who you are and be that well.', 'March 5', NULL, 1, 10, 10, 10, 7, 10),

('Frances of Rome', 'frances-of-rome', 'Founding the Oblates of Mary and serving the poor in Rome.', 'St. Frances of Rome was a devout woman who dedicated her life to helping the needy in the streets of Rome. Despite personal trials, including the loss of her husband, she remained steadfast in her faith and service. She founded a religious community and was known for her mystical visions and deep spirituality.', 'The things of this world are not worth a single tear shed for love of God.', 'March 9', NULL, 2, 5, 1, 3, 1, 10),

('John Ogilvie', 'john-ogilvie', 'A Scottish Jesuit martyr known for his courage in the face of persecution.', 'St. John Ogilvie was a Jesuit priest who returned to Scotland during a time of severe anti-Catholic sentiment. He dedicated his life to the pastoral care of the faithful, enduring imprisonment and torture for his beliefs. Ultimately, he was hanged in 1615, becoming a symbol of steadfast faith and commitment to the Gospel.', 'I die for God and the Catholic Church.', 'March 10', NULL, 2, 5, 1, 10, 3, 3),

('Eulogius of Toledo', 'eulogius-of-toledo', 'He is known for his commitment to the faith during the period of Muslim rule in Spain.', 'St. Eulogius was a cleric and theologian who played a pivotal role in the defense of Christianity in 9th-century Spain. He was arrested for his outspoken faith and ultimately martyred for refusing to renounce his beliefs. His writings and his ultimate sacrifice inspired many Christians during a turbulent time in the history of the Church in Spain.', 'The more one serves God, the more one learns to love Him.', 'March 11', NULL, 3, 8, 8, 10, 5, 5),

('Euphrasia', 'euphrasia', 'Known for her deep piety and commitment to monastic life.', 'St. Euphrasia was a noted abbess in the early Christian church, recognized for her extraordinary devotion and leadership among her fellow sisters. She led her community with grace and humility, guiding them in a life of prayer and service. Her legacy continues to inspire many in their spiritual journeys.', 'He who wishes for anything but Christ does not know what he wishes for.', 'March 13', NULL, 4, 10, 6, 4, 1, 4),

('Matilda', 'matilda', 'Matilda was known for her piety and her role in promoting the welfare of her family and the church.', 'St. Matilda was a noblewoman who became the queen consort of Henry I of Germany. She devoted her life to acts of charity and was instrumental in the founding of monasteries. Her legacy endures through her steadfast commitment to faith and community service.', 'Let us trust in God and not grow weary.', 'March 14', NULL, 2, 10, 1, 10, 1, 4),

('Abraham', 'abraham', 'He is known for his piety and the miracles attributed to him during his lifetime.', 'St. Abraham was a monastic leader who dedicated his life to the service of God and the nurturing of his fellow believers. He was renowned for his ascetic lifestyle and the miraculous healings he performed. His legacy continues to inspire those seeking a deeper spiritual life and commitment to faith.', 'Faith is the light that guides us through the darkness.', 'March 16', NULL, 4, 10, 1, 2, 4, 6),

('Cyril of Jerusalem', 'cyril-of-jerusalem', 'St. Cyril is known for his contributions to Christian catechesis and for his role in the development of the Nicene Creed.', 'Born in Jerusalem around 315, St. Cyril became the bishop of the city and was a prominent figure during the Arian controversy. He is best known for his thorough teachings on the sacraments and the catechism, which helped to shape the Christian faith. His commitment to the truth of the Gospel and the teachings of the Church earned him respect and honor among his peers.', 'Be attentive to your conscience, God speaks to man’s heart.', 'March 18', NULL, 1, 10, 6, 4, 4, 2),

('Cuthbert', 'cuthbert', 'He was known for his piety and dedication to monastic life.', 'St. Cuthbert was a 7th-century monk and bishop known for his faith and miracles. He began his spiritual journey as a shepherd and later joined the monastic community at Melrose. Cuthbert''s life was marked by dedication to prayer, and he became a prominent figure in the spread of Christianity in northern England.', 'The Lord is my shepherd', 'March 20', NULL, 3, 10, 1, 3, 3, 3),

('Enda', 'enda', 'Founder of the monastic school of Aran Islands in Ireland.', 'St. Enda is revered as the founder of monasticism in the Aran Islands, known for his deep spirituality and dedication to God. His influence helped establish a strong Christian presence in Ireland, fostering education and religious life throughout the region. Enda''s legacy endures, inspiring countless followers through his teachings and steadfast commitment to faith.', 'The heart of a man can be his own worst prison.', 'March 21', NULL, 2, 10, 5, 3, 5, 1),

('Nicholas Owen', 'nicholas-owen', 'Nicholas Owen was a Jesuit priest and martyr known for his role in the English Catholic underground.', 'St. Nicholas Owen was a devoted layman and carpenter who worked tirelessly to support the work of the Jesuit missionaries in England. His remarkable skill in building hiding places for priests led to his eventual arrest and torture. Ultimately, he gave his life for the faith, becoming a symbol of courage and loyalty in the face of persecution.', 'The dignity of man is a divine quality.', 'March 22', NULL, 3, 8, 1, 8, 1, 10),

('Emma', 'emma', 'Known for her piety and charitable acts toward the needy.', 'St. Emma was a noblewoman in the Holy Roman Empire, deeply beloved for her selfless devotion to helping the poor and sick. After her husband''s death, she dedicated her life to Christ, often giving away her wealth to alleviate the suffering of those around her. Her unwavering faith and remarkable acts of kindness earned her the title of saint and continue to inspire acts of charity today.', 'Love and kindness are never wasted.', 'March 26', NULL, 1, 10, 1, 3, 1, 3),

('Rupert of Salzburg', 'rupert-of-salzburg', 'He is known for founding the Diocese of Salzburg and spreading Christianity in the region.', 'St. Rupert, the first bishop of Salzburg, is celebrated for his missionary work in the 8th century. He founded the Abbey of St. Peter in Salzburg, which became a center of learning and culture. His influence helped to establish Christianity in the Alpine region, making him a key figure in the spread of the faith in Central Europe.', 'Christ is our peace, and in Him we are saved.', 'March 27', NULL, 1, 10, 6, 8, 4, 1),

('Guntramnus', 'guntramnus', 'He is known for his pious life and contributions to the church in the face of political turmoil.', 'St. Guntramnus was a king of the Franks who ruled with justice and sought to bring peace to his kingdom during a time of division. He was dedicated to the well-being of his people, often building churches and supporting charitable works. His legacy endures as a symbol of humility and devotion amidst power.', 'A true king is one who serves his people.', 'March 28', NULL, 1, 10, 1, 1, 1, 3),

('Jonas', 'jonas', 'St. Jonas is known for being a saint and martyr in the early Christian Church.', 'St. Jonas was a devoted follower of Christ who lived during a time of persecution. He was martyred for his faith and is revered as one of the courageous early saints who stood firm in the face of adversity. His legacy continues to inspire those who seek strength in their beliefs.', 'Courage is not the absence of fear, but the triumph over it.', 'March 29', NULL, 3, 8, 1, 10, 5, 8),

('John Climacus', 'john-climacus', 'He is known for his spiritual work, ''The Ladder of Divine Ascent'', which guides Christians in their spiritual growth.', 'St. John Climacus, a prominent 7th-century monk, dedicated his life to the pursuit of spiritual perfection. He is best known for his writings that provide insight into the ascetic life and the path to holiness. His teachings continue to inspire and guide believers in their spiritual journeys today.', 'If you wish to be rich, do not add to your gold but rather strive to diminish your desires.', 'March 30', NULL, 5, 5, 8, 1, 1, 10),

('Benjamin', 'benjamin', 'A deacon and martyr known for his unwavering faith and dedication to spreading the Gospel.', 'St. Benjamin was a deacon who courageously preached Christianity during a time of persecution. He was captured and subsequently martyred for his faith, serving as an inspiration to many. His steadfast commitment to his beliefs continues to resonate with those who advocate for social justice and human rights.', 'The glory of God is the living man', 'March 31', NULL, 1, 10, 1, 10, 4, 4),

('Hugh of Grenoble', 'hugh-of-grenoble', 'He is recognized for his role in the reform of the Church and the establishment of the Carthusian Order.', 'St. Hugh of Grenoble was a 12th-century bishop known for his profound dedication to the Church and a life of asceticism. He was instrumental in the founding of the Grande Chartreuse, home of the Carthusian monks, emphasizing a life of solitude and prayer. His compassionate leadership and commitment to education left a lasting impact on the Christian community in his time.', 'The Lord has given the world to all who dwell in it, but He has shared it with none so that all can have their own.', 'April 1', NULL, 1, 10, 4, 1, 1, 1),

('Marcellinus', 'marcellinus', 'St. Marcellinus is known for being a Pope and for his martyrdom during the persecution of Christians under Emperor Diocletian.', 'St. Marcellinus served as Pope at a time of great turmoil for Christians in the Roman Empire. He was eventually arrested and executed for his faith, becoming a symbol of courage and steadfastness. His legacy continues to inspire those who face persecution for their beliefs.', 'The blood of martyrs is the seed of the Church.', 'April 6', NULL, 2, 6, 6, 10, 1, 4),

('Julia', 'julia', 'Martyrdom for her Christian faith during the persecution of Christians in North Africa.', 'St. Julia was a young Christian woman who showed remarkable courage by refusing to renounce her faith despite persecution. She was captured by the Romans and endured various tortures before ultimately being martyred. Her steadfastness and bravery inspire many in their faith journey.', 'The more you are in the spirit of Christ, the more everything happens without your knowing it.', 'April 8', NULL, 1, 5, 1, 10, 3, 3),

('William of Eskhill', 'william-of-eskhill', 'William was a devoted hermit known for his ascetic life and deep spirituality.', 'St. William of Eskhill was a revered hermit who dedicated his life to prayer and contemplation in the wilderness. Through his rigorous ascetic practices, he sought to grow closer to God and inspire others toward holiness. His legacy of devotion continues to inspire many on the path of spiritual growth.', 'Prayer is the root of all virtues.', 'April 9', NULL, 4, 6, 6, 1, 1, 10),

('Magdalen of Canossa', 'magdalen-of-canossa', 'Founding the Canossian Daughters of Charity.', 'St. Magdalen of Canossa was an Italian nun and the founder of a religious order dedicated to the spiritual and educational needs of the poor and marginalized. She devoted her life to serving others, establishing several schools and residences throughout Italy. Her legacy continues through the Canossian Sisters, who continue her mission of charity and education around the world.', 'To love is to give oneself without reserve.', 'April 10', NULL, 1, 10, 1, 7, 1, 1),

('Albert the Great', 'albert-the-great', 'He was a pioneering philosopher and scientist, particularly in the fields of natural science.', 'St. Albert the Great was a German Dominican friar and bishop known for his substantial contributions to the study of nature and the integration of faith and reason. His works laid the groundwork for later scientific inquiry and influenced many thinkers, including St. Thomas Aquinas. Revered as a Doctor of the Church, he is celebrated for his extensive writings on various disciplines, including theology, philosophy, and the natural sciences.', 'All sciences are not only in harmony with each other, but are united and connected in a universal science.', 'April 12', NULL, 1, 10, 1, 2, 1, 6),

('Martin I', 'martin-i', 'He is known for his steadfast resistance against the Monothelite heresy.', 'St. Martin I served as pope in the 7th century and is remembered for his courageous stand against the Monothelite doctrine, which claimed that Christ had only one will. His commitment to faith led to his imprisonment and exile by the Byzantine Emperor. His martyrdom and dedication have made him a revered figure in the Catholic Church.', 'The church must be free.', 'April 13', NULL, 1, 10, 1, 8, 1, 4),

('Perfectus', 'perfectus', 'St. Perfectus is recognized as one of the early martyrs of the Christian faith during the Roman Empire.', 'St. Perfectus was a devoted Christian who boldly proclaimed his faith in a time of intense persecution. He became a martyr for his beliefs, inspiring countless others to hold fast to their faith. His legacy endures as a symbol of courage and resilience in the face of adversity.', 'Faith is the light that guides us through the darkness.', 'April 15', NULL, 1, 1, 1, 10, 6, 3),

('Apollonius', 'apollonius', 'A Christian martyr known for his defense of the faith during the Roman persecutions.', 'St. Apollonius was a renowned Christian apologist in the 2nd century who bravely stood before the Roman authorities to proclaim the truth of the Gospel. He was ultimately sentenced to death for his unwavering faith and commitment to spreading Christianity. His story inspires many believers to stand firm in their convictions, even in the face of persecution.', 'The glory of God is man fully alive.', 'April 18', NULL, 3, 1, 8, 10, 5, 8),

('Albert of Montecorvino', 'albert-of-montecorvino', 'He was a Franciscan missionary known for spreading the Gospel in the East.', 'St. Albert of Montecorvino was a pioneering Franciscan missionary who devoted his life to evangelizing in the distant lands of Asia. He played a significant role in establishing the first Christian missions in China, where he translated religious texts into Chinese. His legacy of faith and perseverance continues to inspire missionaries worldwide.', 'Preach the Gospel at all times', 'April 19', NULL, 1, 10, 1, 3, 3, 1),

('Anselm of Canterbury', 'anselm-of-canterbury', 'He is recognized as a Doctor of the Church and a key figure in medieval theology.', 'St. Anselm of Canterbury was an Italian Benedictine monk, philosopher, and theologian who became the Archbishop of Canterbury. He is renowned for his arguments for the existence of God and for his work in reconciling faith and reason. His pioneering thoughts laid the groundwork for later theologians and philosophers, making significant impacts on Christian thought.', 'I do not seek to understand in order to believe, but I believe in order to understand.', 'April 20', NULL, 4, 4, 10, 4, 1, 6),

('Theodore of Sykeon', 'theodore-of-sykeon', 'He is known for his ascetic life and numerous miraculous healings.', 'St. Theodore of Sykeon was a Byzantine monk renowned for his piety and deep commitment to an ascetic lifestyle. He spent his life in seclusion, dedicating himself to prayer and spiritual healing, earning a reputation for performing miracles. His legacy continues to inspire those seeking holiness and devotion in the Christian faith.', 'Prayer is the mother of all virtues.', 'April 22', NULL, 1, 10, 1, 1, 1, 6),

('Fidelis of Sigmaringen', 'fidelis-of-sigmaringen', 'A martyr and passionate preacher who dedicated his life to defending the Catholic faith against Protestant heresies.', 'St. Fidelis of Sigmaringen was a Capuchin friar known for his fervent preaching and the defense of the Catholic faith. He was martyred in 1622 while preaching in Switzerland, becoming a symbol of unwavering faith and dedication. His legacy inspires many in the legal profession and beyond to uphold justice and truth.', 'The true servant of God is a great helper of the oppressed.', 'April 24', NULL, 2, 10, 1, 5, 1, 5),

('Zita', 'zita', 'She is known for her unwavering devotion and service to her family and the poor.', 'St. Zita was born in Tuscany, Italy, and dedicated her life to serving her family and those in need. She worked as a servant for the wealthy Fatinelli family, embodying kindness and humility in her daily tasks. Celebrated for her virtuous life, she became a beloved saint, and her example inspires many who work in domestic service.', 'A mother’s love would give her life to save her child.', 'April 27', NULL, 3, 10, 1, 1, 1, 4),

('Pius V', 'pius-v', 'Pope who excommunicated Queen Elizabeth I and established the Tridentine Mass.', 'St. Pius V was a reformist pope known for his commitment to the Council of Trent''s decrees, which sought to address issues within the Church. He is most renowned for promulgating the Roman Missal, which standardized the Mass throughout the Catholic Church. His papacy was marked by significant efforts to strengthen the Catholic faith in the face of the Reformation.', 'All the good works in the world will not save us without faith.', 'April 30', NULL, 3, 10, 3, 8, 1, 5),

('Florian', 'florian', 'St. Florian is known as the patron saint of firefighters and chimney sweeps.', 'St. Florian was a Roman officer who became a Christian martyr during the reign of Emperor Diocletian. He is celebrated for his steadfast faith and is often depicted emerging from flames. His legacy endures as a symbol of protection against fire and disaster.', 'For you, I am willing to endure all things.', 'May 4', NULL, 3, 5, 1, 10, 1, 10),

('Hilary of Arles', 'hilary-of-arles', 'Bishop of Arles and influential Church leader in the 5th century.', 'St. Hilary of Arles played a significant role in the early Church as a bishop who was known for his pastoral care and efforts to combat heresy. He was a pivotal figure in the Christianization of southern Gaul and worked tirelessly to promote unity and orthodoxy among believers. His leadership and dedication to the faith have made him a revered saint in the Catholic Church.', 'In all things, unity', 'May 5', NULL, 1, 10, 10, 10, 7, 3),

('Aidan of Lindisfarne', 'aidan-of-lindisfarne', 'He is known for his role in the conversion of the Northumbrians to Christianity.', 'St. Aidan was a monk from Iona who became the first bishop of Lindisfarne. He devoted his life to spreading Christianity in northern England and established the influential monastery on Lindisfarne. Aidan''s gentle approach to conversion and his care for the poor made him beloved by the people he served.', 'There is nothing more delightful than to be in love with God.', 'May 6', NULL, 1, 10, 4, 1, 1, 1),

('John of Beverley', 'john-of-beverley', 'Known for his role as a bishop and his contributions to the education and spiritual life of the early church in England.', 'St. John of Beverley was an influential bishop in the early 8th century who founded a monastery and played a significant role in the formation of the church in northern England. His commitment to education helped in the spiritual growth of the community, and he was also known for his piety and miracles. Today, he is remembered for his dedication to God and his service to the people of York.', 'The Kingdom of God is not for those who are idle, but for those who diligently seek it.', 'May 7', NULL, 2, 10, 1, 2, 4, 6),

('Michael de los Santos', 'michael-de-los-santos', 'He is known for his dedication to the missions in the American territories.', 'St. Michael de los Santos was a Spanish priest who became a Franciscan missionary in the Philippines. He was known for his tireless work in spreading the Christian faith among the indigenous people. His life was marked by a deep commitment to his faith and an unwavering spirit of service.', 'Preach the Gospel at all times', 'May 8', NULL, 1, 10, 1, 6, 3, 1),

('Pacian of Barcelona', 'pacian-of-barcelona', 'He was a bishop known for his theological writings and defense of Christian doctrine.', 'St. Pacian was a prominent bishop in the late 4th century, recognized for his strong stance against heresy and his efforts to win back lapsed Christians. He authored several letters and treatises that defended the importance of the sacraments and the need for moral purity among the faithful. His influence extended beyond his diocese, as he was consulted by other bishops on matters of doctrine and church governance.', 'We do not lose sight of heaven', 'May 9', NULL, 3, 10, 10, 7, 1, 10),

('Mamertus', 'mamertus', 'Being the Bishop of Vienne and advocating for festivals of penance and prayer.', 'St. Mamertus was the Bishop of Vienne who is best known for instituting the Rogation Days, which were intended to ask for God''s mercy in times of calamity. His dedication to prayer and penance reflects the early Church''s understanding of communal needs during crises. He played a crucial role in the religious life of his community during the tumultuous times of the 5th century.', 'Prayer is an all-powerful weapon.', 'May 11', NULL, 4, 10, 2, 8, 1, 4),

('Paschal Baylón', 'paschal-bayl-n', 'He is known for his deep devotion to the Eucharist and for his role as a Franciscan friar.', 'St. Paschal Baylón was a Spanish Franciscan who dedicated his life to serving the poor and promoting devotion to the Holy Eucharist. He is remembered for his piety and his efforts in the reform of the Franciscan order. His dedication and humility made him a beloved figure in the Church, inspiring many to a greater love for the sacrament.', 'The Eucharist is the greatest gift of God to us.', 'May 17', NULL, 3, 10, 1, 1, 1, 6),

('John I', 'john-i', 'Being a pope who stood for the rights of the Church against the Arian heresy.', 'St. John I was elected pope in 523 and is remembered for his defense of Catholic doctrine during a time of great theological turmoil. He was imprisoned by the Ostrogoth king Theodoric for opposing his Arian views, leading to his death due to harsh treatment. His legacy is one of steadfast faith and commitment to the truth of the Gospel.', 'For the sake of unity, we must often be willing to set aside our own preferences.', 'May 18', NULL, 3, 8, 8, 8, 1, 10),

('Yves', 'yves', 'St. Yves is known for his unwavering commitment to justice and the defense of the poor.', 'St. Yves, a Breton priest and lawyer, dedicated his life to serving the underprivileged and offering fair legal representation. His work emphasized the importance of compassion and integrity in legal matters. He is revered as a champion of justice and is often invoked for guidance in legal issues.', 'The law should be based on the truth.', 'May 19', NULL, 1, 10, 1, 1, 1, 3),

('John Baptist de Rossi', 'john-baptist-de-rossi', 'He is known for his dedication to the spiritual and material welfare of the poor and the sick.', 'St. John Baptist de Rossi was an Italian priest who dedicated his life to serving the poor and sick in the streets of Rome. He was particularly known for his deep compassion and tireless work in providing both spiritual guidance and material assistance to those in need. His legacy continues to inspire those who work in pastoral care and social justice.', 'Compassion is the link between the Church and her public.', 'May 23', NULL, 1, 10, 1, 1, 1, 1),

('David I of Scotland', 'david-i-of-scotland', 'Known for founding several monastic communities and his efforts in evangelizing Scotland.', 'St. David I was a pivotal figure in the history of Scotland, known for his dedication to the Christian faith and his influence in the establishment of the church. He played a key role in promoting ecclesiastical reforms and aided in the development of monastic life throughout the region. His legacy continues to inspire many, and he is celebrated for his contributions to the spiritual and cultural growth of Scotland.', 'Your faith is your anchor in the storms of life.', 'May 24', NULL, 1, 10, 6, 6, 4, 1),

('William of York', 'william-of-york', 'He is known for his dedication to the Church and his conflict with the powers of his time regarding his rightful position.', 'St. William of York was a Benedictine monk and later became the Archbishop of York. His life was marked by a struggle to reclaim his see against political intrigue and opposition. After his death, he was regarded as a martyr for his unwavering commitment to his faith and his flock.', 'In all things, I have followed the truth with a sincere heart.', 'May 28', NULL, 7, 10, 7, 7, 1, 10),

('Josemaria Escriva', 'josemaria-escriva', 'Founder of Opus Dei, a personal prelature of the Catholic Church devoted to the sanctification of everyday life.', 'St. Josemaria Escriva was a Spanish priest who dedicated his life to encouraging people to find God in their daily activities. He founded Opus Dei in 1928, emphasizing the importance of holiness in ordinary life. His teachings inspire millions to integrate their faith into their work and family lives.', 'Work, then, is a channel of grace.', 'May 31', NULL, 3, 5, 1, 5, 8, 10),

('Blandina', 'blandina', 'Blandina is known as a martyr who stood steadfast in her faith, enduring horrific torture without renouncing Christ.', 'St. Blandina was a young Christian woman who lived in the 2nd century and is remembered for her unwavering faith. During a period of intense persecution in Lyons, she faced brutal torture alongside fellow Christians but remained resolute in her beliefs. Her courage inspired many and solidified her status as a symbol of faith and perseverance.', 'I am a Christian, and I cannot sacrifice to the gods.', 'June 2', NULL, 1, 4, 1, 10, 1, 3),

('Francis Caracciolo', 'francis-caracciolo', 'Founder of the Congregation of the Servants of the Blessed Sacrament.', 'St. Francis Caracciolo dedicated his life to serving God through the Eucharist and showed a profound love for the Blessed Sacrament. He founded a religious order focused on the love and adoration of the Eucharist, emphasizing the importance of this sacrament in daily life. His deep spirituality and commitment to service inspired many to follow his example of faith and devotion.', 'Let us be one among ourselves, but first let us be one with Christ.', 'June 4', NULL, 3, 10, 1, 3, 3, 3),

('Robert of Newminster', 'robert-of-newminster', 'He is known for his role in the founding of the Cistercian order in the 12th century.', 'St. Robert of Newminster was an English Cistercian monk and the abbot of the monastery at Newminster. He became a significant figure in the monastic reform of his time, helping to establish communities that emphasized simplicity and prayer. His dedication to the Cistercian way of life inspired many others to follow his spiritual path.', 'The good man owes it to himself to be better than he is.', 'June 7', NULL, 1, 10, 1, 1, 1, 4),

('Landry', 'landry', 'He is known for his leadership and dedication to the spiritual well-being of his community.', 'St. Landry was a devoted bishop of Paris, who showed exceptional care for the poor and sick during his tenure. He is remembered for his charitable works and his commitment to fostering a strong Christian community. His legacy continues to inspire those who work toward the service of others.', 'Faith is the foundation of all virtues.', 'June 10', NULL, 2, 10, 5, 1, 1, 5),

('Methodius', 'methodius', 'Co-patron of the Slavic people, known for his missionary work alongside his brother Cyril.', 'St. Methodius was a 9th-century missionary known for bringing Christianity to the Slavic nations, particularly Great Moravia. Alongside his brother Cyril, he developed the Glagolitic alphabet, the first script used for writing Old Church Slavonic. Their work laid the foundation for Slavic culture and literacy.', 'Let us, therefore, accept the teachings of Holy Scripture.', 'June 14', NULL, 2, 6, 6, 10, 1, 4),

('Germaine Cousin', 'germaine-cousin', 'Known for her deep faith and miracles attributed to her intercession.', 'St. Germaine Cousin was born in a small village in France, where she faced great hardship from a young age due to her physical disabilities and neglect from her family. Despite her suffering, she led a life of piety and charity, often caring for the sick and the poor in her community. Her profound compassion and unwavering faith led to her being canonized as a saint, with many claiming miracles after invoking her name.', 'I would rather die than offend my God.', 'June 15', NULL, 2, 10, 1, 4, 1, 6),

('John Francis Regis', 'john-francis-regis', 'He is known for his dedication to the spiritual and physical welfare of the poor.', 'St. John Francis Regis was a French priest of the Society of Jesus who spent his life in service to the marginalized. His zealous preaching and tireless pastoral work significantly impacted the region around Toulouse in France, particularly focusing on the conversion of the indifferently Catholic and the protestors of the Jansenist heresy. His life was characterized by deep compassion and commitment to those in need, earning him a revered place among the saints.', 'We must strive to be like Jesus, who emptied himself for the good of others.', 'June 16', NULL, 1, 10, 1, 4, 6, 1),

('Albert Chmielowski', 'albert-chmielowski', 'Founder of the Albertine Brothers and Sisters, dedicated to serving the poor.', 'St. Albert Chmielowski, originally an artist, experienced a profound transformation that led him to abandon his career and dedicate his life to serving the marginalized. He founded the Albertine religious congregation, which focused on caring for the poor and homeless in Poland. His life exemplifies the call to charity and compassion, highlighting the importance of serving others in need.', 'Love is the most important thing in life.', 'June 17', NULL, 1, 10, 1, 1, 2, 1),

('Gregory Barbarigo', 'gregory-barbarigo', 'He is known for his contributions to the Catholic Church in the 17th century as a bishop and a diplomat.', 'St. Gregory Barbarigo was an influential bishop in the 17th century, dedicated to reforming the clergy and enhancing the quality of pastoral care. He played a crucial role in the Counter-Reformation efforts in Venice, establishing seminaries and promoting a deeper understanding of the faith. His commitment to education and the spiritual well-being of his flock earned him a place as a revered figure in Church history.', 'He who follows Christ, walks not in darkness.', 'June 18', NULL, 1, 10, 4, 1, 1, 4),

('Alban', 'alban', 'St. Alban is recognized as the first British martyr.', 'St. Alban was a pagan soldier who converted to Christianity after sheltering a priest named Amphibalus. He witnessed the priest''s bravery and chose to take his place when soldiers came to arrest him. Captured and executed for his faith, Alban''s legacy inspires countless Christians around the world.', 'In the end, we will remember not the words of our enemies, but the silence of our friends.', 'June 20', NULL, 1, 10, 1, 7, 3, 3),

('Joseph Cafasso', 'joseph-cafasso', 'Known for his work as a priest and confessor, and for his deep commitment to spiritual guidance and care for the poor.', 'St. Joseph Cafasso was a dedicated priest from Italy who served as a mentor to St. John Bosco. He was renowned for his spiritual direction and his tireless efforts to aid those in need, particularly prisoners. His life was a testament to compassion, mercy, and the transformative power of faith.', 'It is in the spirit of practice and habits that we become what we will be.', 'June 23', NULL, 1, 10, 4, 3, 3, 1),

('William', 'william', 'He is known for his extensive work in reforming monastic life and promoting the Benedictine Rule.', 'St. William was a committed Benedictine monk and later became the Bishop of Eboracum, known today as York. He devoted his life to the care of his flock, emphasizing the need for pastoral charity and the importance of monastic reform. His canonization highlighted his role as a shining example of holiness and compassion in the Middle Ages.', 'For where there is charity and wisdom, there is neither fear nor ignorance.', 'June 25', NULL, 1, 10, 3, 1, 1, 1),

('Cyril of Alexandria', 'cyril-of-alexandria', 'Cyril was a prominent theologian and philosopher known for his role in the Nestorian controversy and the Council of Ephesus.', 'St. Cyril of Alexandria served as the Patriarch of Alexandria and was a staunch defender of the orthodox faith against heresies. His teachings significantly shaped Christological doctrine, particularly the nature of Christ as both divine and human. An influential figure in early Christianity, Cyril''s commitment to the truth and his eloquent writings continue to resonate with the faithful.', 'What is not assumed is not healed.', 'June 27', NULL, 1, 10, 1, 7, 1, 10),

('Odilo of Cluny', 'odilo-of-cluny', 'He is renowned for his role in the development of the monastic reform movement and the expansion of the Cluniac order.', 'St. Odilo of Cluny was a Benedictine monk who became the second abbot of Cluny Abbey. Under his leadership, the monastery flourished, and its influence expanded across Europe, promoting a return to strict monastic discipline and spirituality. He is also remembered for instituting the observance of All Souls'' Day, emphasizing the importance of praying for the deceased.', 'We must strive to please others, but most importantly, we must please our God.', 'July 2', NULL, 3, 10, 1, 3, 3, 3),

('Anthony Mary Zaccaria', 'anthony-mary-zaccaria', 'Founder of the Barnabite Fathers and a champion of the Tridentine reforms.', 'St. Anthony Mary Zaccaria was a priest who dedicated his life to revitalizing the faith among the clergy and laity. He founded the Clerics Regular of St. Paul, a religious order aimed at educating the youth and promoting a deeper spiritual life. His commitment to the Church and the formation of spiritual leaders left a lasting legacy in the Catholic community.', 'The love of Jesus is the greatest treasure.', 'July 5', NULL, 3, 1, 1, 5, 10, 10),

('Rufinus', 'rufinus', 'Rufinus is venerated as a martyr and saint who died for his faith during the early Christian persecutions.', 'St. Rufinus was a devoted Christian who faced persecution for his beliefs in the early 4th century. He exemplified courage in the face of adversity and ultimately gave his life for his faith. His legacy continues to inspire Christians to stand firm in their convictions.', 'Faith is to believe what you do not see', 'July 10', NULL, 3, 8, 1, 10, 5, 8),

('Alexis', 'alexis', 'Legendary figure known for his piety and devotion to God, renouncing a life of comfort for prayer and charity.', 'St. Alexis, originally from a wealthy family, chose a life of poverty and anonymity after his marriage. He lived as a beggar, dedicating his life to serving the poor and living out the teachings of Christ. His extraordinary humility and commitment to the needy have made him a beloved saint in the Catholic Church.', 'The one who wants to be first must become the servant of all.', 'July 17', NULL, 3, 10, 1, 3, 1, 3),

('Arsenius', 'arsenius', 'Being an influential monk and spiritual teacher in the early Christian church.', 'St. Arsenius was a hermit who profoundly influenced many through his life of prayer and asceticism. After serving as a tutor to the sons of Emperor Theodosius, he sought a life of solitude in the Egyptian desert. His wisdom and teachings on detachment and humility have inspired countless followers seeking a deeper spiritual life.', 'I have often said, ''I have but one desire, I would not lose my right mind in this world for all the empires of the earth.''', 'July 19', NULL, 6, 4, 10, 1, 1, 6),

('Apollinaris', 'apollinaris', 'Early bishop and martyr who played a key role in the spread of Christianity in Italy.', 'St. Apollinaris was one of the early bishops of Ravenna who faced persecution for his steadfast faith. He is believed to have been martyred for his efforts to evangelize the region, and his legacy continues to influence the Church today. His dedication to Christ and unwavering spirit inspires many to remain steadfast in their faith despite challenges.', 'Let us not be ashamed of the Cross of Christ.', 'July 20', NULL, 2, 5, 1, 10, 3, 3),

('Lawrence of Brindisi', 'lawrence-of-brindisi', 'A Capuchin Franciscan and an influential preacher known for his eloquent sermons and theological writings.', 'St. Lawrence of Brindisi was a remarkable theologian and preacher in the early 17th century, renowned for his ability to communicate the faith with clarity and passion. He played a key role in the Counter-Reformation by traveling extensively to rekindle faith in communities threatened by Protestantism. His deep devotion and commitment to Christ inspired many to follow his example in both religious and everyday life.', 'A great measure of faith is to abandon oneself to God and trust Him.', 'July 21', NULL, 2, 10, 1, 1, 1, 8),

('Pantaleon', 'pantaleon', 'St. Pantaleon is known as a physician and martyr who devoted his life to healing and serving others.', 'St. Pantaleon, a physician in the fourth century, became renowned for his miraculous healings through faith. After converting to Christianity, he refused to renounce his faith even under persecution, leading to his martyrdom. His legacy of compassion and dedication to the sick continues to inspire medical professionals today.', 'The physician should be aware that the greatest skill of healing is prayer.', 'July 27', NULL, 1, 10, 1, 8, 1, 4),

('Lydia', 'lydia', 'The first recorded convert to Christianity in Europe.', 'St. Lydia was a wealthy seller of purple cloth from Thyatira who became the first European convert to Christianity after hearing St. Paul preach. She opened her home to Paul and his companions and was instrumental in establishing the early Church in Philippi. Her generous spirit and faithfulness made her a key figure in the spread of the Gospel in the Roman Empire.', 'Faith is the light that illuminates the dark places of our lives.', 'August 3', NULL, 1, 8, 1, 8, 1, 10),

('Sixtus II', 'sixtus-ii', 'Pope and martyr known for his leadership during the early Church''s struggles.', 'St. Sixtus II served as pope during a tumultuous time when Christians faced severe persecution under the Roman Empire. He was known for his courageous defense of the faith and his role in promoting the martyrdom of clergy and laity alike. Ultimately, he was martyred while celebrating the Eucharist, exemplifying his commitment to Christ and the Church.', 'The blood of martyrs is the seed of the Church.', 'August 6', NULL, 1, 8, 2, 10, 1, 3),

('Hyacinth', 'hyacinth', 'A renowned Dominican friar known for his missionary work in Eastern Europe.', 'St. Hyacinth was a Polish Dominican who played a pivotal role in spreading Christianity across Eastern Europe. He is celebrated for his unwavering dedication to preaching and converting souls, often at great personal risk. His efforts led to the establishment of numerous Dominican communities in the region, making him a significant figure in the history of the Church.', 'Preach the Gospel at all times and when necessary use words.', 'August 17', NULL, 4, 8, 1, 10, 4, 4),

('Helena', 'helena', 'Mother of Emperor Constantine and influential in the establishment of Christianity in the Roman Empire.', 'St. Helena, the mother of Emperor Constantine, is venerated for her significant role in the early Christian Church. She is best known for her pilgrimage to the Holy Land, where she discovered the True Cross. Honored as a saint by the Catholic Church, her legacy continues to inspire countless believers.', 'The heart that is grateful is always in the right mood.', 'August 18', NULL, 2, 6, 6, 10, 1, 4),

('Aidan', 'aidan', 'Founder of the monastery on Lindisfarne and a key figure in the conversion of the Northumbrians to Christianity.', 'St. Aidan was originally from Ireland and became a monk on the Isle of Iona before being sent to Northumbria as a missionary. Known for his gentle demeanor and spiritual leadership, he played a pivotal role in spreading Christianity in the region. His work laid the foundation for a lasting ecclesiastical structure in England and he is revered for his commitment to both the faith and the well-being of his flock.', 'The measure of love is to love without measure.', 'August 31', NULL, 1, 10, 4, 1, 1, 1),

('Brocard', 'brocard', 'He was the first prior of the Carthusian order in England.', 'St. Brocard was a significant figure in early British monasticism, well-known for his devotion and leadership within the Carthusian community. He played a critical role in establishing the Carthusian order in England, promoting a lifestyle of solitude and prayer. His life exemplifies dedication to God through silence and contemplation, inspiring many to pursue a similar calling.', 'The soul should be like a beautiful garden, where contemplation is cultivated.', 'September 2', NULL, 10, 7, 1, 2, 1, 5),

('Eleutherius', 'eleutherius', 'He is recognized as a martyr and an early Pope of the Roman Catholic Church.', 'St. Eleutherius served as Pope during a time of persecution for Christians. He is remembered for his steadfast faith and leadership during adversity, ultimately leading to his martyrdom. His dedication inspired generations of believers seeking hope and resilience.', 'The blood of martyrs is the seed of the Church.', 'September 6', NULL, 1, 5, 1, 10, 3, 3),

('Wasnildus', 'wasnildus', 'St. Wasnildus is recognized for his pious life and dedication to monasticism.', 'St. Wasnildus was a revered monk who devoted his life to prayer and contemplation in a secluded monastery. His deep spirituality and commitment to asceticism inspired many of his contemporaries. Known for his wisdom, he guided numerous souls on their spiritual journeys throughout his life.', 'Contemplation is a treasure that lies within the heart.', 'September 7', NULL, 1, 10, 4, 1, 1, 1),

('Peter Claver', 'peter-claver', 'He is known for his dedicated work in serving African slaves in Colombia.', 'St. Peter Claver was a Spanish Jesuit priest who dedicated his life to the service of the enslaved people brought to the Americas. He is remembered for his compassion, providing care, and spreading the Christian faith among the African slaves. Claver baptized more than 300,000 slaves throughout his life, earning him the title ''Apostle of the Negroes.''', 'It is not enough to love the negro', 'September 9', NULL, 1, 10, 1, 4, 1, 1),

('Nicholas of Toledo', 'nicholas-of-toledo', 'Nicholas of Toledo is celebrated for his contributions to the church and his moral integrity.', 'St. Nicholas of Toledo was a noted 12th-century Spanish priest known for his dedication to pastoral care. Throughout his life, he demonstrated remarkable compassion towards the sick and the needy, earning the respect and love of his community. He is remembered as a man of great faith and wisdom, whose teachings continue to inspire many in the Catholic tradition.', 'Faith is like a grain of mustard seed', 'September 10', NULL, 1, 10, 3, 1, 1, 1),

('Adrian of Nicomedia', 'adrian-of-nicomedia', 'Martyrdom during the persecution of Christians under Emperor Diocletian.', 'St. Adrian of Nicomedia was a Christian martyr who lived during the early 4th century. He boldly refused to renounce his faith, even when faced with brutal torture and death. His steadfastness in the face of adversity has inspired countless believers throughout the ages.', 'The greater the struggle, the greater the reward.', 'September 11', NULL, 2, 1, 1, 10, 1, 8),

('Thecla', 'thecla', 'St. Thecla is known for her remarkable dedication to the Christian faith and her role as one of the earliest female martyrs.', 'St. Thecla was a young woman from Iconium who, inspired by the teachings of St. Paul, embraced a life of celibacy and devotion to God. She faced persecution for her faith, enduring trials that ultimately led to her martyrdom. Her story has inspired generations, symbolizing the strength and resilience of women in the early church.', 'For I will not marry, but I will follow my hope, which has been spoken of unto me.', 'September 12', NULL, 2, 5, 1, 10, 3, 3),

('Catherine of Genoa', 'catherine-of-genoa', 'She is known for her mystical writings and profound spirituality.', 'St. Catherine of Genoa was a devoted mystic and servant of the sick, who dedicated her life to the care of the poor and the suffering. Her mystical experiences led her to a deeper understanding of God''s love and mercy, which she expressed in her writings. She founded a hospital in Genoa, which became a model for future institutions of care.', 'Love transforms one into what one loves.', 'September 15', NULL, 8, 10, 1, 4, 1, 4),

('Joseph of Cupertino', 'joseph-of-cupertino', 'Known for his remarkable levitations during prayer.', 'St. Joseph of Cupertino was a humble Franciscan friar who became known for his ecstatic visions and miracles. Despite facing significant challenges in his education, he was deeply devoted to prayer and the contemplative life. His extraordinary ability to levitate led many to see him as a saintly figure during his lifetime, and he remains an inspiration to those who face difficulties in their spiritual journey.', 'I have only one desire, and that is to love God.', 'September 18', NULL, 3, 3, 1, 1, 1, 10),

('Januarius', 'januarius', 'Famed for the miraculous liquefaction of his blood.', 'St. Januarius was a bishop and martyr who died during the persecution of Christians under Emperor Diocletian. He is best known for the miraculous phenomenon of his blood, which is said to liquefy annually in his shrine in Naples. His veneration has been a source of inspiration for many, as he represents steadfast faith amid adversity.', 'The blood of martyrs is the seed of Christians.', 'September 19', NULL, 2, 5, 1, 10, 3, 3),

('Maurice', 'maurice', 'Maurice is known as a leader of the Theban Legion and a martyr under the Roman Empire.', 'St. Maurice was an early Christian martyr and the commander of the Theban Legion in the Roman army. Refusing to participate in pagan sacrifices, he and his fellow soldiers faced execution for their faith. Maurice''s steadfastness and leadership in the face of persecution made him a beloved figure and a symbol of military obedience to Christ.', 'The enemy does not attack when he knows the victor to be ever watchful.', 'September 22', NULL, 2, 1, 1, 10, 1, 8),

('Cosmas', 'cosmas', 'St. Cosmas is known as a patron saint of physicians and surgeons.', 'St. Cosmas, along with his brother Damian, was a physician known for performing surgeries without charge, demonstrating their commitment to serving the sick and needy. They were martyred for their faith during the reign of Emperor Diocletian and are revered for their dedication to the practice of medicine as a ministry. Their legacy continues to inspire countless medical professionals who see their work as a vocation of service.', 'Medicine is a divine gift bestowed upon us.', 'September 26', NULL, 1, 10, 1, 1, 1, 4),

('Our Lady of the Rosary', 'our-lady-of-the-rosary', 'The celebration honors the Blessed Virgin Mary under her title of Our Lady of the Rosary.', 'Our Lady of the Rosary dates back to the 13th century, reflecting the importance of the rosary in Catholic devotion. She is seen as a powerful intercessor and has inspired countless faithful to seek her guidance through prayer. The feast emphasizes the role of Mary in the church and the spiritual strength of the rosary.', 'The rosary is a powerful weapon to put the demons to flight and to keep oneself free from sin.', 'October 7', NULL, 6, 10, 1, 1, 2, 6),

('Pelagia', 'pelagia', 'Known for her conversion from a life of sin to a life dedicated to God.', 'St. Pelagia was originally a beautiful actress who lived a life of luxury and indulgence in Antioch. After hearing a sermon on repentance, she chose to abandon her former life and dedicated herself to prayer and penance. Her remarkable transformation inspires many to seek forgiveness and live a holy life.', 'The time is now to take up the cross and follow Him.', 'October 8', NULL, 3, 8, 1, 10, 5, 8),

('Denis', 'denis', 'The patron saint of France and a martyr who was one of the first bishops of Paris.', 'St. Denis was a third-century Christian martyr, known for his missionary work in Gaul. According to legend, he was decapitated for his faith but picked up his head and walked several miles, preaching the Gospel. He became the bishop of Paris and is celebrated for his unwavering dedication to spreading Christianity in France.', 'What we do in life echoes in eternity.', 'October 9', NULL, 2, 5, 1, 10, 3, 3),

('Paul of the Cross', 'paul-of-the-cross', 'Founder of the Passionists, a religious order dedicated to the Passion of Christ.', 'St. Paul of the Cross was born in Italy and spent much of his life preaching and spreading devotion to the Passion of Jesus. He founded the Congregation of the Passion (the Passionists) to foster a deeper understanding of Christ''s suffering. His profound spirituality and emphasis on contemplative prayer have inspired countless followers to deepen their faith.', 'May the Passion of Christ be always in our hearts.', 'October 10', NULL, 10, 8, 1, 8, 5, 5),

('Edward the Confessor', 'edward-the-confessor', 'Last of the Anglo-Saxon kings of England, known for his piety and dedication to God.', 'St. Edward the Confessor was a beloved king who governed with compassion and justice, fostering peace and stability in England during his reign. He was known for his deep spirituality and commitment to helping the less fortunate, earning him a reputation as a kind and holy ruler. After his death, his sanctity was recognized and he was canonized, becoming one of the most revered saints in England.', 'I am a king but I am a servant of Christ.', 'October 13', NULL, 4, 10, 1, 1, 1, 8),

('Callistus I', 'callistus-i', 'St. Callistus I was known for his role as pope and his reforms in the early Church.', 'St. Callistus I was a pope who advocated for the inclusion of sinners into the Church, emphasizing God''s mercy. He established a cemetery for Christians in Rome, which became a revered burial site. His leadership provided a model of compassion and forgiveness during a time of persecution.', 'Let us be careful, lest we think ourselves well of our own works.', 'October 14', NULL, 1, 10, 1, 4, 1, 4),

('Ignatius of Antioch', 'ignatius-of-antioch', 'Early Christian martyr and bishop known for his letters encouraging unity and faith.', 'St. Ignatius of Antioch was a bishop and one of the earliest Apostolic Fathers of the Church. He was arrested and brought to Rome, where he faced martyrdom for his faith around the year 107 AD. His impactful letters emphasize the importance of the Eucharist and the authority of bishops in the early Christian community.', 'Where there is Christ Jesus, there is the Catholic Church.', 'October 17', NULL, 2, 1, 1, 7, 3, 10),

('John Cantius', 'john-cantius', 'He is known for his deep spirituality, commitment to education, and dedication to helping the poor.', 'St. John Cantius was a Polish priest and professor who dedicated his life to teaching and spiritual guidance. Renowned for his piety and devotion, he significantly contributed to the academic landscape of his time and was beloved by both students and the community he served. His legacy continues to inspire educators and students alike, emphasizing the importance of faith and knowledge.', 'Teach us to give and not to count the cost.', 'October 20', NULL, 1, 10, 1, 1, 1, 3),

('Crispin', 'crispin', 'Patron saint of cobblers and shoemakers.', 'St. Crispin, along with his brother Crispinian, was a Christian martyr who dedicated his life to preaching and helping the poor. They famously worked as cobblers during the day while spreading the Gospel at night. Their unwavering faith led to their martyrdom under Emperor Maximian in the late 3rd century.', 'Let us, in our own humble way, preach the Gospel, even while we work.', 'October 25', NULL, 4, 10, 1, 6, 1, 6),

('Evaristus', 'evaristus', 'He is known as the fifth Pope and a successor of St. Peter.', 'St. Evaristus served as Pope during the early years of the Christian church, promoting the faith in a time of persecution. Known for his leadership and commitment to the teachings of Christ, he played a pivotal role in organizing the church''s structure. His papacy is marked by the strengthening of the Christian community and the affirmation of its doctrines.', 'A shepherd does not run at the sight of a wolf.', 'October 26', NULL, 1, 10, 4, 6, 1, 1),

('Alphonsus Maria de Liguori', 'alphonsus-maria-de-liguori', 'Founding the Congregation of the Most Holy Redeemer (Redemptorists).', 'St. Alphonsus Maria de Liguori was a prominent Italian bishop and theologian known for his deep devotion to the Blessed Virgin Mary and his emphasis on moral theology. His commitment to pastoral care and his writings have made a profound impact on the Church, particularly in the area of conscience. He founded the Redemptorist congregation to promote spiritual renewal and assist the poor in rural areas.', 'Prayer is necessary for salvation.', 'October 30', NULL, 3, 10, 10, 3, 7, 10),

('Wolfgang', 'wolfgang', 'He is known for his role in the Christianization of the region of Bavaria and for founding several monasteries.', 'St. Wolfgang was a Benedictine monk and the Bishop of Regensburg known for his missionary work in Bavaria. He dedicated his life to spreading Christianity and educating the people in his diocese. His legacy includes various churches and abbeys established in his honor throughout the region.', 'The Lord has given me a true friendship.', 'October 31', NULL, 1, 10, 4, 3, 3, 1),

('All Saints', 'all-saints', 'Honoring all saints, known and unknown, who have attained heaven.', 'St. All Saints represents the collective holiness of all those who have responded to God''s call. Celebrated on November 1, this feast day invites the faithful to recognize the saints'' examples and intercessions in their lives. It serves as a reminder of the hope of eternal life with God, encouraging believers to strive for holiness.', 'The saints are the people who provide us a glimpse into heaven.', 'November 1', NULL, 4, 10, 1, 6, 4, 4),

('All Souls', 'all-souls', 'Honoring the souls of the faithful departed.', 'St. All Souls is commemorated on November 2, recognized within the Church for interceding on behalf of those who have died. The day serves as a time to pray for the souls in purgatory, reflecting on the belief in communion with the dead. Through prayers and remembrances, the faithful seek to help these souls attain eternal rest in Heaven.', 'Eternal rest grant unto them, O Lord, and let perpetual light shine upon them.', 'November 2', NULL, 7, 10, 1, 1, 1, 10),

('Leonard of Noblac', 'leonard-of-noblac', 'St. Leonard is known for his dedication to the monastic life and for his work in freeing captives.', 'St. Leonard of Noblac was a hermit and one of the most popular saints in medieval Europe, known for his pious life and dedication to God. He is particularly celebrated for his compassion towards prisoners and is often invoked for their protection. His numerous miracles and acts of kindness inspired many, leading to his veneration across the Christian world.', 'Pray with confidence, and you will be heard.', 'November 6', NULL, 1, 10, 3, 1, 1, 1),

('Willibrord', 'willibrord', 'Known as the apostle of the Frisians, he was instrumental in spreading Christianity in the region of what is now the Netherlands.', 'St. Willibrord was a Benedictine monk from England who became a missionary in the continental Europe during the early Middle Ages. He founded several churches and established the diocese of Utrecht, becoming its first bishop. His dedicated work in evangelizing the Frisians earned him the title of a revered saint in both local and broader Christian contexts.', 'The glory of God is the human person fully alive.', 'November 7', NULL, 3, 10, 1, 10, 7, 10),

('Benignus', 'benignus', 'He is known for his missionary work and dedication to spreading Christianity in Ireland.', 'St. Benignus was a devoted companion of St. Patrick and played a significant role in the establishment of the Christian faith in Ireland. He is often remembered for his zeal in spreading the Gospel and his commitment to the teachings of Christ. His life serves as an inspiration for those dedicated to missionary work and evangelization.', 'The path to holiness is paved with humility and patience.', 'November 9', NULL, 2, 10, 1, 6, 8, 4),

('Lawrence O''Toole', 'lawrence-otoole', 'He is known for his dedication to reforming the Church and his efforts to promote peace in Ireland during a turbulent period.', 'St. Lawrence O''Toole was the Archbishop of Dublin and a prominent figure in the Irish Church during the 12th century. He worked tirelessly to build bridges between the English and the Irish, promoting harmony while advocating for the rights of his people. His legacy is celebrated through his commitment to both faith and peace, making him a beloved figure in Irish history.', 'Our Lord, instruct me', 'November 14', NULL, 6, 10, 6, 4, 1, 1),

('Agnes of Assisi', 'agnes-of-assisi', 'Founding the Poor Clares and following in the footsteps of her sister, St. Clare.', 'St. Agnes of Assisi was a devoted follower of St. Clare and dedicated her life to the Franciscan way of living. She founded the Poor Clares in Italy, emphasizing a life of poverty and humility. Her commitment to Christ and the values of the Gospel inspired many to embrace the religious life and pursue a closer relationship with God.', 'In our actions, let it be known that we are servants of the Lord.', 'November 19', NULL, 4, 10, 1, 1, 1, 8),

('Andrew Dung-Lac', 'andrew-dung-lac', 'A Vietnamese martyr who courageously defended his faith during a time of persecution.', 'St. Andrew Dung-Lac was a Vietnamese priest who played a crucial role in the evangelization of Vietnam during the hostile period of the 19th century. He was martyred for his faith along with many companions who suffered greatly for their commitment to Christianity. His steadfastness inspires countless Catholics, reminding them of the power of faith amidst adversity.', 'The strongest weapon is the one that comes from the heart.', 'November 24', NULL, 1, 5, 1, 10, 3, 3),

('John Berchmans', 'john-berchmans', 'Known for his deep spirituality and commitment to Jesuit ideals.', 'St. John Berchmans was a Belgian Jesuit who dedicated his short life to the service of God and his fellow man. He is remembered for his piety and dedication to learning, earning him the esteem of many during his lifetime. His example continues to inspire young people, especially students and altar servers, to live with integrity and devotion.', 'The greatest happiness is to be in the presence of God.', 'November 26', NULL, 10, 5, 8, 3, 1, 8),

('Saturninus', 'saturninus', 'He is known for being one of the early bishops of Toulouse and a martyr for the faith.', 'St. Saturninus was a prominent early Christian leader in Toulouse, known for his unwavering faith during a time of great persecution. According to tradition, he was martyred for refusing to renounce Christianity, highlighting his dedication to God. His legacy has continued to inspire many believers throughout the centuries.', 'The power of Christ compels me to speak the truth.', 'November 29', NULL, 2, 6, 1, 8, 4, 10),

('Bibiana', 'bibiana', 'She is known for her fortitude and martyrdom during the persecution of Christians in Rome.', 'St. Bibiana was a young Roman noblewoman who remained steadfast in her faith despite brutal persecution. After her family''s martyrdom, she was arrested for refusing to renounce Christianity and was subjected to various tortures. Ultimately, Bibiana''s dedication to her faith led to her martyrdom, and she became a symbol of resilience and hope for believers.', 'The soul of our faith is love.', 'December 2', NULL, 3, 8, 1, 10, 5, 8),

('Nicholas of Myra', 'nicholas-of-myra', 'He is renowned for his acts of charity and generosity towards the poor and for performing miracles.', 'St. Nicholas of Myra was a 4th-century bishop known for his secret gift-giving, which laid the groundwork for the modern Santa Claus tradition. His life was marked by compassion, especially towards children and the less fortunate. He became famous for several miracles attributed to him, including saving sailors and providing dowries for poor girls.', 'It is better to give than to receive.', 'December 5', NULL, 1, 10, 4, 1, 1, 1),

('Eulalia', 'eulalia', 'A martyr known for her bravery and commitment to her faith during persecution in early Christianity.', 'St. Eulalia is revered for her steadfastness during the Diocletian persecution. At a young age, she boldly confronted the Roman authorities in defense of her Christian beliefs. Her unwavering spirit ultimately led to her martyrdom, inspiring many to uphold their faith against adversity.', 'The soul cannot be captivated when it stands by the truth.', 'December 10', NULL, 1, 1, 1, 10, 1, 4),

('Damasus I', 'damasus-i', 'Known for his efforts to promote the primacy of the Roman See.', 'St. Damasus I served as Pope from 366 to 384 and was instrumental in defining the role of the papacy in the early Church. He advocated for the support of Christian literature and was dedicated to the preservation of the writings of early Church Fathers. His influence contributed significantly to the establishment of the Church''s authority and unity during a tumultuous time.', 'It is not without reason that I call you, to bear witness with me, certain of the most blessed martyrs.', 'December 11', NULL, 3, 1, 10, 8, 3, 8),

('Our Lady of Guadalupe', 'our-lady-of-guadalupe', 'A prominent figure in Catholicism, she is known for her miraculous appearance to St. Juan Diego in Mexico.', 'Our Lady of Guadalupe is a significant figure in Catholic faith, celebrated for her apparitions to the indigenous Juan Diego in 1531. Her image, which appeared on his cloak, became a symbol of faith and unity for the Mexican people and beyond. She is revered as the Mother of the Americas, promoting love, compassion, and respect for life.', 'I am your mother, and I desire that you go and tell all that I will do for them.', 'December 12', NULL, 1, 10, 1, 1, 1, 3),

('Cuan', 'cuan', 'Known for his piety and dedication to the Christian faith in early Ireland.', 'St. Cuan, a revered figure in early Irish Christianity, was noted for his incredible faith and commitment to God. He is often associated with the spread of Christianity in Ireland, inspiring many through his teachings and holy life. His legacy continues to influence the spiritual landscape of Ireland today.', 'Faith is a shield against life''s storms.', 'December 15', NULL, 3, 10, 10, 3, 7, 10),

('Adelaide', 'adelaide', 'Queen of the Germans and protector of the Church.', 'St. Adelaide was a noblewoman who enriched the Church and promoted peace during turbulent times in medieval Europe. As the wife of Emperor Otto I, she played a crucial role in politics and was a strong supporter of Christian missions. Her legacy includes her dedication to the poor and her efforts in promoting the faith throughout her realm.', 'The spirit of the Lord will rest upon him.', 'December 16', NULL, 1, 4, 4, 10, 1, 1),

('Lazarus', 'lazarus', 'St. Lazarus is best known for being raised from the dead by Jesus Christ.', 'St. Lazarus, a close friend of Jesus, is famously remembered for his miraculous resurrection from the dead after four days. His story, found in the Gospel of John, illustrates the power of faith and the promise of eternal life. After his resurrection, he became a prominent figure in the early Christian community, symbolizing hope and renewal.', 'Lord, if you had been here, my brother would not have died.', 'December 17', NULL, 2, 10, 1, 1, 1, 8),

('Flannan', 'flannan', 'Bishop of Killaloe and known for his piety and dedication to the Christian faith.', 'St. Flannan was a revered bishop in Ireland who played a significant role in the spread of Christianity in the region. He is remembered for his deep spirituality and commitment to his flock, leading many to follow the Christian path. His influence extended beyond his lifetime, shaping the religious landscape of Ireland.', 'The greatest wealth is to live content with little.', 'December 18', NULL, 4, 10, 1, 2, 4, 6),

('Nemesius', 'nemesius', 'He is known for his contributions to early Christian theology and his defense of the faith against heresies.', 'St. Nemesius was an influential bishop from the early Christian period who played a vital role in the theological debates of his time. Renowned for his writings, he sought to clarify the divine nature of Christ and the Holy Spirit. His legacy continues to inspire scholars and theologians striving for truth in their faith.', 'Faith is the light that illuminates the path of truth.', 'December 19', NULL, 2, 10, 10, 8, 1, 1),

('Dominic of Silos', 'dominic-of-silos', 'He is known for his deep dedication to prayer and monastic life in the service of God.', 'St. Dominic of Silos was a Benedictine monk who lived in the 11th century in Spain. He played a significant role in reforming his monastery and was renowned for his piety and dedication to the Lord. His life exemplifies the virtues of humility and steadfast faith amidst challenges.', 'Pray, hope, and don''t worry.', 'December 20', NULL, 3, 10, 1, 1, 1, 4),

('Chaeremon', 'chaeremon', 'He is known for his steadfast faith during the persecution of Christians in Egypt.', 'St. Chaeremon was a bishop in Egypt during a turbulent time for Christians. He courageously faced persecution and martyrdom rather than renounce his faith. His legacy inspires many to stand firm in their convictions amidst adversity.', 'The blood of martyrs is the seed of Christians.', 'December 22', NULL, 4, 10, 1, 10, 1, 4),

('John of Kanty', 'john-of-kanty', 'A noted scholar and theologian known for his piety and dedication to education.', 'St. John of Kanty was a Polish priest and scholar who dedicated his life to teaching and guiding students in their spiritual and academic pursuits. Known for his humility and kindness, he spent many years at the University of Kraków, where he inspired countless young minds. His legacy continues to influence educators and students alike in their quest for knowledge and virtue.', 'The greatest gift one can give is to serve others.', 'December 23', NULL, 1, 10, 4, 1, 1, 1),

('Adam', 'adam', 'Known as the first man created by God, symbolizing humanity''s beginnings.', 'St. Adam, celebrated on December 24, is revered as the first man according to the Judeo-Christian tradition. His creation narrative plays a pivotal role in theology, illustrating the relationship between God and humanity. In many Christian teachings, St. Adam represents the original innocence of man before the Fall.', 'But of the tree of the knowledge of good and evil, thou shalt not eat of it: for in the day that thou eatest thereof thou shalt surely die.', 'December 24', NULL, 1, 1, 1, 1, 1, 10),

('Aetherius', 'aetherius', 'St. Aetherius is recognized as a martyr of the early Church.', 'St. Aetherius was a devoted Christian who faced persecution during the era of Emperor Diocletian. He was known for his unwavering faith and courage in the face of death. His legacy inspires many faithful to stand firm in their beliefs despite adversity.', 'Faith is the substance of things hoped for, the evidence of things not seen.', 'December 25', NULL, 2, 5, 1, 10, 3, 3),

('Thomas Becket', 'thomas-becket', 'Martyrdom for the independence of the Church.', 'St. Thomas Becket was the Archbishop of Canterbury who fiercely contested the authority of King Henry II over the church. His dedication to church independence led to a dramatic confrontation resulting in his martyrdom. Today, he is remembered as a symbol of religious freedom and integrity in leadership.', 'I am ready to die for my country, but I will not betray my church.', 'December 28', NULL, 2, 1, 1, 10, 3, 5),

('Sylvester', 'sylvester', 'Known for being the Pope who led the Church during the first half of the 4th century.', 'St. Sylvester was the pope who presided over the Church during a time of significant growth and transition. He is celebrated for his role in the Council of Nicaea, which addressed the Arian controversy. Pope Sylvester''s leadership laid the foundation for the future of the Church in a rapidly changing world.', 'Faith is the entrance to the life of Christ.', 'December 31', NULL, 1, 10, 10, 10, 7, 3),

('Severinus', 'severinus', 'Known for his ascetic life and miraculous deeds as a monk and missionary in the region that is now Austria.', 'St. Severinus was a wandering monk who dedicated his life to spreading Christianity among the pagan tribes of the Danube region. He became famous for his miraculous interventions, including restoring health to the sick and boosting the harvest during famine. His legacy as a holy man has rendered him a highly revered figure in Austrian Catholic tradition.', 'To serve God is the greatest joy of life.', 'January 8', NULL, 2, 8, 1, 2, 1, 10),

('Head of the Holy Innocents', 'head-of-the-holy-innocents', 'Known for being a martyr among the Holy Innocents massacred by King Herod.', 'St. Head of the Holy Innocents represents the tragic fate of the innocents slain at the behest of Herod during his attempt to eliminate the prophesied King. While their lives were taken too soon, their martyrdom symbolizes the purity and innocence of childhood. He is commemorated on February 2nd, a day that also marks the Presentation of Jesus at the Temple.', 'The blood of the martyrs is the seed of the Church.', 'February 2', NULL, 1, 1, 1, 1, 1, 10),

('Margaret of Cortona', 'margaret-of-cortona', 'Known for her life of penitence and dedication to the poor after a life of sin.', 'St. Margaret of Cortona was a 13th-century Italian saint who transformed her life from one of sin and comfort to one of deep devotion and charity after a personal tragedy. Having lost her lover, she embraced a life of penance, dedicating herself to helping the poor and living in a manner wholly devoted to God. Her legacy continues to inspire those who seek redemption and a deeper relationship with Christ.', 'In the depth of my sin, God''s mercy found me.', 'February 22', NULL, 4, 10, 1, 6, 4, 4),

('Oswald of Northumbria', 'oswald-of-northumbria', 'He is known for his efforts in spreading Christianity in Northumbria.', 'St. Oswald was an influential king of Northumbria who played a crucial role in the Christianization of England. He established a strong alliance with the Irish Church, which helped to promote the faith among his people. His reign was marked by notable victories and the founding of monasteries that contributed to the spiritual growth of the region.', 'Lord, I ask you to bless this nation and all who dwell within it.', 'February 29', NULL, 3, 8, 1, 10, 1, 8),

('Maximilian of Tebessa', 'maximilian-of-tebessa', 'Being a Christian martyr during the Roman Empire and known for his bold confession of faith.', 'St. Maximilian was a young Christian from Tebessa in present-day Algeria, who boldly professed his faith in the face of persecution. He was a member of a prominent family and chose martyrdom over renouncing his beliefs, ultimately executed for refusing military service against fellow Christians. His story serves as a testament to the power of conviction and the sacrifices made for the faith in its early days.', 'I am a Christian, and I cannot serve the idols.', 'March 12', NULL, 2, 5, 1, 10, 3, 3),

('Benedict the Moor', 'benedict-the-moor', 'St. Benedict the Moor is celebrated for his life of humility and service to God despite facing racial discrimination.', 'Born in Sicily, St. Benedict the Moor overcame the challenges of his mixed-race heritage to lead a life of profound faith and piety. He became a Franciscan lay brother, known for his dedication to prayer and service to the marginalized. Benedict’s example of charity and humility continues to inspire many, especially those facing prejudice.', 'Preach the Gospel at all times', 'April 3', NULL, 1, 10, 1, 6, 3, 1),

('Anicetus', 'anicetus', 'He was a Pope in the early Christian Church known for his role in combating heresy.', 'St. Anicetus served as Pope in the 2nd century and was notably involved in addressing the challenges brought by early heresies. His papacy was marked by a strong commitment to preserving the integrity of apostolic teachings. Although not much is known about his life, he is remembered for his efforts to unify early Christians in their faith.', 'The blood of martyrs is the seed of the Church.', 'April 17', NULL, 5, 8, 5, 1, 1, 10),

('Ansbert', 'ansbert', 'Ansbert is known for his role as a bishop and his dedication to monastic life.', 'St. Ansbert was a devoted bishop in the 8th century who dedicated his life to the spiritual well-being of his flock. He is often remembered for his strong advocacy for monastic practices and education. His legacy continues to inspire those who seek a life of faith and service within the Church.', 'The love of God is an unchangeable source of strength.', 'April 21', NULL, 3, 10, 4, 1, 1, 3),

('Basil the Elder', 'basil-the-elder', 'Bishop of Caesarea known for great piety and the father of St. Basil the Great.', 'St. Basil the Elder was a revered bishop whose life was marked by deep faith and commitment to his flock. He was the father of St. Basil the Great, illustrating a spiritual legacy of strength and virtue. His dedication to the Church and its teachings had a profound impact on early Christian communities.', 'A good shepherd lays down his life for the sheep.', 'April 26', NULL, 1, 10, 1, 3, 1, 1),

('Maximinus of Aix', 'maximinus-of-aix', 'He was the first bishop of Aix-en-Provence and played a key role in spreading Christianity in the region.', 'St. Maximinus of Aix is remembered as a devoted leader of the early Church in Provence, tirelessly working to convert and support his community. His efforts laid the groundwork for the growth of the Christian faith in southern France during a time of significant persecution. He is venerated not only for his ministry but also for his wisdom and guidance to his followers.', 'Faith is the foundation upon which we build our lives.', 'May 29', NULL, 3, 10, 10, 10, 7, 7),

('John of San Facundo', 'john-of-san-facundo', 'His dedication to the reform of the clergy and his commitment to the spiritual life.', 'St. John of San Facundo was a Spanish priest known for his austere lifestyle and devotion to prayer. He founded a congregation for the reform of the clergy during a time when the Church was facing significant moral challenges. His life was marked by a commitment to humility and service, earning him veneration as a saint.', 'He who has no faith has no conviction.', 'June 12', NULL, 4, 10, 1, 1, 1, 8),

('Willibald', 'willibald', 'He is known for his missionary work and founding of several churches in Germany.', 'St. Willibald was an English monk who set out on a pilgrimage to the Holy Land. His travels took him across Europe, where he shared the Christian faith and established monasteries. His dedication to spreading the Gospel and his commitment to the monastic life made him a revered figure in early Christianity.', 'May your heart be a vessel of love and your hands a source of kindness.', 'July 7', NULL, 4, 10, 1, 8, 2, 4),

('Cuthbert of Lindisfarne', 'cuthbert-of-lindisfarne', 'He is known for his piety, miraculous deeds, and role in spreading Christianity in northern England.', 'St. Cuthbert was a monk and bishop in the early medieval period, revered for his dedication to monastic life and the spiritual wellbeing of his community. His life was marked by numerous miracles and a deep connection to nature, which led many to regard him as a saint shortly after his death. Cuthbert''s legacy continues through the monastic traditions he established at Lindisfarne, which played a pivotal role in the spread of Christianity in Britain.', 'For whom have I in heaven but you? And there is nothing on earth that I desire besides you.', 'July 8', NULL, 4, 10, 1, 4, 1, 6),

('Lydwine of Schiedam', 'lydwine-of-schiedam', 'Known for her extraordinary suffering and mystical experiences, which inspired many to a deeper faith.', 'St. Lydwine was a Dutch mystic who experienced a series of debilitating illnesses from a young age. Despite her intense suffering, she found solace in her faith and had numerous visions, serving as a spiritual guide for her community. Her profound journey and dedication led to her being revered as a saint and the patroness of the sick.', 'In sickness and suffering, I found the depths of God''s love.', 'July 16', NULL, 6, 6, 1, 4, 1, 10),

('Nicetas of Remesiana', 'nicetas-of-remesiana', 'He was known for his evangelization efforts among the Goths and for his theological writings.', 'St. Nicetas of Remesiana was a Bishop in the early Church who played a crucial role in spreading Christianity among the Gothic tribes. He is credited with composing various theological texts that aided the understanding of the faith in a time of great cultural upheaval. His dedication to the pastoral care of his flock and commitment to missionary work helped lay the groundwork for the future growth of the Church in Eastern Europe.', 'Faith is the anchor of the soul.', 'September 14', NULL, 2, 4, 10, 8, 1, 6),

('Pacificus of San Severino', 'pacificus-of-san-severino', 'He is known for his deep spirituality and commitment to prayer and penance.', 'St. Pacificus of San Severino was an Italian Franciscan friar who dedicated his life to serving the poor and spreading the Gospel. Throughout his life, he engaged in rigorous self-discipline and promoted a deep devotion to prayer among his fellow friars. His legacy continues to inspire those who seek a life of humility and service in their communities.', 'In every act of kindness, God is present.', 'September 24', NULL, 8, 10, 6, 2, 1, 4),

('Finbar', 'finbar', 'Finbar is known as the founder and patron saint of the city of Cork in Ireland.', 'St. Finbar was an early Irish priest and abbot who established a monastic community in Cork. His dedication to education and the spiritual well-being of his community left a lasting legacy that is remembered in the region to this day. Many local legends surround his life, emphasizing his deep faith and miraculous deeds.', 'The lighter the heart, the heavier the grace.', 'September 25', NULL, 3, 10, 7, 1, 1, 1),

('Fructuosus', 'fructuosus', 'He is known as a martyr who was executed during the persecution of Christians under Emperor Valerian.', 'St. Fructuosus was a Spanish bishop in the early Church who bravely faced martyrdom alongside his deacons, Augurius and Eulogius. His steadfast faith in the face of persecution made him a symbol of courage among Christians. His legacy continues through the many churches named in his honor across Spain and beyond.', 'The moment you give up is the moment you let someone else win.', 'October 27', NULL, 1, 6, 6, 10, 1, 4),

('Edmund Rich', 'edmund-rich', 'Known for his role as the Archbishop of Canterbury and his commitment to justice and peace.', 'St. Edmund Rich was a notable English archbishop renowned for his wisdom and piety. Throughout his life, he worked tirelessly for the welfare of his people, often facing adversity and opposition. His dedication to justice earned him respect and admiration, leading to his canonization shortly after his death.', 'Justice consists in doing no injury to men', 'November 20', NULL, 2, 10, 6, 4, 1, 2),

('Virgil of Salzburg', 'virgil-of-salzburg', 'Being the Bishop of Salzburg who contributed to the spread of Christianity in the region and was known for his scholarly work.', 'St. Virgil was a learned monk who served as Bishop of Salzburg during the 8th century. He played a crucial role in the establishment of the church in Bavaria and was instrumental in the evangelization of the surrounding areas. A man of deep faith and intellect, he is remembered for his dedication to both education and pastoral care.', 'Faith is the compass that guides us through the storms of life.', 'November 27', NULL, 2, 7, 10, 2, 1, 2),

('Romanus of Condat', 'romanus-of-condat', 'He is known for founding the Abbey of Condat and promoting a life of prayer and asceticism among monks.', 'St. Romanus of Condat was a revered hermit and abbot known for his commitment to monastic life in the wilderness of modern-day France. He founded the Abbey of Condat, where he emphasized the virtues of prayer, community, and asceticism, leading many souls to a deeper relationship with God. His life exemplified humility, faithfulness, and devotion, inspiring generations of monks and laypeople alike.', 'It is in solitude that we can truly discover God''s presence.', 'February 28', NULL, 3, 7, 10, 1, 1, 10),

('Medard', 'medard', 'He is known for his role as a bishop and protector against storms, particularly in the region of Picardy, France.', 'St. Medard was a 6th-century bishop known for his piety and dedication to God. He became famous as a protector against storms and was often sought for his intercessions for good weather. His charitable work and commitment to the spiritual welfare of his people made him a beloved figure in the Church.', 'Faith is the light that guides us through the darkest storms.', 'June 8', NULL, 3, 10, 10, 1, 1, 7),

('Martial', 'martial', 'He is known for being one of the first bishops of Limoges and for his role in establishing and spreading Christianity in the region.', 'St. Martial was a bishop in Limoges who played a significant role in the spread of Christianity in the region of Aquitaine during the 3rd century. He is recognized for his unwavering faith and dedication to preaching the Gospel, despite facing persecution and hardship. His legacy of leadership and commitment to God’s work continues to inspire many believers.', 'Faith is the light that guides us through the darkness of doubt.', 'June 30', NULL, 2, 1, 2, 10, 1, 6),

('Frederick', 'frederick', 'St. Frederick is known for his foundational role in monasticism and his contributions to community-building among early Christians.', 'St. Frederick was a revered hermit and abbot in the early Christian church, known for his devout life and dedication to God. He led a community of monks, emphasizing the importance of prayer, humility, and communal living as a path to holiness. His virtuous life and commitment to serving others made him a beloved figure among those who sought inspiration in the monastic tradition.', 'Let us not seek to be better than others, but strive to be better than we were yesterday.', 'July 18', NULL, 3, 7, 10, 1, 1, 7),

('Afra', 'afra', 'She is known for her steadfast faith and martyrdom during the early Christian persecutions.', 'St. Afra was a Christian martyr who lived in the early centuries of Christianity. She is believed to have converted to Christianity despite the pressures of her former life and served as a symbol of redemption. Her unwavering faith and commitment to her newfound beliefs ultimately led to her martyrdom as she faced persecution for her convictions.', 'Faith is the bird that feels the light and sings when the dawn is still dark.', 'August 5', NULL, 1, 1, 1, 1, 1, 10),

('Symphorian', 'symphorian', 'St. Symphorian is known for his unwavering faith in the face of persecution and his inspirational martyrdom.', 'St. Symphorian was a young Christian martyr from the second century, who remained steadfast in his faith despite persecution. He was arrested and ultimately executed for refusing to renounce his beliefs. His bravery and commitment to Christ inspire many to embrace their faith with courage and conviction.', 'The glory of God is man fully alive.', 'August 22', NULL, 1, 1, 1, 10, 1, 7),

('Sabina', 'sabina', 'St. Sabina is known for her martyrdom and her unwavering faith in the face of persecution.', 'St. Sabina was a noble Roman woman who embraced Christianity and was martyred for her faith. She is celebrated for her steadfastness in belief, especially during the persecutions against Christians. Her virtues of courage and faith have inspired many in their spiritual journeys.', 'The glory of God is the living man, and the life of man is the vision of God.', 'August 29', NULL, 1, 1, 1, 10, 1, 7),

('Pammachius', 'pammachius', 'St. Pammachius is known for being a dedicated Christian martyr and an advocate for the needy during the early days of Christianity.', 'St. Pammachius was a prominent Roman noble who became a Christian martyr during the persecution of Christians in the early church. Known for his unwavering faith and commitment to aiding the poor and sick, he was a close confidante of St. Jerome, who praised his virtues and dedication to the faith. He ultimately died for his beliefs, leaving behind a legacy of charity and devotion that continues to inspire the faithful.', 'The blood of martyrs is the seed of the Church.', 'August 30', NULL, 1, 1, 1, 10, 1, 7),

('Adrian', 'adrian', 'He is known for his martyrdom during the persecutions of Christians under Emperor Maximilian.', 'St. Adrian was a prominent figure during the early Christian period, known for his unwavering faith and strong leadership as a devout Christian. He worked fervently to uphold Christian teachings, often placing himself in danger for the sake of his beliefs. His martyrdom is celebrated as a testament to his dedication to Christ and his role in inspiring others to live virtuous lives.', 'The greatest weapon against stress is our ability to choose one thought over another.', 'September 8', NULL, 2, 1, 2, 10, 1, 4),

('Gelasius I', 'gelasius-i', 'St. Gelasius I is known for his significant contributions to the doctrine and governance of the early Church.', 'St. Gelasius I served as Pope from 492 until his death in 496. He is recognized for his leadership during a time of political turmoil and for his efforts in defining the relationship between Church and State. His teaching emphasized the importance of unity and purity of faith among Christians.', 'What you are is God''s gift to you', 'November 21', NULL, 1, 1, 10, 5, 1, 3),

('Eutychian', 'eutychian', 'St. Eutychian is known for his leadership as Pope and his martyrdom during the early Christian persecutions.', 'St. Eutychian served as the Pope in the 2nd century, leading the Church through a time of trial and growth. He is remembered for his unwavering commitment to the duties of his office and for nurturing the faith of the early Christians. His martyrdom is seen as a testament to his deep faith and dedication to Christ.', 'Faith is the assurance of things hoped for, the conviction of things not seen.', 'December 8', NULL, 1, 1, 10, 10, 1, 3),

('Trophimus', 'trophimus', 'He is primarily known for his role as a martyr and a companion to St. Paul in the early Church.', 'St. Trophimus is known as a companion of St. Paul, having served as a supporter in his ministry during the early Christian church. A devoted and tireless worker in spreading the Gospel, he was eventually martyred for his faith, exemplifying courage and conviction. His unwavering dedication to Christ and his compassion for the marginalized have made him a revered figure in the Catholic Church.', 'Faith is the anchor of the soul, firm and secure.', 'December 29', NULL, 1, 1, 1, 10, 1, 7),

('Egwin', 'egwin', 'He is known for founding the Abbey of Evesham and fostering monastic life in England.', 'St. Egwin was a bishop of East Anglia in the 7th century known for his deep piety and commitment to monastic life. After leading a dedicated life, he established the monastery of Evesham, which became prominent in the region. His virtues of humility and service earned him a lasting legacy as a guiding light for many in their faith.', 'True love is not a feeling of great excitement, but a love that is steadfast and persevering.', 'December 30', NULL, 3, 7, 10, 1, 1, 7),

('Seraphim of Sarov', 'seraphim-of-sarov', 'One of the most beloved Russian mystics, known for his joy and hospitality to all.', 'Seraphim lived as a hermit in the forest for 25 years. He spent a thousand nights standing on a rock in prayer. Later, he opened his door to pilgrims, greeting everyone with the words ''My joy, Christ is risen!'' He emphasized the ''acquisition of the Holy Spirit'' as the goal of the Christian life.', 'My joy, I pray you, acquire a peaceful spirit, and then thousands around you will be saved.', 'January 2', NULL, 3, 7, 1, 1, 10, 10),

('Paisios of Mount Athos', 'paisios-of-mount-athos', 'A modern Athonite elder known for his profound spiritual wisdom and prophecies.', 'Paisios was an Athonite monk who became world-famous in his later years. Thousands of people flocked to his small cell on Mount Athos for advice. He was known for his extreme asceticism, his sense of humor, and his ability to see the spiritual root of people''s modern psychological struggles.', 'God is the only one who can fill the void in a person''s life.', 'July 12', NULL, 3, 7, 10, 1, 1, 10),

('Gregory Palamas', 'gregory-palamas', 'Archbishop of Thessaloniki and defender of Hesychasm (the practice of silent prayer).', 'A monk of Mount Athos, Gregory defended the traditional Orthodox understanding that humans can truly experience God''s ''uncreated energies'' through prayer, even though His ''essence'' remains unknowable.', 'God is called ''Light'', not according to His essence, but according to His energy.', 'November 14', NULL, 1, 1, 1, 1, 1, 10),

('Pachomius', 'pachomius', 'The founder of ''cenobitic'' (community) monasticism.', 'A former Roman soldier, Pachomius sought a way for monks to live together in community rather than as hermits. He wrote the first monastic Rule, emphasizing obedience, labor, and mutual support.', 'True virtue consists in doing God''s will with a joyful heart.', 'May 9', NULL, 2, 10, 2, 4, 1, 8),

('Sergius of Radonezh', 'sergius-of-radonezh', 'The greatest spiritual leader of medieval Russia and founder of the Trinity Lavra.', 'Sergius was a humble monk who revitalized Russian monasticism. He was known for his extreme poverty, his love for work, and his ability to reconcile quarreling princes, helping to unite Russia during the Mongol yoke.', 'Love God and love one another.', 'September 25', NULL, 5, 5, 3, 5, 1, 10),

('Louis de Montfort', 'louis-de-montfort', 'Promoter of the Rosary and ''True Devotion to Mary''.', 'Louis was a tireless missionary who traveled across western France, preaching the Gospel and the Rosary. He founded the Company of Mary and the Daughters of Wisdom and wrote the classic ''True Devotion to the Blessed Virgin''.', 'To Jesus through Mary.', 'April 28', NULL, 5, 3, 1, 1, 1, 10),

('Margaret of Antioch', 'margaret-of-antioch', 'A virgin martyr who reportedly defeated a dragon through the sign of the cross.', 'Margaret was disowned by her father for her conversion. She was tortured and imprisoned, and according to legend, she was swallowed by a dragon in her cell but emerged unharmed when the cross she held caused the dragon to burst open.', 'My faith in Christ is my strength.', 'July 20', NULL, 2, 1, 1, 10, 1, 10),

('Anastasia', 'anastasia', 'A Roman martyr who was known for visiting and caring for imprisoned Christians.', 'Anastasia was the daughter of a pagan father and a Christian mother. She spent her life and fortune ministering to those suffering in prison for their faith. She was finally martyred by being burned at the stake during the Diocletian persecution.', 'Christ is my hope.', 'December 25', NULL, 3, 8, 1, 8, 1, 10),

('Ursula', 'ursula', 'A legendary British princess who traveled across Europe with 11,000 virgins and was martyred by the Huns.', 'Ursula''s story is one of the most famous legends of the Middle Ages. She led a group of young women on a pilgrimage to Rome. On their return trip, they were intercepted at Cologne by the Huns, who martyred them when they refused to renounce their faith or marry the Hun army.', 'We follow the King of Kings.', 'October 21', NULL, 1, 1, 2, 10, 1, 8),

('Dominic Savio', 'dominic-savio', 'A young pupil of St. John Bosco who achieved great holiness at a very early age.', 'Dominic joined Don Bosco''s oratory at age 12. He was known for his extraordinary maturity, his peacemaking among other boys, and his intense devotion to the Eucharist. He died of pleurisy at age 14, becoming the youngest non-martyr to be canonized.', 'Death but not sin!', 'May 6', NULL, 2, 1, 1, 1, 6, 10),

('Maria Mazzarello', 'maria-mazzarello', 'Co-founder of the Salesian Sisters (Daughters of Mary Help of Christians).', 'Maria was a hardworking peasant girl who, after surviving typhus, founded a workshop to teach needlework to young girls and provide them with a Christian education. She teamed up with Don Bosco to form a women''s branch of his Salesian mission.', 'Be cheerful at all times.', 'May 13', NULL, 2, 10, 2, 4, 6, 2),

('Mariam Baouardy', 'mariam-baouardy', 'A Palestinian Carmelite mystic known as ''The Little Arab'' who received the stigmata and visions.', 'Also known as St. Mary of Jesus Crucified, she was a barely literate peasant girl from I''billin. She founded the Carmelite convent in Bethlehem and was known for her extraordinary spiritual gifts, including levitation and deep mystical insight.', 'Holy Spirit, inspire me', 'August 25', NULL, 5, 3, 1, 1, 1, 10),

('John Neumann', 'john-neumann', 'A missionary from Bohemia who became the fourth Bishop of Philadelphia and founded the first diocesan school system in the US.', 'Neumann came to America with only one suit and $1 in his pocket. He was a tireless worker who learned eight languages to serve the diverse immigrant populations of New York and Pennsylvania. He established over 100 schools during his short time as bishop.', 'Everyone who breathes is my neighbor.', 'January 5', NULL, 2, 10, 2, 4, 1, 4),

('Matrona of Moscow', 'matrona-of-moscow', 'A blind and crippled Russian wonderworker who was one of the most beloved saints of the 20th century.', 'Born blind in a peasant family, Matrona spent her life in prayer and counseling thousands who sought her help during the difficult years of Soviet rule. Despite her physical disabilities and the constant threat of arrest, she was a source of spiritual light and healing for any who came to her.', 'Come to me and tell me as if I were alive, and I will see you and hear you, and help you.', 'May 2', NULL, 2, 1, 1, 1, 1, 10),

('Luke of Simferopol', 'luke-of-simferopol', 'A brilliant surgeon, professor, and archbishop who continued to serve the sick even while in Soviet exile.', 'Dr. Valentin Voyno-Yasenetsky was a world-class surgeon who wrote ''Essays on Purulent Surgery'', a textbook used for decades. He became a priest and then a bishop during the height of Stalin''s purges. He spent 11 years in various prisons and exiles, often performing surgeries with limited tools to save the lives of fellow prisoners.', 'I have loved medicine, but I loved my God more.', 'June 11', NULL, 1, 8, 1, 8, 1, 10),

('Seraphim of Vyritsa', 'seraphim-of-vyritsa', 'A wealthy merchant who gave away his fortune after the Revolution to become a monk and a spiritual elder.', 'Vasily Muravyov was a successful businessman/milionaire who entered a monastery with his wife (who became a nun). During WWII, he prayed for 1,000 nights on a rock for the salvation of Russia, mirroring his namesake St. Seraphim of Sarov. He became a beloved elder to whom thousands of people from Leningrad flocked for comfort.', 'The most important thing is to love God and your neighbor.', 'April 3', NULL, 7, 10, 10, 7, 1, 10),

('Maria of Gatchina', 'maria-of-gatchina', 'A bedridden nun and martyr who was a source of spiritual strength for thousands during the Soviet era.', 'Maria suffered from Parkinson''s disease which left her completely paralyzed and in constant pain. Despite this, she was transformed into a spiritual elder who could read souls. People lined up outside her house in Gatchina to receive her counsel. She was finally arrested and died in a prison hospital.', 'God is our strength', 'February 8', NULL, 3, 1, 1, 5, 8, 10),

('Elizabeth the New Martyr', 'elizabeth-the-new-martyr', 'A Grand Duchess of Russia who became a nun after her husband''s murder and founded a convent for the poor.', 'Princess Elizabeth of Hesse was the granddaughter of Queen Victoria and sister to the last Tsarina. After her husband was killed by a bomb, she visited his assassin to forgive him. She became a nun and founded the Martha and Mary Convent in Moscow, serving the city''s poorest. She was thrown down a mine shaft alive by the Bolsheviks.', 'Lord, forgive them, for they know not what they do.', 'July 18', NULL, 2, 2, 1, 4, 1, 10),

('Barbara the New Martyr', 'barbara-the-new-martyr', 'The faithful companion and fellow martyr of St. Elizabeth the New Martyr.', 'Barbara Yakovleva was a novice at the Martha and Mary Convent and a devoted friend of St. Elizabeth. When the secret police came to deport Elizabeth, they offered Barbara her freedom, but she refused to abandon her mentor. She shared in the same horrific death in the Alapaevsk mine shaft.', 'I will not leave you, no matter what happens.', 'July 18', NULL, 2, 6, 1, 10, 1, 6),

('Vladimir of Kiev', 'vladimir-of-kiev', 'The Grand Prince of Kiev who converted to Christianity and baptized the entire nation of Kievan Rus''.', 'Vladimir was a fierce pagan ruler who sent envoys to research different religions. They were so moved by the beauty of the liturgy in Constantinople that he chose Orthodoxy. After his conversion, he radically changed his life, dismissing his many wives and building churches and hospitals.', 'I have found the true faith.', 'July 15', NULL, 2, 1, 2, 4, 1, 10),

('Olga of Kiev', 'olga-of-kiev', 'The first Christian ruler of Kievan Rus'', known for her wisdom and her role in paving the way for her grandson St. Vladimir.', 'Olga was a regent who ruled Kyivan Rus'' with great skill. She was baptized in Constantinople and attempted to bring Christianity to her people, though her own son refused to convert. She is remembered as the first saint of the Russian Orthodox Church.', 'Let my people see the light of Christ.', 'July 11', NULL, 3, 1, 10, 10, 1, 8),

('Boris', 'boris', 'Prince of Kiev and martyr who refused to fight his brother for the throne, becoming a ''Passion-bearer''.', 'Boris was a son of St. Vladimir. When his elder brother Sviatopolk plotted to seize the throne, Boris''s troops urged him to fight back. Instead, Boris chose to model Christ by non-resistance, sending his army home and waiting for his assassins while singing psalms.', 'I will not lift a hand against my brother.', 'May 2', NULL, 3, 10, 1, 7, 1, 10),

('Gleb', 'gleb', 'Prince of Kiev and fellow martyr with his brother St. Boris.', 'Gleb was the younger brother of Boris. Like his brother, he refused to take up arms against Sviatopolk, choosing instead to follow the example of Christ''s voluntary suffering. He was murdered shortly after Boris.', 'Blessed are the peacemakers.', 'May 2', NULL, 1, 2, 1, 4, 1, 10),

('Alexander Nevsky', 'alexander-nevsky', 'Grand Prince of Russia and legendary military leader who protected the Orthodox faith from foreign invaders.', 'Alexander was a brilliant general who defeated the Swedes on the Neva River and the Teutonic Knights on Lake Peipus. He used his diplomatic skills to manage the relationship with the Golden Horde, saving Russia from complete destruction. He took monastic vows on his deathbed.', 'God is not in power, but in truth.', 'November 23', NULL, 2, 1, 2, 10, 1, 8),

('Savva of Serbia', 'savva-of-serbia', 'The first Archbishop of the autocephalous Serbian Orthodox Church and national hero of Serbia.', 'Savva was a prince who secretly fled to Mount Athos to become a monk. He later returned to Serbia to establish its independent church, founded schools and hospitals, and negotiated peace between his brothers. He is considered the father of Serbian culture and identity.', 'The soul is more precious than the body.', 'January 14', NULL, 3, 1, 10, 5, 1, 10),

('David of Wales', 'david-of-wales', 'The patron saint of Wales and a bishop who founded many monasteries known for their extreme austerity.', 'David (Dewi Sant) was a prominent figure in the Celtic Church. He was known as ''The Waterman'' (Aquaticus) because he and his monks drank only water and ate only bread and herbs. His final words to his followers, ''Do the little things'', is a beloved Welsh proverb.', 'Be joyful, keep the faith, and do the little things.', 'March 1', NULL, 2, 1, 2, 4, 1, 10),

('Columba of Iona', 'columba-of-iona', 'The ''Apostle to the Picts'', a powerful Irish abbot who founded the monastery of Iona and converted much of Scotland.', 'Columba (Colum Cille) was a prince and a gifted scholar. After a conflict over a copied book led to a battle, he went into exile on the island of Iona. From there, he became a major cultural and religious force, establishing a network of monasteries and spreading the faith throughout the British Isles.', 'I follow the King of Kings.', 'June 9', NULL, 1, 1, 2, 10, 4, 6),

('Dunstan', 'dunstan', 'Archbishop of Canterbury who revitalized English monasticism and served as a statesman under several kings.', 'Dunstan was an artist, a musician, and a skilled metalworker before becoming a monk. He rose to become the most powerful religious leader in England, reforming the clergy and using his influence to bring stability to the country. He was also a noted bell-caster.', 'The measure of love is to love without measure.', 'May 19', NULL, 1, 1, 3, 5, 5, 10),

('Perpetua', 'perpetua', 'A young noblewoman and mother who kept a diary of her imprisonment and was martyred in Carthage for refusing to renounce her faith.', 'St. Perpetua was a young, well-educated noblewoman from Carthage who was arrested during the persecution of Emperor Septimius Severus. Despite her father''s pleas and her love for her infant son, she refused to renounce her faith. Her prison diary is one of the earliest known writings by a Christian woman and provides a vivid account of early Christian martyrdom.', 'I am a Christian, and I cannot be called by any other name.', 'March 7', NULL, 1, 1, 1, 10, 1, 3),

('Felicity of Carthage', 'felicity-of-carthage', 'A slave and companion of St. Perpetua who gave birth in prison and was martyred alongside her mistress in the arena.', 'St. Felicity was an enslaved woman who was arrested along with her mistress Perpetua and other catechumens in Carthage. She was eight months pregnant at the time of her arrest and gave birth to a daughter in prison just days before her martyrdom. Her bravery alongside Perpetua has made them inseparable symbols of Christian courage.', 'What I suffer now, I suffer alone. But then, another will be in me who will suffer for me.', 'March 7', NULL, 2, 6, 1, 10, 1, 4),

('Paul Chong Hasang', 'paul-chong-hasang', 'A Korean lay catechist and seminarist martyred for his faith during the Joseon Dynasty persecutions.', 'St. Paul Chong Hasang was a Korean lay catechist whose father was one of the first Korean martyrs. He worked tirelessly to bring foreign missionaries into Korea and to organize the underground Catholic community. He was arrested, imprisoned, and eventually executed for his faith.', 'Even if we die, we cannot betray the Lord of heaven whom we serve.', 'September 20', NULL, 1, 1, 8, 10, 1, 4),

('Marguerite Bays', 'marguerite-bays', 'A Swiss laywoman and mystic who received the stigmata and lived a life of extraordinary prayer and charity as a simple seamstress.', 'St. Marguerite Bays was a Swiss seamstress who lived a hidden life of extraordinary holiness. She was miraculously healed of intestinal cancer and received the stigmata, experiencing the wounds of Christ every Friday. Despite these mystical gifts, she continued her humble life of sewing, teaching catechism, and caring for the sick.', 'God does not ask great things of us, only small things with great love.', 'June 27', NULL, 4, 4, 1, 1, 1, 10),

('Alberto Hurtado', 'alberto-hurtado', 'A Chilean Jesuit priest who founded a nationwide network of shelters for homeless children and championed workers'' rights.', 'St. Alberto Hurtado was a Chilean Jesuit who dedicated his life to the poorest of the poor. He founded Hogar de Cristo, a network providing shelter, education, and care for homeless children across Chile. He also advocated for labor rights and wrote extensively on Catholic social teaching.', 'Christ has no body now on earth but yours.', 'August 18', NULL, 1, 1, 2, 10, 1, 6),

('Peter To Rot', 'peter-to-rot', 'A Papuan catechist who was martyred by the Japanese during World War II for defending the sanctity of Christian marriage.', 'St. Peter To Rot was a catechist from the Tolai people of Papua New Guinea. During the Japanese occupation in World War II, he continued to lead his community in prayer and defended the sanctity of Christian marriage against the occupiers'' attempts to impose polygamy. He was arrested and killed by lethal injection.', 'I must fulfill my duty as a catechist.', 'January 12', NULL, 1, 1, 1, 10, 1, 1),

('Agnes Le Thi Thanh', 'agnes-le-thi-thanh', 'A Vietnamese laywoman and mother who was martyred for sheltering priests during the Vietnamese persecutions.', 'St. Agnes Le Thi Thanh was a Vietnamese mother of six who sheltered persecuted priests and missionaries in her home. She was arrested, brutally tortured, and eventually executed for refusing to trample on a crucifix. She is one of the 117 Vietnamese Martyrs canonized by Pope John Paul II.', 'I would rather die than abandon my religion.', 'July 12', NULL, 1, 2, 1, 10, 1, 6),

('Kuriakose Elias Chavara', 'kuriakose-elias-chavara', 'An Indian Carmelite priest who founded the first indigenous religious congregation for men in India and pioneered education for all castes.', 'St. Kuriakose Elias Chavara was an Indian priest of the Syro-Malabar Catholic Church who founded the Carmelites of Mary Immaculate, the first indigenous religious congregation for men in India. He established schools in every parish, including for girls and lower castes, and pioneered a Sanskrit school for interfaith dialogue.', 'Educate the people and they will be transformed.', 'January 3', NULL, 1, 1, 10, 5, 1, 8),

('Euphrasia Eluvathingal', 'euphrasia-eluvathingal', 'An Indian Carmelite nun known as the ''Praying Mother'' for her extraordinary life of contemplative prayer and mystical experiences.', 'St. Euphrasia Eluvathingal was an Indian Carmelite nun of the Syro-Malabar Church known for her deep mystical prayer life. She spent hours in Eucharistic adoration daily and was sought out by people from all walks of life for her spiritual counsel. She was canonized by Pope Francis in 2014.', 'My only desire is to love God and to be consumed in His love.', 'August 29', NULL, 4, 4, 1, 1, 1, 10),

('Devasahayam Pillai', 'devasahayam-pillai', 'The first Indian layperson to be canonized, a Hindu convert who was martyred for his faith in 18th-century southern India.', 'St. Devasahayam Pillai was born Neelakanta Pillai, a high-caste Hindu official in the kingdom of Travancore. After converting to Christianity under the influence of a Dutch naval commander, he faced severe persecution from the royal court. He endured years of imprisonment and torture before being shot and killed, becoming the first Indian layperson to be canonized.', 'I have found the truth and I will not abandon it.', 'January 14', NULL, 1, 1, 1, 10, 1, 3),

('Magdalena of Nagasaki', 'magdalena-of-nagasaki', 'A Japanese Augustinian tertiary who was martyred during the brutal persecution of Christians in 17th-century Japan.', 'St. Magdalena of Nagasaki was the daughter of Japanese Christian martyrs. She became an Augustinian tertiary and served as an interpreter and catechist for missionaries. During the severe Tokugawa persecution, she was arrested and subjected to the torture of tsurushi (being hung upside down over a pit) for 13 days before dying.', 'I am a Christian and I will die a Christian.', 'October 15', NULL, 2, 2, 1, 10, 1, 8),

('Anna Wang', 'anna-wang', 'A 14-year-old Chinese girl martyred during the Boxer Rebellion for refusing to renounce her Christian faith.', 'St. Anna Wang was a young Chinese Christian girl from Majiazhuang village who was caught up in the Boxer Rebellion''s persecution of Christians. When soldiers demanded she renounce her faith, the 14-year-old refused, saying she would rather die. She was beheaded and is among the 120 Martyrs of China canonized by Pope John Paul II.', 'The door of heaven is open to all.', 'July 9', NULL, 1, 1, 1, 10, 1, 3),

('Kizito', 'kizito', 'The youngest of the Uganda Martyrs, killed at approximately 13-14 years old for refusing to renounce Christianity.', 'St. Kizito was the youngest of the Uganda Martyrs, a group of Catholic and Anglican converts killed on the orders of King Mwanga II of Buganda. Despite his young age, he refused to renounce his Christian faith. He was baptized by St. Charles Lwanga the night before their execution and was burned alive alongside his companions.', 'I will go wherever Charles Lwanga goes.', 'June 3', NULL, 1, 2, 1, 10, 1, 6),

('Anuarite Nengapeta', 'anuarite-nengapeta', 'A Congolese religious sister who was martyred for defending her vow of chastity during the Simba Rebellion.', 'St. Anuarite Nengapeta was a Congolese religious sister of the Holy Family who was martyred during the Simba Rebellion. When rebel soldiers attempted to assault her, she resisted and was beaten and stabbed to death. She forgave her attackers before dying, echoing the words of Christ and St. Stephen.', 'I forgive you because you do not know what you are doing.', 'December 1', NULL, 1, 1, 1, 10, 1, 3),

('Mariam Thresia Chiramel', 'mariam-thresia-chiramel', 'An Indian mystic and foundress who established the Congregation of the Holy Family to serve the sick and marginalized in Kerala.', 'St. Mariam Thresia Chiramel Mankidiyan was an Indian mystic of the Syro-Malabar Church who experienced extraordinary spiritual phenomena from childhood. She founded the Congregation of the Holy Family to serve broken families, the sick, and the dying. Despite facing misunderstanding and opposition, she persevered in her mission.', 'My God, let me suffer and love.', 'June 8', NULL, 1, 1, 2, 10, 1, 6),

('Narcisa de Jesús', 'narcisa-de-jes-s', 'An Ecuadorian laywoman known for her extreme penances, deep prayer life, and mystical experiences.', 'St. Narcisa de Jesús Martillo Morán was an Ecuadorian laywoman who lived a life of extraordinary penance and prayer. Though she never joined a religious order, she lived as a consecrated laywoman, spending her days in prayer, fasting, and works of charity. She died in Lima, Peru, at the age of 36.', 'My only desire is to love God above all things.', 'August 30', NULL, 4, 4, 1, 1, 1, 10),

('Roque González', 'roque-gonz-lez', 'A Jesuit missionary who founded several of the famous Guaraní Reductions in South America before being martyred.', 'St. Roque González de Santa Cruz was a Paraguayan Jesuit and one of the first criollo (American-born) priests in South America. He founded several Jesuit Reductions among the Guaraní people, creating self-sustaining communities. He was killed by a shaman who opposed Christian influence.', 'I came to bring the Gospel to the ends of the earth.', 'November 17', NULL, 1, 1, 1, 10, 1, 3),

('Laura of Saint Catherine of Siena', 'laura-of-saint-catherine-of-siena', 'A Colombian foundress who established schools and missions for indigenous and African-descended peoples.', 'St. Laura Montoya Upegui was a Colombian religious sister who founded the Missionary Sisters of Mary Immaculate and St. Catherine of Siena. She dedicated her life to evangelizing and educating indigenous communities in the Colombian jungle, traveling by canoe and mule to reach remote villages.', 'God has given me the indigenous and the African peoples as my inheritance.', 'October 21', NULL, 1, 1, 2, 10, 1, 6),

('María de Jesús Sacramentado', 'mar-a-de-jes-s-sacramentado', 'A Mexican foundress who established the Daughters of the Sacred Heart to serve the poor and abandoned.', 'St. María de Jesús Sacramentado Venegas de la Torre was a Mexican religious sister who founded the Daughters of the Sacred Heart of Jesus. She dedicated over 50 years to caring for the sick, poor, and abandoned in Guadalajara. She persevered through the Mexican Revolution and Cristero War.', 'The Sacred Heart of Jesus is the fountain of all graces.', 'July 30', NULL, 2, 1, 2, 4, 1, 10),

('Felipe de Jesús', 'felipe-de-jes-s', 'A Mexican Franciscan friar who was among the Twenty-Six Martyrs of Japan, crucified in Nagasaki.', 'St. Felipe de Jesús de las Casas was born in Mexico City and became a Franciscan friar. While traveling from the Philippines to Mexico, his ship was blown off course to Japan, where Christians were being persecuted. He was arrested, marched to Nagasaki, and crucified alongside 25 other Christians.', 'I die happily for Christ.', 'February 5', NULL, 1, 2, 1, 10, 1, 6),

('Walburga', 'walburga', 'An Anglo-Saxon missionary nun who helped evangelize Germany and became one of the most venerated saints of the medieval period.', 'St. Walburga was an Anglo-Saxon princess who left England to join her brothers Sts. Willibald and Winebald in their missionary work in Germany. She became abbess of the double monastery of Heidenheim and was renowned for her healing powers and educational work. She is one of the most celebrated women missionaries of the 8th century.', 'Where there is faith, there is light.', 'February 25', NULL, 1, 1, 2, 10, 1, 6),

('Lioba', 'lioba', 'An Anglo-Saxon missionary nun who was instrumental in the evangelization of Germany under St. Boniface.', 'St. Lioba was an Anglo-Saxon Benedictine nun who was sent by her relative St. Boniface to help establish the Church in Germany. She became abbess of Tauberbischofsheim and was renowned for her learning, wisdom, and spiritual counsel. She was so respected that Charlemagne''s wife sought her company.', 'Let us learn from the Scriptures how to live and how to die.', 'September 28', NULL, 1, 1, 10, 3, 1, 3),

('Gudula', 'gudula', 'A Belgian noblewoman who devoted her life to prayer and charity, becoming the patroness of Brussels.', 'St. Gudula was a Frankish noblewoman from Brabant who was educated by her cousin, St. Gertrude of Nivelles. She lived a life of extraordinary piety, walking daily from her home to a church two miles away. She is the patron saint of Brussels, and the city''s cathedral is named after her.', 'Light conquers darkness through faith.', 'January 8', NULL, 4, 4, 1, 1, 1, 10),

('Rabanus Maurus', 'rabanus-maurus', 'A Carolingian-era Benedictine monk, archbishop, and scholar known as ''the Teacher of Germany'' for his encyclopedic works.', 'St. Rabanus Maurus was a Frankish Benedictine monk who became Archbishop of Mainz. He was one of the most important scholars of the Carolingian Renaissance, writing encyclopedias, biblical commentaries, and the famous hymn ''Veni Creator Spiritus.'' He earned the title ''Praeceptor Germaniae'' (Teacher of Germany).', 'Come, Holy Spirit, Creator blest.', 'February 4', NULL, 1, 1, 10, 3, 1, 3),

('Ansgar', 'ansgar', 'The ''Apostle of the North'' who brought Christianity to Scandinavia and served as the first Archbishop of Hamburg-Bremen.', 'St. Ansgar was a Frankish monk who became the first Archbishop of Hamburg-Bremen and dedicated his life to evangelizing Scandinavia. He established the first Christian churches in Denmark and Sweden, enduring raids, setbacks, and the destruction of his mission by Vikings. Despite these challenges, he persevered in his missionary work.', 'One miracle I would ask of God: that by His grace He would make me a good man.', 'February 3', NULL, 1, 1, 2, 10, 1, 6),

('Methodius of Moravia', 'methodius-of-moravia', 'Co-creator of the Glagolitic alphabet and Apostle to the Slavs, who translated the Bible and liturgy into Old Church Slavonic.', 'St. Methodius, together with his brother St. Cyril, is known as one of the Apostles to the Slavs. They created the Glagolitic alphabet to translate Scripture and liturgical texts into Old Church Slavonic, making Christianity accessible to Slavic peoples. Despite opposition from Frankish clergy, Methodius defended the use of the Slavonic liturgy until his death.', 'Let every tongue confess that Jesus Christ is Lord.', 'February 14', NULL, 1, 1, 8, 1, 1, 10),

('Adelaide of Italy', 'adelaide-of-italy', 'A Holy Roman Empress who used her political power for charitable works and the spread of Christianity across Europe.', 'St. Adelaide was a Burgundian princess who became Holy Roman Empress through her marriage to Otto the Great. She endured imprisonment, political intrigue, and family conflict, yet used her influence to promote monasteries, churches, and charitable institutions across Europe. She spent her final years in prayer and penance.', 'Power is given to serve, not to dominate.', 'December 16', NULL, 1, 1, 8, 10, 1, 4),

('Matilda of Ringelheim', 'matilda-of-ringelheim', 'A German queen renowned for her generosity to the poor and her founding of monasteries and charitable institutions.', 'St. Matilda was the wife of King Henry I of Germany (Henry the Fowler) and mother of Emperor Otto the Great. After her husband''s death, she devoted her wealth to founding monasteries, convents, and charitable institutions. Despite being criticized by her sons for her generosity, she continued her charitable work throughout her life.', 'The riches of this world mean nothing compared to the treasures of heaven.', 'March 14', NULL, 3, 5, 1, 1, 1, 10),

('Margaret of Hungary', 'margaret-of-hungary', 'A Hungarian princess who willingly embraced a life of extreme penance and prayer as a Dominican nun.', 'St. Margaret was a daughter of King Béla IV of Hungary who was offered to God as a child in thanksgiving for the country''s deliverance from the Mongol invasion. She entered a Dominican convent on an island in the Danube (now Margaret Island, Budapest) and chose to live a life of extreme penance, refusing all offers of marriage from European royalty.', 'I would rather die than leave my convent.', 'January 18', NULL, 5, 8, 1, 5, 1, 10),

('Zélie Martin', 'z-lie-martin', 'Mother of St. Thérèse of Lisieux and a successful businesswoman who raised a family of extraordinary holiness.', 'St. Zélie Martin (née Guérin) was a French lace-maker and mother of nine children, five of whom became nuns, including St. Thérèse of Lisieux. She ran a successful Alençon lace business while raising her family with deep Catholic devotion. She died of breast cancer at age 45 and was canonized alongside her husband in 2015.', 'I want to become a saint, and for that I must suffer much.', 'July 12', NULL, 1, 1, 1, 1, 1, 10),

('Louis Martin', 'louis-martin', 'Father of St. Thérèse of Lisieux, a watchmaker and devoted father who raised five daughters who all became nuns.', 'St. Louis Martin was a French watchmaker and the father of St. Thérèse of Lisieux. Together with his wife Zélie, he raised five daughters who all entered religious life. After his wife''s death, he supported his daughters'' vocations with profound faith. He suffered from cerebral arteriosclerosis in his later years, enduring his affliction with great patience.', 'God has given me many crosses, but He has also given me much grace.', 'July 12', NULL, 5, 8, 1, 5, 1, 10),

('Dulce Lopes Pontes', 'dulce-lopes-pontes', 'A Brazilian religious sister known as the ''Mother of the Poor'' who built hospitals, orphanages, and schools for the destitute.', 'St. Dulce Lopes Pontes, known as Irmã Dulce, was a Brazilian Franciscan sister who devoted her life to serving the poorest people of Salvador, Bahia. She transformed an abandoned fish market into a hospital, founded schools, orphanages, and health centers. She was nominated for the Nobel Peace Prize and was canonized by Pope Francis in 2019.', 'If there is a problem, there is a solution. If there is no solution, then there is no problem.', 'August 13', NULL, 1, 1, 2, 10, 1, 6),

('Nino of Georgia', 'nino-of-georgia', 'The ''Enlightener of Georgia'' who brought Christianity to the ancient kingdom of Iberia (modern Georgia) in the 4th century.', 'St. Nino was a young woman from Cappadocia who traveled to the ancient kingdom of Iberia (modern Georgia) as a captive or pilgrim. Through her prayers and miracles, she converted Queen Nana and eventually King Mirian III, leading to the declaration of Christianity as the state religion. She is revered as equal to the apostles in the Georgian Orthodox Church.', 'Christ is the light of all nations.', 'January 14', NULL, 1, 1, 1, 8, 1, 10),

('Notburga', 'notburga', 'A Tyrolean peasant servant known for her charity to the poor and her defense of workers'' right to rest on Sundays.', 'St. Notburga was a Tyrolean kitchen servant who gave leftover food to the poor against her employer''s wishes. When fired, she worked for a farmer who agreed to let her attend Mass and rest on Sundays. According to legend, when he reneged on this promise, her sickle floated in the air, proving God''s will for Sunday rest.', 'Give to the poor what belongs to God.', 'September 14', NULL, 5, 5, 1, 8, 1, 10),

('Boris of Bulgaria', 'boris-of-bulgaria', 'The Khan and later Tsar of Bulgaria who converted to Christianity and established it as the state religion.', 'St. Boris I was the ruler of Bulgaria who converted to Christianity around 864 and established it as the state religion. He navigated complex diplomatic relationships between Rome and Constantinople to secure autonomy for the Bulgarian Church. He eventually abdicated and retired to a monastery, but emerged briefly to prevent his son from restoring paganism.', 'A nation united in faith is invincible.', 'May 2', NULL, 1, 1, 2, 10, 1, 6),

('Teresa of the Andes', 'teresa-of-the-andes', 'A Chilean Discalced Carmelite nun who died at 19, known for her profound joy and mystical union with God.', 'St. Teresa of the Andes, born Juanita Fernández Solar, was a Chilean girl from a wealthy family who entered the Discalced Carmelite convent in Los Andes at age 18. She lived only 11 months as a Carmelite before dying of typhus, but her diary and letters reveal an extraordinary mystical life. She was the first Chilean saint.', 'God is infinite joy.', 'July 13', NULL, 2, 1, 1, 1, 6, 10),

('Ezequiel Moreno', 'ezequiel-moreno', 'A Spanish Augustinian Recollect bishop who served extensively in the Philippines and Colombia, known for his pastoral zeal.', 'St. Ezequiel Moreno was a Spanish Augustinian Recollect who served as a missionary in the Philippines before becoming Bishop of Pasto, Colombia. He was known for his tireless pastoral visitations of remote communities, often traveling by mule through dangerous terrain. He died of cancer and offered his sufferings for his diocese.', 'Liberalism is sin.', 'August 19', NULL, 2, 1, 1, 6, 1, 10),

('Lidwina of Schiedam', 'lidwina-of-schiedam', 'A Dutch mystic who suffered a skating accident at 15 and spent the rest of her life bedridden, offering her suffering for others.', 'St. Lidwina of Schiedam was a Dutch woman who, at age 15, broke a rib while ice skating and never recovered. For the remaining 38 years of her life, she was bedridden with progressively worsening ailments. She transformed her suffering into a powerful spiritual ministry, experiencing mystical visions and offering her pain for the souls in purgatory.', 'My suffering is my prayer.', 'April 14', NULL, 2, 2, 1, 4, 1, 10),

('Lorenzo Ruiz', 'lorenzo-ruiz', 'The first Filipino saint, a lay missionary and calligrapher who was martyred in Japan for refusing to renounce Christianity.', 'St. Lorenzo Ruiz was a Chinese-Filipino binukot (altar server) and calligrapher from Manila who fled to Japan after being falsely accused of a crime. He was captured during the Tokugawa persecution and subjected to the water torture of tsurushi. He refused to renounce his faith and died a martyr, becoming the first Filipino saint.', 'I am a Christian, and I will die for God.', 'September 28', NULL, 1, 2, 1, 10, 1, 6),

('Paul Miki', 'paul-miki', 'A Japanese Jesuit seminarian and one of the Twenty-Six Martyrs crucified in Nagasaki during the persecution of Christians.', 'St. Paul Miki was a Japanese Jesuit scholastic from a wealthy family who was one of the Twenty-Six Martyrs of Japan. He was arrested during the persecution under Toyotomi Hideyoshi and forced to march 600 miles to Nagasaki in winter. He preached his most powerful sermon from the cross before being killed by lance thrusts.', 'I have been living as a Japanese and I am dying as a Japanese. This land of mine is the cradle for Christianity.', 'February 6', NULL, 1, 2, 1, 10, 1, 6),

('Augustine Zhao Rong', 'augustine-zhao-rong', 'A Chinese diocesan priest who was one of 120 Martyrs of China killed during various persecutions from the 17th to 20th centuries.', 'St. Augustine Zhao Rong was a Chinese soldier who guarded a bishop being transported to execution. So moved by the bishop''s courage, he converted to Christianity and eventually became a diocesan priest. He was arrested and tortured to death during the Qing Dynasty''s persecution of Christians.', 'I was once a persecutor, now I die for the faith I persecuted.', 'July 9', NULL, 1, 2, 1, 10, 1, 6),

('Charles Lwanga', 'charles-lwanga', 'The chief of the Uganda Martyrs, a young courtier who protected pages from the king''s abuse and was burned alive for his faith.', 'St. Charles Lwanga was a young page in the court of King Mwanga II of Buganda who became chief of the royal pages. He protected younger pages from the king''s sexual abuse and secretly baptized them. When the king ordered the execution of all Christian pages, Charles led them in refusing to renounce their faith. He was burned alive at Namugongo.', 'A well that has water cannot dry up.', 'June 3', NULL, 1, 1, 1, 10, 1, 3),

('Gianna Beretta Molla', 'gianna-beretta-molla', 'An Italian pediatrician who sacrificed her life to save her unborn child, choosing to continue a dangerous pregnancy rather than have an abortion.', 'St. Gianna Beretta Molla was an Italian pediatrician and mother of four. During her fourth pregnancy, she was diagnosed with a uterine fibroma. She chose to have the tumor removed while preserving the pregnancy, refusing a hysterectomy or abortion. She gave birth to a healthy daughter but died a week later from complications.', 'The life of the child is more important than mine.', 'April 28', NULL, 1, 2, 1, 10, 1, 6),

('Josephine Bakhita', 'josephine-bakhita', 'A Sudanese woman who was kidnapped into slavery as a child, eventually found freedom and faith, and became a Canossian nun in Italy.', 'St. Josephine Bakhita was kidnapped from her village in Darfur at age seven and sold into slavery multiple times. After being bought by an Italian consul, she was brought to Italy where she encountered Christianity. She entered the Canossian Sisters and spent the rest of her life serving God with extraordinary gentleness and joy.', 'If I were to meet those who kidnapped me, and even those who tortured me, I would kneel and kiss their hands.', 'February 8', NULL, 1, 1, 1, 1, 1, 10),

('Moses the Black', 'moses-the-black', 'A former Ethiopian gang leader and robber who converted to Christianity and became one of the greatest Desert Fathers.', 'St. Moses the Black was an Ethiopian servant dismissed for theft who became the leader of a gang of bandits. After hiding from authorities in a desert monastery, he was so moved by the monks'' way of life that he converted and became a monk himself, eventually leading 75 disciples.', 'Go, sit in your cell, and your cell will teach you everything.', 'August 28', NULL, 3, 7, 10, 10, 1, 7),

('Tekle Haymanot', 'tekle-haymanot', 'The most celebrated Ethiopian saint, a monk and missionary who spread Christianity throughout southern Ethiopia.', 'St. Tekle Haymanot was an Ethiopian monk who founded the monastery of Debre Libanos, which became the most important monastic center in Ethiopian Christianity. He is credited with converting many pagan communities and is venerated as a national saint.', 'Prayer is the breath of the soul.', 'August 24', NULL, 1, 1, 3, 5, 1, 10),

('Frumentius', 'frumentius', 'The Apostle of Ethiopia who brought Christianity to the ancient kingdom of Aksum in the 4th century.', 'St. Frumentius was a young Christian from Tyre who was shipwrecked on the Ethiopian coast and taken to the court of Aksum. He rose to a position of influence, introduced Christianity to the kingdom, and was later consecrated as the first bishop of Aksum by St. Athanasius of Alexandria.', 'The light of Christ shines even in the most distant lands.', 'October 27', NULL, 1, 1, 3, 5, 1, 10),

('Mary of Egypt', 'mary-of-egypt', 'A 5th-century penitent who spent 47 years in the desert doing penance after a life of sin in Alexandria.', 'St. Mary of Egypt lived as a prostitute in Alexandria for 17 years before experiencing a dramatic conversion while trying to enter the Church of the Holy Sepulchre in Jerusalem. She spent the remaining 47 years of her life as a hermit in the Jordanian desert, living on herbs and divine grace.', 'An invisible force held me back at the door of the church.', 'April 1', NULL, 1, 1, 1, 1, 1, 10),

('Julia of Corsica', 'julia-of-corsica', 'A North African Christian woman who was sold into slavery and martyred on the island of Corsica for refusing to worship pagan gods.', 'St. Julia was a Christian noblewoman from Carthage who was captured and sold into slavery when the Vandals sacked the city. Despite her enslaved status, she remained devout and was eventually crucified on the island of Corsica by a pagan governor for refusing to participate in idol worship.', 'My freedom is in Christ alone.', 'May 22', NULL, 1, 2, 1, 10, 1, 6),

('Colette of Corbie', 'colette-of-corbie', 'A French reformer who restored the Rule of St. Clare to its original strictness, founding 17 convents across Europe.', 'St. Colette was a French Franciscan nun who lived as an anchoress before receiving a vision from St. Francis commanding her to reform the Poor Clares. She traveled across Europe founding and reforming convents, restoring the original austerity of the order. She founded 17 new convents and reformed numerous existing ones.', 'If there be a true way that leads to the Everlasting Kingdom, it is most certainly through suffering.', 'March 6', NULL, 3, 5, 3, 10, 1, 5),

('Bernadette Soubirous', 'bernadette-soubirous', 'A poor French girl who received 18 apparitions of the Blessed Virgin Mary at the grotto of Lourdes.', 'St. Bernadette Soubirous was a sickly, impoverished girl from Lourdes, France, who in 1858 experienced 18 visions of the Blessed Virgin Mary at the grotto of Massabielle. The spring she uncovered during the apparitions became a site of miraculous healings. She later became a nun and lived a hidden life of prayer and suffering.', 'I do not promise to make you happy in this life, but in the next.', 'April 16', NULL, 3, 5, 1, 1, 1, 10),

('Jadwiga of Poland', 'jadwiga-of-poland', 'A medieval Queen of Poland who used her wealth to restore universities, found hospitals, and unite Poland and Lithuania through her marriage.', 'St. Jadwiga was crowned King (not Queen) of Poland at age 10. She sacrificed her personal happiness by breaking her engagement to marry the pagan Grand Duke of Lithuania, leading to the Christianization of Lithuania. She funded the restoration of the Kraków Academy (now Jagiellonian University) and was beloved for her personal charity.', 'I pledge all my jewels for the glory of God and the education of youth.', 'July 17', NULL, 1, 3, 10, 10, 1, 5),

('Olga of Kyiv', 'olga-of-kyiv', 'A Viking-era princess who became the first ruler of Kyivan Rus'' to convert to Christianity, paving the way for the Christianization of Eastern Europe.', 'St. Olga was the wife of Igor I of Kyiv, and after his murder, she ruled as regent for their young son. She was baptized in Constantinople and spent her life trying to convert her people. Although she did not succeed in her lifetime, her grandson Vladimir eventually Christianized all of Kyivan Rus''.', 'I have known God and I rejoice.', 'July 11', NULL, 1, 1, 10, 5, 1, 8),

('Elias of the Carmelites', 'elias-of-the-carmelites', 'The Old Testament prophet who defended the worship of God against the priests of Baal and is considered the spiritual father of the Carmelite Order.', 'The prophet Elijah is one of the most dramatic figures in the Old Testament. He challenged 450 prophets of Baal on Mount Carmel, was fed by ravens, raised the dead, and was taken up to heaven in a chariot of fire. The Carmelite Order traces its spiritual lineage to Elijah and the hermits who lived on Mount Carmel.', 'As the Lord lives, before whom I stand.', 'July 20', NULL, 1, 1, 1, 8, 1, 10),

('Maroun', 'maroun', 'A 5th-century hermit whose followers founded the Maronite Church, the largest Christian community in Lebanon.', 'St. Maroun was a hermit monk who lived on a mountain in Syria. He was renowned for his healing gifts and spiritual counsel, attracting many followers. After his death, his disciples formed a distinct community that would become the Maronite Church, which remains the spiritual heart of Lebanese Christianity.', 'The mountain is my cathedral.', 'February 9', NULL, 1, 1, 3, 5, 1, 10),

('Rafqa', 'rafqa', 'A Lebanese Maronite nun who voluntarily asked God for suffering and endured blindness and crippling pain with extraordinary joy.', 'St. Rafqa (Rebecca) was a Lebanese Maronite nun who, after years of teaching and religious life, prayed to share in the sufferings of Christ. She soon went blind and became paralyzed, enduring 29 years of intense suffering with remarkable joy and patience. She was canonized by Pope Benedict XVI in 2001.', 'I asked my Lord for suffering and He gave it to me abundantly.', 'March 23', NULL, 3, 3, 1, 5, 8, 10),

('Nektarios of Aegina', 'nektarios-of-aegina', 'A Greek Orthodox bishop who was unjustly exiled and slandered, yet responded with humility and built a convent on the island of Aegina.', 'St. Nektarios was a Greek Orthodox bishop who was falsely accused of corruption and stripped of his position. Rather than fight back, he accepted his disgrace with humility and devoted himself to writing, teaching, and building the Holy Trinity Convent on the island of Aegina. He is one of the most beloved modern Greek saints.', 'Love all people equally.', 'November 9', NULL, 3, 5, 1, 1, 1, 10),

('Herman of Alaska', 'herman-of-alaska', 'The first Orthodox saint canonized in the Americas, a Russian monk who defended Native Alaskans from exploitation.', 'St. Herman was a Russian Orthodox monk who arrived in Alaska in 1794 as part of a missionary group. He spent over 40 years on Spruce Island, protecting the native Aleut people from exploitation by the Russian-American Company, establishing schools and an orphanage, and living a life of extreme simplicity.', 'From this day, from this hour, let us love God above all.', 'December 13', NULL, 3, 5, 1, 1, 1, 10),

('Nina Martyr of Georgia', 'nina-martyr-of-georgia', 'A teenage Georgian girl martyred in the Soviet purges for refusing to remove her cross and deny Christ.', 'St. Nina was a young Georgian Christian woman who was arrested during Stalin''s Great Purge for her religious activities. She was ordered to renounce her faith and remove her cross necklace. When she refused, she was tortured and executed. She was glorified as a new martyr by the Georgian Orthodox Church.', 'I cannot remove my cross.', 'December 15', NULL, 1, 1, 1, 10, 1, 3),

('Mesrop Mashtots', 'mesrop-mashtots', 'An Armenian monk who invented the Armenian alphabet to translate the Bible and preserve Armenian Christian culture.', 'St. Mesrop Mashtots was an Armenian monk, theologian, and linguist who created the Armenian alphabet around 405 AD. His invention allowed the Bible and liturgical texts to be translated into Armenian, preserving Armenian Christian identity and culture under foreign domination for centuries.', 'To know the letters is to know God''s Word.', 'February 17', NULL, 1, 1, 8, 1, 1, 10),

('Gregory the Illuminator', 'gregory-the-illuminator', 'The patron saint of Armenia who converted King Tiridates III, making Armenia the first nation to adopt Christianity as a state religion in 301 AD.', 'St. Gregory the Illuminator was imprisoned in a pit for 13 years by King Tiridates III of Armenia for refusing to worship pagan gods. When the king fell gravely ill, Gregory was released to pray for him. The king was healed and converted, making Armenia the first Christian nation in 301 AD.', 'Armenia shall be a light to the nations.', 'September 30', NULL, 1, 1, 2, 10, 1, 6),

('Daniel Comboni', 'daniel-comboni', 'An Italian missionary bishop who dedicated his life to Africa, founding missionary congregations for the evangelization of Central Africa.', 'St. Daniel Comboni was an Italian priest who devoted his entire life to the evangelization of Central Africa, particularly Sudan. He founded the Comboni Missionaries and the Comboni Missionary Sisters, and became the first Catholic bishop of Central Africa. He died of exhaustion and fever in Khartoum at age 50.', 'Africa or death!', 'October 10', NULL, 1, 3, 3, 10, 1, 8),

('Brigid of Kildare', 'brigid-of-kildare', 'One of Ireland''s three patron saints, an abbess who founded one of the most important monasteries in Ireland.', 'St. Brigid of Kildare was one of the most remarkable women in Irish history. She founded the monastery of Kildare, which became one of the most prestigious in Ireland, and established a tradition of hospitality and learning. She is one of Ireland''s three patron saints alongside St. Patrick and St. Columba.', 'I would like a great lake of beer for the King of Kings.', 'February 1', NULL, 1, 1, 3, 5, 1, 10),

('Bakhita of Olossio', 'bakhita-of-olossio', 'A Nigerian convert and catechist who was one of the first indigenous African religious sisters in West Africa.', 'St. Bakhita of Olossio was a Nigerian woman who converted to Christianity through the work of European missionaries. She became a catechist and later joined a religious community, dedicating her life to teaching the faith to her people and caring for the sick in her village.', 'God called me from the darkness of my ancestors'' ways.', 'September 15', NULL, 1, 1, 1, 8, 1, 10),

('John of Damascus', 'john-of-damascus', 'A Doctor of the Church and the last of the Church Fathers, who defended the veneration of icons during the Iconoclast controversy.', 'St. John of Damascus was a Syrian Christian monk and theologian who served as a financial officer in the Islamic Umayyad Caliphate before becoming a monk. He wrote extensively against iconoclasm and composed some of the most important theological treatises of the Eastern Church, including ''The Fount of Knowledge.''', 'I do not worship matter, but the Creator of matter.', 'December 4', NULL, 2, 1, 10, 5, 1, 3),

('Hilda of Whitby', 'hilda-of-whitby', 'An Anglo-Saxon abbess who presided over the famous Synod of Whitby and ran one of the most important monasteries in England.', 'St. Hilda was a Northumbrian princess who became abbess of the double monastery of Whitby. Under her leadership, five future bishops were trained, and the monastery became one of England''s greatest centers of learning. She hosted the Synod of Whitby in 664, which determined the date of Easter for the English Church.', 'All who knew her called her Mother.', 'November 17', NULL, 1, 1, 10, 3, 1, 3),

('Genevieve', 'genevieve', 'The patron saint of Paris who rallied the city''s defense against Attila the Hun and organized relief during a siege.', 'St. Genevieve was a Gallo-Roman woman who dedicated her life to God at a young age. When Attila the Hun threatened Paris in 451, she rallied the citizens to pray rather than flee, and the Huns bypassed the city. She later organized a convoy of boats to bring food to Paris during a Frankish siege.', 'Let us pray and God will deliver us.', 'January 3', NULL, 1, 1, 2, 10, 1, 6),

('Elżbieta Hesselblad', 'el-bieta-hesselblad', 'A Swedish convert who restored the Bridgettine Order and sheltered Jews during the Holocaust in Rome.', 'St. Elżbieta Hesselblad was born Lutheran in Sweden, emigrated to America as a nurse, and converted to Catholicism. She refounded the Bridgettine Order and during World War II, hid Jewish families in her convent in Rome, saving at least 12 lives. She was canonized by Pope Francis in 2016.', 'Unity among Christians is the will of God.', 'June 4', NULL, 1, 1, 1, 8, 1, 10),

('Damien of Molokai', 'damien-of-molokai', 'A Belgian priest who volunteered to serve the leper colony on Molokai, Hawaii, eventually contracting and dying of the disease himself.', 'St. Damien de Veuster was a Belgian priest who volunteered to serve the isolated leper colony on the island of Molokai in Hawaii. He built houses, hospitals, and churches, and personally cared for the sick. After 16 years of service, he contracted leprosy himself and died among the people he loved.', 'I make myself a leper with the lepers to gain all to Jesus Christ.', 'May 10', NULL, 1, 8, 1, 10, 1, 4),

('Marianne Cope', 'marianne-cope', 'A German-American Franciscan sister who continued St. Damien''s work among the lepers of Molokai for over 30 years without ever contracting the disease.', 'St. Marianne Cope was a German-born American Franciscan sister who arrived in Hawaii in 1883 to manage hospitals and schools. After St. Damien''s death, she took over the care of the Molokai leper settlement, serving for over 30 years. Remarkably, she never contracted the disease despite constant close contact.', 'I am not afraid of any disease.', 'January 23', NULL, 1, 10, 1, 10, 1, 10),

('Pio of Pietrelcina', 'pio-of-pietrelcina', 'An Italian Capuchin friar who bore the stigmata for 50 years and was renowned for his mystical gifts of bilocation, prophecy, and reading souls.', 'St. Padre Pio was an Italian Capuchin friar who received the stigmata in 1918 and bore the wounds of Christ on his hands, feet, and side for 50 years. He was known for his long hours in the confessional, his ability to read souls, and reports of bilocation and other mystical phenomena.', 'Pray, hope, and don''t worry.', 'September 23', NULL, 3, 5, 1, 1, 1, 10),

('Faustina Kowalska', 'faustina-kowalska', 'A Polish nun who received visions of Jesus and promoted the Divine Mercy devotion, which became one of the most popular Catholic devotions worldwide.', 'St. Faustina Kowalska was a Polish nun of the Congregation of the Sisters of Our Lady of Mercy who received private revelations from Jesus about Divine Mercy. She recorded these visions in her diary, which became the basis for the Divine Mercy devotion. She was canonized by Pope John Paul II in 2000.', 'Jesus, I trust in You.', 'October 5', NULL, 3, 5, 1, 1, 1, 10),

('John Henry Newman', 'john-henry-newman', 'An Anglican theologian and cardinal whose conversion to Catholicism shook Victorian England and whose writings profoundly influenced the Second Vatican Council.', 'St. John Henry Newman was the most prominent Anglican convert to Catholicism in 19th-century England. A leading intellectual and Oxford professor, his conversion caused a national sensation. He was made a cardinal and wrote extensively on the development of doctrine, the nature of faith, and education.', 'To live is to change, and to be perfect is to have changed often.', 'October 9', NULL, 1, 1, 8, 1, 1, 10),

('Jeanne Jugan', 'jeanne-jugan', 'A French laywoman who founded the Little Sisters of the Poor to care for destitute elderly people.', 'St. Jeanne Jugan founded the Little Sisters of the Poor after bringing a blind, paralyzed elderly woman into her own home. Her work grew rapidly as she begged door-to-door to support her growing community of elderly residents. Despite founding the order, she was unjustly removed from leadership and spent her last 27 years in obscurity.', 'It is so good to be poor, to have nothing, to depend on God for everything.', 'August 30', NULL, 3, 7, 1, 1, 10, 10),

('Sharbel Makhlouf', 'sharbel-makhlouf', 'Feast of the finding of St. Charbel''s incorrupt body, celebrated in some Maronite traditions.', 'This feast commemorates the discovery of St. Charbel''s incorrupt body when his tomb was opened and a mysterious light was seen above it. His body had been buried for months but showed no signs of decomposition, leading to increased veneration and eventually his beatification and canonization.', 'The silence of God is the loudest sound.', 'December 24', NULL, 1, 1, 1, 1, 1, 10),

('Oscar Arnulfo Romero', 'oscar-arnulfo-romero', 'Archbishop of San Salvador who was assassinated while saying Mass for his outspoken defense of the poor during El Salvador''s civil war.', 'St. Oscar Romero was a quiet, conservative priest who was appointed Archbishop of San Salvador expecting he would not challenge the status quo. Instead, after witnessing the murder of his friend Fr. Rutilio Grande, he became the most vocal defender of the poor in Latin America. He was shot dead while celebrating Mass in 1980.', 'If they kill me, I shall arise in the Salvadoran people.', 'March 24', NULL, 1, 2, 1, 10, 1, 6),

('Toribio Romo González', 'toribio-romo-gonz-lez', 'A Mexican priest martyred during the Cristero War who has become the unofficial patron of migrants crossing the US-Mexico border.', 'St. Toribio Romo González was a young Mexican priest who was martyred during the Cristero War at age 28. In recent decades, countless Mexican and Central American migrants have reported seeing a mysterious young man who helped them cross the desert safely — they later identified him from pictures as St. Toribio.', 'Do not be afraid', 'May 25', NULL, 1, 2, 1, 10, 1, 6),

('María Guadalupe García Zavala', 'mar-a-guadalupe-garc-a-zavala', 'A Mexican co-foundress who sheltered persecuted priests and the Archbishop of Guadalajara during the Cristero War.', 'St. María Guadalupe García Zavala co-founded the Handmaids of St. Margaret Mary to serve the sick and poor. During the Cristero War, she risked her life by hiding persecuted priests and even the Archbishop of Guadalajara in her hospital. She was canonized by Pope Francis in 2013.', 'Charity and suffering go hand in hand.', 'June 24', NULL, 1, 1, 2, 10, 1, 6);

-- Total: 495 new saints
